/**
 * Tangible Tag Detection Utility
 *
 * Detects and analyzes Tangible template tags in content
 */

/**
 * List of common Tangible tags to detect
 */
export const TANGIBLE_TAGS = [
  'Loop',
  'Field',
  'If',
  'Template',
  'Format',
  'Date',
  'List',
  'Set',
  'Get',
  'User',
  'Term',
  'Taxonomy',
  'Menu',
  'Post',
  'Attachment',
  'Comment',
  'Option',
  'Site',
  'Math',
  'Random',
  'Length',
  'Sort',
  'Filter',
  'Map',
  'Join',
  'Split',
  'Replace',
  'Trim',
  'Upper',
  'Lower',
  'Capitalize',
] as const;

export type TangibleTag = (typeof TANGIBLE_TAGS)[number];

/**
 * Information about detected Tangible tag
 */
export interface DetectedTag {
  tag: string;
  fullMatch: string;
  position: number;
  attributes?: string;
}

/**
 * Result of Tangible tag detection
 */
export interface TangibleDetectionResult {
  hasTangibleTags: boolean;
  detectedTags: DetectedTag[];
  tagCounts: Record<string, number>;
  totalTags: number;
}

/**
 * Create regex pattern for detecting Tangible tags
 */
export function createTangibleTagRegex(): RegExp {
  // Create pattern that matches opening and closing Tangible tags
  const tagPattern = TANGIBLE_TAGS.join('|');

  // Match patterns like:
  // <Loop>...</Loop>
  // <Field name="title" />
  // <If condition="...">...</If>
  return new RegExp(
    `<(${tagPattern})(?:\\s+[^>]*)?(?:/>|>[\\s\\S]*?</\\1>)`,
    'gi'
  );
}

/**
 * Create regex pattern for self-closing Tangible tags
 */
export function createSelfClosingTangibleTagRegex(): RegExp {
  const tagPattern = TANGIBLE_TAGS.join('|');
  return new RegExp(`<(${tagPattern})(?:\\s+[^>]*)?\\/?>`, 'gi');
}

/**
 * Detect Tangible tags in content
 */
// Regex for extracting attributes from tags
const ATTRIBUTE_REGEX = /<\w+\s+([^>]+?)(?:\/>|>)/;
const TAG_REGEX = /^[A-Z]/;

export function detectTangibleTags(content: string): TangibleDetectionResult {
  const detectedTags: DetectedTag[] = [];
  const tagCounts: Record<string, number> = {};

  // Use the comprehensive regex to find all Tangible tags
  const regex = createTangibleTagRegex();
  let match: RegExpExecArray | null = null;

  // biome-ignore lint/suspicious/noAssignInExpressions: Standard regex exec pattern
  while ((match = regex.exec(content)) !== null) {
    const [fullMatch, tagName] = match;

    // Only treat as Tangible if the matched tag name starts with uppercase
    // This avoids false positives on native HTML tags like <option>, <map>, <menu>
    if (!TAG_REGEX.test(tagName)) {
      continue;
    }

    // Extract attributes if present (simplified extraction)
    const attributeMatch = fullMatch.match(ATTRIBUTE_REGEX);
    const attributes = attributeMatch ? attributeMatch[1].trim() : undefined;

    detectedTags.push({
      tag: tagName,
      fullMatch,
      position: match.index,
      attributes,
    });

    // Count occurrences
    tagCounts[tagName] = (tagCounts[tagName] || 0) + 1;
  }

  return {
    hasTangibleTags: detectedTags.length > 0,
    detectedTags,
    tagCounts,
    totalTags: detectedTags.length,
  };
}

/**
 * Get a user-friendly description of detected tags
 */
export function getTangibleTagsDescription(
  result: TangibleDetectionResult
): string {
  if (!result.hasTangibleTags) {
    return 'No Tangible tags detected';
  }

  const uniqueTags = Object.keys(result.tagCounts);
  const tagList = uniqueTags
    .sort((a, b) => result.tagCounts[b] - result.tagCounts[a]) // Sort by usage count
    .map((tag) => `${tag} (${result.tagCounts[tag]})`)
    .join(', ');

  return `Found ${result.totalTags} Tangible tags: ${tagList}`;
}

/**
 * Check if content contains any Tangible tags (quick check)
 */
export function hasTangibleTags(content: string): boolean {
  // Use the full detection logic to ensure uppercase-only match rule applies
  return detectTangibleTags(content).hasTangibleTags;
}

/**
 * Get list of unique Tangible tags found in content
 */
export function getUniqueTangibleTags(content: string): string[] {
  const result = detectTangibleTags(content);
  return Object.keys(result.tagCounts);
}

/**
 * Estimate complexity of migration based on detected tags
 */
export function estimateMigrationComplexity(
  result: TangibleDetectionResult
): 'simple' | 'moderate' | 'complex' {
  if (!result.hasTangibleTags) {
    return 'simple';
  }

  const complexTags = ['Loop', 'If', 'Template', 'Set', 'Get'];
  const hasComplexTags = result.detectedTags.some((tag) =>
    complexTags.includes(tag.tag)
  );

  if (result.totalTags > 10 || hasComplexTags) {
    return 'complex';
  }
  if (result.totalTags > 5) {
    return 'moderate';
  }
  return 'simple';
}
