/**
 * PHP Execution API
 *
 * KISS principle: Simple PHP code execution
 */

import { apiClient } from './client';

export interface PhpExecuteRequest {
  code: string;
  post_id?: number;
}

export interface PhpExecuteResponse {
  success: boolean;
  output: string;
  error?: string;
}

export const phpApi = {
  /**
   * Execute PHP code and return output
   */
  execute: async (data: PhpExecuteRequest): Promise<PhpExecuteResponse> => {
    const response = await apiClient.post<PhpExecuteResponse>(
      '/php/execute',
      data
    );
    return response;
  },
};
