import type React from 'react';
import type { Message } from '../types/ai-dialog.types';
import { CodeDisplay } from './code-display';

interface MessageBubbleProps {
  message: Message;
  onInsertCode?: (code: string) => void;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({
  message,
  onInsertCode,
}) => {
  const isUser = message.role === 'user';

  return (
    <div className="mb-4">
      <div
        className={`inline-block ${isUser ? 'max-w-[80%]' : 'w-full max-w-4xl'} rounded-lg px-4 py-2 ${
          isUser ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-900'
        }`}
      >
        {message.content && (
          <p className="whitespace-pre-wrap">{message.content}</p>
        )}

        {/* 显示生成的模板代码 */}
        {message.template && (
          <div className="mt-3">
            <div className="mb-2 font-medium text-sm">生成的动态内容代码：</div>
            <CodeDisplay
              code={message.template}
              onInsert={onInsertCode}
              showInsertButton={!!onInsertCode}
            />
          </div>
        )}
      </div>
    </div>
  );
};
