import {
  autocompletion,
  closeBrackets,
  closeBracketsKeymap,
  completionKeymap,
} from '@codemirror/autocomplete';
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands';
import { php } from '@codemirror/lang-php';
import {
  bracketMatching,
  defaultHighlightStyle,
  foldGutter,
  foldKeymap,
  indentOnInput,
  syntaxHighlighting,
} from '@codemirror/language';
import { lintKeymap } from '@codemirror/lint';
import { highlightSelectionMatches, searchKeymap } from '@codemirror/search';
import { Compartment, EditorState } from '@codemirror/state';
import {
  crosshairCursor,
  drawSelection,
  // dropCursor,
  EditorView,
  highlightActiveLine,
  highlightActiveLineGutter,
  highlightSpecialChars,
  keymap,
  lineNumbers,
  rectangularSelection,
} from '@codemirror/view';
import { oneDark } from '@uiw/react-codemirror';
import { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
import { useEditorStore } from '@/store/editor';
import { useCodeHighlight } from '../hooks/use-code-highlight';
import { useCustomHtmlLanguage } from '../hooks/use-custom-html-language';
import type { ElementPosition } from '../types/editor';

interface CodeEditorProps {
  value: string;
  onChange: (value: string) => void;
}

export interface CodeEditorRef {
  highlightPosition: (position: ElementPosition) => void;
  clearHighlight: () => void;
  focus: () => void;
  selectAll: () => void;
  getContent: () => string;
}

const CodeEditor = forwardRef<CodeEditorRef, CodeEditorProps>(
  ({ value, onChange }, ref) => {
    const { highlightExtension, highlightPosition, clearHighlight } =
      useCodeHighlight();
    const customHtmlExtensions = useCustomHtmlLanguage();
    const { setSelection } = useEditorStore();
    const editorRef = useRef<HTMLDivElement>(null);
    const viewRef = useRef<EditorView | null>(null);
    const languageCompartmentRef = useRef(new Compartment());

    // Detect if content has PHP code - use ref to avoid recreating editor
    const hasPhpCodeRef = useRef(false);
    hasPhpCodeRef.current = value.includes('<?php') || value.includes('<?=');

    // Detect current language type
    const currentHasPhp = value.includes('<?php') || value.includes('<?=');
    // Keep a stable reference to HTML extensions so reconfigure doesn't thrash
    const htmlExtensionsRef = useRef(customHtmlExtensions);

    // Create the editor only once; switch language via Compartment
    // biome-ignore lint/correctness/useExhaustiveDependencies: only run once
    useEffect(() => {
      if (!editorRef.current || viewRef.current) {
        return;
      }

      const startState = EditorState.create({
        doc: value,
        extensions: [
          oneDark,
          lineNumbers(),
          highlightActiveLineGutter(),
          highlightSpecialChars(),
          history(),
          foldGutter(),
          drawSelection(),
          // dropCursor(),
          EditorState.allowMultipleSelections.of(true),
          indentOnInput(),
          syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
          bracketMatching(),
          closeBrackets(),
          autocompletion(),
          rectangularSelection(),
          crosshairCursor(),
          highlightActiveLine(),
          highlightSelectionMatches(),
          EditorView.lineWrapping,
          keymap.of([
            ...closeBracketsKeymap,
            ...defaultKeymap,
            ...searchKeymap,
            ...historyKeymap,
            ...foldKeymap,
            ...completionKeymap,
            ...lintKeymap,
          ]),
          highlightExtension,
          languageCompartmentRef.current.of(
            currentHasPhp ? php() : htmlExtensionsRef.current
          ),
          EditorView.updateListener.of((update) => {
            if (update.docChanged) {
              onChange(update.state.doc.toString());
            }

            // Track selection changes
            if (update.selectionSet) {
              const selection = update.state.selection.main;
              if (selection.from !== selection.to) {
                // Text is selected
                const selectedText = update.state.doc.sliceString(
                  selection.from,
                  selection.to
                );
                setSelection(selectedText, selection.from, selection.to);
              } else {
                // Cursor position (no selection)
                // Keep the cursor position instead of clearing
                setSelection('', selection.from, selection.from);
              }
            }
          }),
        ],
      });

      const view = new EditorView({
        state: startState,
        parent: editorRef.current,
      });

      viewRef.current = view;

      return () => {
        view.destroy();
        viewRef.current = null;
      };
    }, []);

    // Reconfigure language only when PHP detection toggles
    useEffect(() => {
      if (!viewRef.current) {
        return;
      }
      const view = viewRef.current;
      const next = currentHasPhp ? php() : htmlExtensionsRef.current;
      view.dispatch({
        effects: languageCompartmentRef.current.reconfigure(next),
      });
    }, [currentHasPhp]);

    useEffect(() => {
      if (viewRef.current && value !== viewRef.current.state.doc.toString()) {
        viewRef.current.dispatch({
          changes: {
            from: 0,
            to: viewRef.current.state.doc.length,
            insert: value,
          },
        });
      }
    }, [value]);

    // Expose methods to parent component
    useImperativeHandle(
      ref,
      () => ({
        highlightPosition: (position: ElementPosition) => {
          if (viewRef.current) {
            highlightPosition(viewRef.current, position);
          }
        },
        clearHighlight: () => {
          if (viewRef.current) {
            clearHighlight(viewRef.current);
          }
        },
        focus: () => {
          if (viewRef.current) {
            viewRef.current.focus();
          }
        },
        selectAll: () => {
          if (viewRef.current) {
            const doc = viewRef.current.state.doc;
            viewRef.current.dispatch({
              selection: { anchor: 0, head: doc.length },
            });
            // 更新 store 中的选中状态
            const content = doc.toString();
            setSelection(content, 0, content.length);
          }
        },
        getContent: () => {
          if (viewRef.current) {
            return viewRef.current.state.doc.toString();
          }
          return '';
        },
      }),
      [highlightPosition, clearHighlight, setSelection]
    );

    return <div className="code-editor" ref={editorRef} />;
  }
);

CodeEditor.displayName = 'CodeEditor';

export default CodeEditor;
