import type React from 'react';
import { useLocalStorage } from '@/hooks/use-local-storage';

interface ProductionModeEducationProps {
  isProductionMode: boolean;
}

export const ProductionModeEducation: React.FC<
  ProductionModeEducationProps
> = ({ isProductionMode }) => {
  const [hasSeenEducation, setHasSeenEducation] = useLocalStorage(
    'zeroy-production-mode-education',
    false
  );

  if (hasSeenEducation || !isProductionMode) {
    return null;
  }

  return (
    <div className="mb-4 border-blue-400 border-l-4 bg-blue-50 p-4">
      <div className="flex">
        <div className="flex-shrink-0">
          <svg
            aria-hidden="true"
            className="h-5 w-5 text-blue-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
            />
          </svg>
        </div>
        <div className="ml-3">
          <h3 className="font-medium text-blue-800 text-sm">生产模式已启用</h3>
          <p className="mt-1 text-blue-700 text-sm">
            您正在使用优化后的CSS。保存任何更改将自动切换到开发模式，
            以确保您的编辑能够正确生效。这是正常行为，无需担心。
          </p>
          <button
            className="mt-2 text-blue-600 text-sm underline transition-colors hover:text-blue-500"
            onClick={() => setHasSeenEducation(true)}
            type="button"
          >
            知道了
          </button>
        </div>
      </div>
    </div>
  );
};
