/**
 * PHP Block Preprocessor
 *
 * Converts PHP blocks to inert script placeholders before DOM parsing
 * to prevent any layout corruption or HTML parsing issues.
 */

export interface PhpBlock {
  id: string;
  startIdx: number; // Position in original content (including comments)
  endIdx: number; // Position in original content (including comments)
  raw: string; // PHP content without comments
  startComment: string;
  endComment: string;
  // Add original content positions for mapping
  originalStartOffset: number; // Start position in original content
  originalEndOffset: number; // End position in original content
}

export interface Replacement {
  id: string;
  rawStart: number;
  rawEnd: number;
  safeStart: number;
  safeEnd: number;
  rawLen: number;
  safeLen: number;
  delta: number;
}

export interface PreprocessResult {
  html: string;
  blocks: Map<string, PhpBlock>;
  replacements: Replacement[];
}

interface Marker {
  type: 'start' | 'end';
  id: string;
  index: number;
  length: number;
  full: string;
}

interface MarkerPair {
  id: string;
  startMarkerIdx: number;
  endMarkerIdx: number;
}

interface ReplacementInfo {
  id: string;
  rawStart: number;
  rawEnd: number;
  placeholder: string;
  block: PhpBlock;
}

/**
 * Safely encode string to Base64
 */
function toBase64(str: string): string {
  try {
    // Handle Unicode properly
    return btoa(unescape(encodeURIComponent(str)));
  } catch {
    // Fallback for edge cases
    // Replace non-ASCII characters with placeholders
    // eslint-disable-next-line no-control-regex
    const ascii = str.replace(/[^\u0020-\u007E]/g, '?');
    return btoa(ascii);
  }
}

/**
 * Safely decode Base64 to string
 */
function fromBase64(base64: string): string {
  try {
    return decodeURIComponent(escape(atob(base64)));
  } catch {
    // Fallback
    return atob(base64);
  }
}

/**
 * Preprocess PHP blocks in HTML string
 * Replaces PHP block markers with inert script placeholders
 */
export function preprocessPhpBlocks(raw: string): PreprocessResult {
  const markers = collectMarkers(raw);
  const pairs = pairMarkers(markers);
  const { blocks, replacementInfo } = buildReplacementEntries(
    raw,
    markers,
    pairs
  );
  const htmlWithPlaceholders = applyReplacements(raw, replacementInfo);
  const replacements = buildReplacementMetadata(
    htmlWithPlaceholders,
    replacementInfo
  );

  return { html: htmlWithPlaceholders, blocks, replacements };
}

function collectMarkers(raw: string): Marker[] {
  const markerRegex =
    /<!--\s*zeroy:block:(start|end):([^:\s>]+)(?:[:\s][^>]*)?\s*-->/g;
  const markers: Marker[] = [];

  let match: RegExpExecArray | null = markerRegex.exec(raw);
  while (match) {
    markers.push({
      type: match[1] as 'start' | 'end',
      id: match[2],
      index: match.index,
      length: match[0].length,
      full: match[0],
    });
    match = markerRegex.exec(raw);
  }

  return markers;
}

function pairMarkers(markers: Marker[]): MarkerPair[] {
  const stack: Array<{ id: string; markerIdx: number }> = [];
  const pairs: MarkerPair[] = [];

  markers.forEach((marker, idx) => {
    if (marker.type === 'start') {
      stack.push({ id: marker.id, markerIdx: idx });
      return;
    }

    for (let s = stack.length - 1; s >= 0; s--) {
      if (stack[s].id === marker.id) {
        const startItem = stack.splice(s, 1)[0];
        pairs.push({
          id: marker.id,
          startMarkerIdx: startItem.markerIdx,
          endMarkerIdx: idx,
        });
        break;
      }
    }
  });

  return pairs;
}

function buildReplacementEntries(
  raw: string,
  markers: Marker[],
  pairs: MarkerPair[]
): { blocks: Map<string, PhpBlock>; replacementInfo: ReplacementInfo[] } {
  const blocks = new Map<string, PhpBlock>();
  const replacementInfo: ReplacementInfo[] = [];

  for (const pair of pairs) {
    const startMarker = markers[pair.startMarkerIdx];
    const endMarker = markers[pair.endMarkerIdx];

    const contentStart = startMarker.index + startMarker.length;
    const contentEnd = endMarker.index;
    const phpContent = raw.slice(contentStart, contentEnd);

    const block: PhpBlock = {
      id: pair.id,
      startIdx: startMarker.index,
      endIdx: endMarker.index + endMarker.length,
      raw: phpContent,
      startComment: startMarker.full,
      endComment: endMarker.full,
      originalStartOffset: startMarker.index,
      originalEndOffset: endMarker.index + endMarker.length,
    };

    blocks.set(pair.id, block);

    replacementInfo.push({
      id: pair.id,
      rawStart: startMarker.index,
      rawEnd: endMarker.index + endMarker.length,
      placeholder: createPlaceholder(pair.id, phpContent),
      block,
    });
  }

  return { blocks, replacementInfo };
}

function applyReplacements(raw: string, info: ReplacementInfo[]): string {
  const replacementOrder = [...info].sort((a, b) => b.rawStart - a.rawStart);

  let html = raw;
  for (const entry of replacementOrder) {
    html =
      html.slice(0, entry.rawStart) +
      entry.placeholder +
      html.slice(entry.rawEnd);
  }

  return html;
}

function buildReplacementMetadata(
  html: string,
  info: ReplacementInfo[]
): Replacement[] {
  const replacements: Replacement[] = [];
  const replacementsByStart = [...info].sort((a, b) => a.rawStart - b.rawStart);

  for (const entry of replacementsByStart) {
    const rawLen = entry.rawEnd - entry.rawStart;
    const safeLen = entry.placeholder.length;
    const delta = rawLen - safeLen;

    let safeStart = html.indexOf(entry.placeholder);
    if (safeStart === -1) {
      const attrNeedle = `data-block-id="${entry.id}"`;
      const attrIndex = html.indexOf(attrNeedle);
      if (attrIndex !== -1) {
        safeStart = html.lastIndexOf('<script', attrIndex);
      }
    }
    if (safeStart === -1) {
      safeStart = entry.rawStart;
    }
    const safeEnd = safeStart + safeLen;

    replacements.push({
      id: entry.id,
      rawStart: entry.rawStart,
      rawEnd: entry.rawEnd,
      safeStart,
      safeEnd,
      rawLen,
      safeLen,
      delta,
    });
  }

  replacements.sort((a, b) => a.safeStart - b.safeStart);
  return replacements;
}

/**
 * Create an inert script placeholder for a PHP block
 */
function createPlaceholder(id: string, content: string): string {
  const base64Content = toBase64(content);

  // Use script element with custom type - completely inert and allowed anywhere
  return `<script type="application/x-zeroy-php" data-block-id="${id}" data-zeroy-php-placeholder>${base64Content}</script>`;
}

/**
 * Build a mapper to convert safe positions to raw positions
 */
export function buildSafeToRawMapper(replacements: Replacement[]) {
  // Build prefix sum array for efficient delta calculation
  const prefixDeltas = new Array(replacements.length + 1).fill(0);
  for (let i = 0; i < replacements.length; i++) {
    prefixDeltas[i + 1] = prefixDeltas[i] + replacements[i].delta;
  }

  // Calculate cumulative delta before a safe position
  function sumDeltaBefore(safePos: number): number {
    // Binary search for first replacement with safeStart > safePos
    let left = 0;
    let right = replacements.length;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (replacements[mid].safeStart > safePos) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }
    return prefixDeltas[left];
  }

  // Map a single safe position to raw position
  function mapPosition(safePos: number): number {
    // Check if position falls within a replacement
    for (const rep of replacements) {
      if (safePos >= rep.safeStart && safePos <= rep.safeEnd) {
        // Position is within a PHP block placeholder - return start of PHP block
        return rep.rawStart;
      }
    }
    // Position is in regular content - add cumulative delta
    return safePos + sumDeltaBefore(safePos);
  }

  // Map a safe range to raw range
  function mapRange(
    safeStart: number,
    safeEnd: number
  ): { rawStart: number; rawEnd: number } {
    let rawStart = mapPosition(safeStart);
    let rawEnd = mapPosition(safeEnd);

    // Expand range if it overlaps with any PHP blocks
    for (const rep of replacements) {
      if (safeStart <= rep.safeEnd && safeEnd >= rep.safeStart) {
        // Range overlaps with this PHP block - expand to include entire block
        rawStart = Math.min(rawStart, rep.rawStart);
        rawEnd = Math.max(rawEnd, rep.rawEnd);
      }
    }

    return { rawStart, rawEnd };
  }

  return { mapPosition, mapRange };
}

/**
 * Restore PHP blocks from preprocessed HTML
 * This is the reverse operation of preprocessPhpBlocks
 */
export function restorePhpBlocks(html: string): string {
  // Pattern to match our placeholders
  const placeholderRegex =
    /<script\s+type="application\/x-zeroy-php"\s+data-block-id="([^"]+)"[^>]*>([^<]*)<\/script>/g;

  let restored = html;

  // Collect all placeholders first
  const placeholders: Array<{
    index: number;
    length: number;
    id: string;
    base64: string;
  }> = [];

  let match: RegExpExecArray | null = placeholderRegex.exec(html);
  while (match !== null) {
    placeholders.push({
      index: match.index,
      length: match[0].length,
      id: match[1],
      base64: match[2],
    });
    match = placeholderRegex.exec(html);
  }

  // Replace from end to start
  placeholders.sort((a, b) => b.index - a.index);

  for (const ph of placeholders) {
    const content = fromBase64(ph.base64);
    const original = `<!--zeroy:block:start:${ph.id}:type=php-->${content}<!--zeroy:block:end:${ph.id}-->`;

    restored =
      restored.slice(0, ph.index) +
      original +
      restored.slice(ph.index + ph.length);
  }

  // Restore HTMX attributes
  restored = restored.replace(/\bdata-preview-hx-([a-z-]+)(\s*=)/gi, 'hx-$1$2');

  return restored;
}

/**
 * Find all PHP block placeholders in a DOM element
 */
export function findPhpPlaceholders(
  root: HTMLElement
): NodeListOf<HTMLScriptElement> {
  return root.querySelectorAll('script[type="application/x-zeroy-php"]');
}

/**
 * Get block info from a placeholder element
 */
export function getBlockFromPlaceholder(
  script: HTMLScriptElement
): PhpBlock | null {
  const id = script.dataset.blockId;
  const base64 = script.textContent || '';

  if (!(id && base64)) {
    return null;
  }

  try {
    const raw = fromBase64(base64);
    return {
      id,
      startIdx: 0, // These will be set during restore if needed
      endIdx: 0,
      raw,
      startComment: `<!--zeroy:block:start:${id}:type=php-->`,
      endComment: `<!--zeroy:block:end:${id}-->`,
      originalStartOffset: 0,
      originalEndOffset: 0,
    };
  } catch {
    return null;
  }
}
