import { type DefaultTreeAdapterTypes, parse, serialize } from 'parse5';

type ChildNode = DefaultTreeAdapterTypes.ChildNode;
type Document = DefaultTreeAdapterTypes.Document;
type Element = DefaultTreeAdapterTypes.Element;

import type { ElementPosition } from '../../types';

export interface ElementMapping {
  elementId: string;
  tagName: string;
  position: ElementPosition;
  attributes: Record<string, string>;
}

export class HtmlPositionMapper {
  private elementMap: Map<string, ElementMapping> = new Map();
  private idCounter = 0;
  private idPrefix: string;

  constructor(idPrefix = 'element-') {
    this.idPrefix = idPrefix;
  }

  parseHtml(html: string): {
    document: Document;
    mappings: Map<string, ElementMapping>;
  } {
    this.elementMap.clear();
    this.idCounter = 0;

    const document = parse(html, {
      sourceCodeLocationInfo: true,
    });

    this.traverseNode(document);

    return {
      document,
      mappings: new Map(this.elementMap),
    };
  }

  private traverseNode(node: ChildNode | Document, parentPath = ''): void {
    if (this.isElement(node)) {
      this.processElement(node, parentPath);
    } else if (this.isDocument(node)) {
      this.processDocument(node, parentPath);
    }
  }

  private processElement(node: Element, parentPath: string): void {
    const elementId = this.generateElementId();
    const path = parentPath ? `${parentPath}>${node.tagName}` : node.tagName;

    if (node.sourceCodeLocation) {
      this.saveElementMapping(node, elementId);
      this.addElementIdAttribute(node, elementId);
    }

    if (node.childNodes) {
      for (const child of node.childNodes) {
        this.traverseNode(child, path);
      }
    }
  }

  private processDocument(node: Document, parentPath: string): void {
    if (node.childNodes) {
      for (const child of node.childNodes) {
        this.traverseNode(child, parentPath);
      }
    }
  }

  private saveElementMapping(node: Element, elementId: string): void {
    const loc = node.sourceCodeLocation;
    if (!loc) {
      return;
    }

    const position: ElementPosition = {
      elementId,
      start: {
        line: loc.startLine,
        column: loc.startCol,
        offset: loc.startOffset,
      },
      end: {
        line: loc.endLine,
        column: loc.endCol,
        offset: loc.endOffset,
      },
    };

    const attributes: Record<string, string> = {};
    if (node.attrs) {
      for (const attr of node.attrs) {
        attributes[attr.name] = attr.value;
      }
    }

    this.elementMap.set(elementId, {
      elementId,
      tagName: node.tagName,
      position,
      attributes,
    });
  }

  private addElementIdAttribute(node: Element, elementId: string): void {
    if (!node.attrs) {
      node.attrs = [];
    }
    node.attrs.push({
      name: 'data-element-id',
      value: elementId,
    });
  }

  private isElement(node: ChildNode | Document): node is Element {
    return 'tagName' in node;
  }

  private isDocument(node: ChildNode | Document): node is Document {
    return node.nodeName === '#document';
  }

  private generateElementId(): string {
    return `${this.idPrefix}${++this.idCounter}`;
  }

  findElementByPosition(offset: number): ElementMapping | undefined {
    for (const [_, mapping] of this.elementMap) {
      if (
        offset >= mapping.position.start.offset &&
        offset <= mapping.position.end.offset
      ) {
        return mapping;
      }
    }
    return;
  }

  getElementMapping(elementId: string): ElementMapping | undefined {
    return this.elementMap.get(elementId);
  }

  // Serialize the document back to HTML with data-element-id attributes
  serializeWithIds(document: Document): string {
    return serialize(document);
  }
}
