import type React from 'react';
import type { MediaActionsProps, MediaItem } from './types';

export const MediaActions: React.FC<MediaActionsProps> = ({
  selectedItems,
  onInsert,
  onCopyLinks,
}) => {
  return (
    <div className="w-64 border-gray-200 border-l bg-gray-50 p-4">
      <div className="mb-4">
        <h3 className="font-medium text-gray-900">
          已选择 {selectedItems.length} 个项目
        </h3>
      </div>

      <div className="space-y-2">
        <button
          className={`w-full rounded-md px-4 py-2 font-medium text-sm transition-colors ${
            selectedItems.length > 0
              ? 'bg-blue-600 text-white hover:bg-blue-700'
              : 'cursor-not-allowed bg-gray-200 text-gray-400'
          }`}
          disabled={selectedItems.length === 0}
          onClick={onInsert}
          type="button"
        >
          插入到编辑器
        </button>

        <button
          className={`w-full rounded-md px-4 py-2 font-medium text-sm transition-colors ${
            selectedItems.length > 0
              ? 'border border-gray-300 bg-white text-gray-700 hover:bg-gray-50'
              : 'cursor-not-allowed bg-gray-100 text-gray-400'
          }`}
          disabled={selectedItems.length === 0}
          onClick={onCopyLinks}
          type="button"
        >
          复制链接
        </button>
      </div>

      {selectedItems.length > 0 && (
        <div className="mt-4">
          <h4 className="mb-2 font-medium text-gray-700 text-sm">
            选中的项目：
          </h4>
          <div className="max-h-64 space-y-2 overflow-y-auto">
            {selectedItems.map((item) => (
              <SelectedItemDisplay item={item} key={item.id} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

const SelectedItemDisplay: React.FC<{ item: MediaItem }> = ({ item }) => {
  const isImage = item.mime_type?.startsWith('image/');

  return (
    <div className="flex items-center gap-2 rounded bg-white p-2 text-sm">
      {isImage && item.sizes?.thumbnail ? (
        // biome-ignore lint/performance/noImgElement: Not using Next.js
        <img
          alt={item.alt || item.title}
          className="h-10 w-10 rounded object-cover"
          src={item.sizes?.thumbnail?.url}
        />
      ) : (
        <div className="flex h-10 w-10 items-center justify-center rounded bg-gray-100">
          <svg
            className="h-6 w-6 text-gray-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <title>文件</title>
            <path
              d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
            />
          </svg>
        </div>
      )}
      <span className="flex-1 truncate text-gray-700">{item.title}</span>
    </div>
  );
};
