import type { CompileResult } from '@/types/templates';
import { apiClient } from './client';

export interface Content {
  id: number;
  content: string;
  title?: string;
  status?: string;
  design_system_html?: string;
  meta?: {
    _zeroy_edited?: boolean;
    _zeroy_last_edited?: string;
    _zeroy_extracted_css?: string;
  };
}

export interface SaveContentPayload {
  content: string;
  extractedCss?: string;
}

export interface HeaderFooterData {
  header: string;
  footer: string;
  safelist: string;
  header_footer_hash: string;
  design_system_hash: string;
}

export interface SaveRawResult {
  success: boolean;
  post_id: number;
  header_footer_hash: string;
  design_system_hash: string;
  global_template_changed?: boolean;
  compile_result?: CompileResult;
  speed_optimization_enabled?: boolean;
  image_optimization_enabled?: boolean;
  message?: string;
}

export interface PageImageOptimizationStatus {
  success: boolean;
  enabled: boolean;
  total_images: number;
  ready_images: number;
  pending_images: number;
  all_ready: boolean;
  pending_attachment_ids: number[];
}

export interface RefreshOptimizedHTMLResult {
  success: boolean;
  refreshed?: boolean;
  image_count?: number;
  reason?: string;
}

export interface SaveCompiledCSSPayload {
  css: string;
  source: 'frontend' | 'backend';
  header_footer_hash: string;
  design_system_hash: string;
}

// 缓存 header/footer 内容（编辑器生命周期内）
let headerFooterCache: HeaderFooterData | null = null;

export const contentApi = {
  // 获取内容
  get: (id: number) => apiClient.get<Content>(`/content/${id}`),

  // 保存内容（旧方法，保持兼容）
  save: (id: number, data: string | SaveContentPayload) => {
    const payload = typeof data === 'string' ? { content: data } : data;
    return apiClient.post<Content>(`/content/${id}`, payload);
  },

  /**
   * 获取 header/footer 内容（用于前端编译）
   * 带缓存，编辑器生命周期内只请求一次
   */
  getHeaderFooter: async (forceRefresh = false): Promise<HeaderFooterData> => {
    if (!forceRefresh && headerFooterCache) {
      return headerFooterCache;
    }

    const result = await apiClient.get<HeaderFooterData>(
      '/content/header-footer'
    );
    headerFooterCache = result;
    return result;
  },

  /**
   * 清除 header/footer 缓存（模板变更时调用）
   */
  clearHeaderFooterCache: () => {
    headerFooterCache = null;
  },

  /**
   * 保存 raw 内容（第 1 步）
   */
  saveRaw: (postId: number, data: { content: string }) => {
    return apiClient.post<SaveRawResult>(`/content/${postId}/save-raw`, data);
  },

  /**
   * 获取当前页面图片优化状态
   */
  getImageOptimizationStatus: (postId: number) => {
    return apiClient.get<PageImageOptimizationStatus>(
      `/content/${postId}/image-optimization-status`
    );
  },

  /**
   * 刷新页面优化 HTML
   */
  refreshOptimizedHTML: (postId: number) => {
    return apiClient.post<RefreshOptimizedHTMLResult>(
      `/content/${postId}/refresh-optimized-html`,
      {}
    );
  },

  /**
   * 保存编译后的 CSS
   */
  saveCompiledCSS: (postId: number, data: SaveCompiledCSSPayload) => {
    return apiClient.post<{ success: boolean }>(
      `/content/${postId}/save-compiled-css`,
      data
    );
  },

  /**
   * 标记使用 CDN（编译失败时）
   */
  markUseCDN: (postId: number) => {
    return apiClient.post<{ success: boolean }>(
      `/content/${postId}/mark-use-cdn`,
      {}
    );
  },
};
