/**
 * 智能 Worker 池管理器
 * 特性：
 * - 自动检测 CPU 核心数
 * - 智能任务调度（优先级队列）
 * - Worker 崩溃自动重启
 * - 性能监控
 */

import type { WorkerResponse, WorkerResult, WorkerTask } from './worker-types';

/**
 * Worker Pool Debug 日志（只在调试模式显示）
 */
function workerDebugLog(...args: unknown[]) {
  const debugLevel = localStorage.getItem('zeroy_debug');
  if (debugLevel === '1') {
    console.log('[WorkerPool]', ...args);
  }
}

/**
 * 任务队列项
 */
interface QueuedTask {
  task: WorkerTask;
  resolve: (result: WorkerResult) => void;
  reject: (error: Error) => void;
}

/**
 * Worker 状态
 */
interface WorkerState {
  worker: Worker;
  busy: boolean;
  currentTask?: {
    resolve: (result: WorkerResult) => void;
    reject: (error: Error) => void;
  };
  tasksCompleted: number;
  crashCount: number;
}

/**
 * 图片处理 Worker 池
 */
export class ImageWorkerPool {
  private workers: WorkerState[] = [];
  private taskQueue: QueuedTask[] = [];
  private taskIdCounter = 0;
  private readonly poolSize: number;

  constructor(poolSize?: number) {
    // 智能检测 CPU 核心数
    const cpuCores = navigator.hardwareConcurrency || 4;

    // M3 有 8 核，我们使用 min(cpuCores, 8) 作为 Worker 数量
    // 避免创建过多 Workers 导致调度开销
    this.poolSize = poolSize || Math.min(cpuCores, 8);

    workerDebugLog(
      `[WorkerPool] 🧠 检测到 ${cpuCores} 个 CPU 核心，创建 ${this.poolSize} 个 Workers`
    );

    this.initializeWorkers();
  }

  /**
   * 初始化 Worker 池
   */
  private initializeWorkers() {
    for (let i = 0; i < this.poolSize; i++) {
      this.createWorker(i);
    }
  }

  /**
   * 创建单个 Worker
   */
  private createWorker(id: number) {
    try {
      const worker = new Worker(new URL('./image-worker.ts', import.meta.url), {
        type: 'module',
        name: `image-worker-${id}`,
      });

      worker.onmessage = (e: MessageEvent<WorkerResponse>) => {
        this.handleWorkerMessage(id, e.data);
      };

      worker.onerror = (e: ErrorEvent) => {
        this.handleWorkerError(id, e);
      };

      this.workers[id] = {
        worker,
        busy: false,
        tasksCompleted: 0,
        crashCount: 0,
      };

      workerDebugLog(`[WorkerPool] ✅ Worker ${id} 已创建`);
    } catch (error) {
      console.error(`[WorkerPool] ❌ Worker ${id} 创建失败:`, error);
      throw error;
    }
  }

  /**
   * 处理 Worker 消息
   */
  private handleWorkerMessage(workerId: number, response: WorkerResponse) {
    const state = this.workers[workerId];

    if (response.type === 'log') {
      // 转发日志到主线程控制台
      workerDebugLog(response.payload);
      return;
    }

    if (response.type === 'error') {
      console.error(`[WorkerPool] Worker ${workerId} 错误:`, response.payload);
      return;
    }

    if (response.type === 'result' && state.currentTask) {
      const result = response.payload as WorkerResult;

      if (result.success) {
        state.currentTask.resolve(result);
        state.tasksCompleted++;
      } else {
        state.currentTask.reject(new Error(result.error || '任务失败'));
      }

      // 标记 Worker 为空闲
      state.busy = false;
      state.currentTask = undefined;

      // 处理队列中的下一个任务
      this.processQueue();
    }
  }

  /**
   * 处理 Worker 错误（自动重启）
   */
  private handleWorkerError(workerId: number, error: ErrorEvent) {
    const state = this.workers[workerId];
    console.error(`[WorkerPool] ⚠️ Worker ${workerId} 崩溃:`, error.message);

    state.crashCount++;

    // 拒绝当前任务
    if (state.currentTask) {
      state.currentTask.reject(new Error(`Worker 崩溃: ${error.message}`));
      state.currentTask = undefined;
    }

    // 最多重启 3 次，避免无限重启
    if (state.crashCount <= 3) {
      // 终止旧 Worker
      state.worker.terminate();

      // 重启 Worker
      this.createWorker(workerId);
      workerDebugLog(
        `[WorkerPool] 🔄 Worker ${workerId} 已重启（第 ${state.crashCount} 次）`
      );

      // 处理队列
      this.processQueue();
    } else {
      console.error(
        `[WorkerPool] ❌ Worker ${workerId} 崩溃次数过多，停止重启`
      );
    }
  }

  /**
   * 智能任务调度（优先级队列）
   */
  private processQueue() {
    // 按优先级排序队列（优先级数字越小越优先）
    this.taskQueue.sort((a, b) => {
      const priorityA = a.task.priority ?? 999;
      const priorityB = b.task.priority ?? 999;
      return priorityA - priorityB;
    });

    // 找到所有空闲的 Workers
    for (let i = 0; i < this.workers.length; i++) {
      const state = this.workers[i];

      if (!state.busy && this.taskQueue.length > 0) {
        const queuedTask = this.taskQueue.shift();
        if (!queuedTask) {
          continue;
        }

        // 标记 Worker 为忙碌
        state.busy = true;
        state.currentTask = {
          resolve: queuedTask.resolve,
          reject: queuedTask.reject,
        };

        // 发送任务到 Worker
        state.worker.postMessage({
          type: 'task',
          payload: queuedTask.task,
        });

        workerDebugLog(
          `[WorkerPool] 📤 分配任务 ${queuedTask.task.id} [${queuedTask.task.type}] 到 Worker ${i} (队列剩余: ${this.taskQueue.length})`
        );
      }
    }
  }

  /**
   * 提交任务到 Worker 池
   */
  runTask(task: Omit<WorkerTask, 'id'>): Promise<WorkerResult> {
    return new Promise<WorkerResult>((resolve, reject) => {
      // 生成任务 ID
      const taskId = `task-${++this.taskIdCounter}`;
      const fullTask: WorkerTask = {
        ...task,
        id: taskId,
      };

      // 添加到队列
      this.taskQueue.push({
        task: fullTask,
        resolve,
        reject,
      });

      // 尝试立即处理
      this.processQueue();
    });
  }

  /**
   * 获取池状态（性能监控）
   */
  getStatus() {
    const busyCount = this.workers.filter((w) => w.busy).length;
    const totalTasksCompleted = this.workers.reduce(
      (sum, w) => sum + w.tasksCompleted,
      0
    );

    return {
      totalWorkers: this.workers.length,
      busyWorkers: busyCount,
      idleWorkers: this.workers.length - busyCount,
      queueLength: this.taskQueue.length,
      totalTasksCompleted,
      workersHealth: this.workers.map((w, i) => ({
        id: i,
        busy: w.busy,
        tasksCompleted: w.tasksCompleted,
        crashCount: w.crashCount,
      })),
    };
  }

  /**
   * 销毁 Worker 池
   */
  destroy() {
    workerDebugLog('[WorkerPool] 🗑️ 正在销毁 Worker 池...');

    // 清空队列
    for (const task of this.taskQueue) {
      task.reject(new Error('Worker 池已销毁'));
    }
    this.taskQueue = [];

    // 终止所有 Workers
    this.workers.forEach((state, i) => {
      state.worker.postMessage({ type: 'terminate' });
      state.worker.terminate();
      workerDebugLog(`[WorkerPool] 🛑 Worker ${i} 已终止`);
    });

    this.workers = [];
    workerDebugLog('[WorkerPool] ✅ Worker 池已销毁');
  }
}
