import type React from 'react';
import { useEffect } from 'react';

interface SaveConfirmDialogProps {
  isOpen: boolean;
  onConfirm: () => void;
  onCancel: () => void;
}

export const SaveConfirmDialog: React.FC<SaveConfirmDialogProps> = ({
  isOpen,
  onConfirm,
  onCancel,
}) => {
  // 处理 ESC 键
  useEffect(() => {
    if (!isOpen) {
      return;
    }

    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onCancel();
      }
    };

    document.addEventListener('keydown', handleEscape);
    return () => document.removeEventListener('keydown', handleEscape);
  }, [isOpen, onCancel]);

  // 防止背景滚动
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* Backdrop */}
      <div
        aria-label="关闭对话框"
        className="fixed inset-0 z-[9999] bg-black/50"
        onClick={onCancel}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            onCancel();
          }
        }}
        role="button"
        tabIndex={0}
      />
      {/* Dialog */}
      <div
        aria-labelledby="dialog-title"
        aria-modal="true"
        className="pointer-events-none fixed inset-0 z-[9999] flex items-center justify-center"
        role="dialog"
      >
        <div className="pointer-events-auto relative z-[10000] w-full max-w-md rounded-lg bg-white p-6 shadow-xl">
          <div className="mb-4 flex items-center">
            <svg
              aria-hidden="true"
              className="mr-3 h-6 w-6 text-amber-500"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
            <h3 className="font-semibold text-lg" id="dialog-title">
              确认保存操作
            </h3>
          </div>

          <div className="space-y-3 text-gray-600 text-sm">
            <p>
              您当前处于
              <strong className="text-green-600">生产模式</strong>。
            </p>
            <p>保存内容将会：</p>
            <ul className="ml-4 list-inside list-disc space-y-1">
              <li>自动关闭生产模式</li>
              <li>切换到开发模式（使用 Play CDN）</li>
              <li>确保您能继续编辑内容</li>
            </ul>
            <p className="mt-4 text-amber-600">
              做出任何改动后，需在“设置 - 性能"中重新启用生产模式。
            </p>
          </div>

          <div className="mt-6 flex justify-end space-x-3">
            <button
              className="rounded-md px-4 py-2 text-gray-600 transition-colors hover:bg-gray-100"
              onClick={onCancel}
              type="button"
            >
              取消
            </button>
            <button
              className="rounded-md bg-blue-600 px-4 py-2 text-white transition-colors hover:bg-blue-700"
              onClick={onConfirm}
              type="button"
            >
              确认保存并退出生产模式
            </button>
          </div>
        </div>
      </div>
    </>
  );
};
