import { AlertTriangle } from 'lucide-react';
import type React from 'react';
import { useCallback } from 'react';
import type { TangibleDetectionResult } from '@/lib/tangible-detector';
import {
  estimateMigrationComplexity,
  getTangibleTagsDescription,
} from '@/lib/tangible-detector';

interface TangibleNoticeProps {
  detectionResult: TangibleDetectionResult;
  onConvert: () => void;
}

/**
 * 检测到 Tangible 标签时显示的提醒组件
 */
export const TangibleNotice: React.FC<TangibleNoticeProps> = ({
  detectionResult,
  onConvert,
}) => {
  const handleConvert = useCallback(() => {
    onConvert();
  }, [onConvert]);

  if (!detectionResult.hasTangibleTags) {
    return null;
  }

  const complexity = estimateMigrationComplexity(detectionResult);
  const description = getTangibleTagsDescription(detectionResult);

  const complexityColors = {
    simple: 'text-green-600',
    moderate: 'text-yellow-600',
    complex: 'text-red-600',
  };

  const complexityLabels = {
    simple: '简单转换',
    moderate: '中等复杂度',
    complex: '复杂转换',
  };

  return (
    <div className="mx-4 mt-4 mb-4 border-red-500 border-l-4 bg-red-50 p-4">
      <div className="flex items-start">
        <div className="flex-shrink-0">
          <AlertTriangle className="h-5 w-5 text-red-500" />
        </div>

        <div className="ml-3 flex-1">
          <div className="mb-2">
            <h3 className="font-medium text-red-800 text-sm">
              ⚠️ 必须转换 Tangible 标签
            </h3>
          </div>

          <div className="mb-3 text-red-700 text-sm">
            <p className="mb-1 font-semibold">
              zeroY 不再支持 Tangible 模板语法，您必须将其转换为现代 PHP
              代码才能继续使用。
            </p>
            <p className="text-red-600 text-xs">{description}</p>
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <span
                className={`font-medium text-xs ${complexityColors[complexity]}`}
              >
                {complexityLabels[complexity]}
              </span>

              <div className="font-semibold text-red-600 text-xs">
                共发现 {detectionResult.totalTags} 个标签
              </div>
            </div>

            <div className="mt-2">
              <button
                className="inline-flex animate-pulse items-center rounded bg-red-600 px-4 py-2 font-medium text-sm text-white hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2"
                onClick={handleConvert}
                type="button"
              >
                立即转换 Tangible 标签
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
