import type React from 'react';
import { useState } from 'react';
import type { MediaPaginationProps } from './types';

export const MediaPagination: React.FC<MediaPaginationProps> = ({
  currentPage,
  totalPages,
  onPageChange,
}) => {
  const [pageInput, setPageInput] = useState('');

  if (totalPages <= 1) {
    return null;
  }

  const handlePageJump = () => {
    const targetPage = Number.parseInt(pageInput, 10);
    if (Number.isNaN(targetPage) || targetPage < 1 || targetPage > totalPages) {
      alert(`请输入 1 到 ${totalPages} 之间的页码`);
      return;
    }
    onPageChange(targetPage);
    setPageInput('');
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handlePageJump();
    }
  };

  return (
    <div className="mt-6 flex items-center justify-center space-x-2">
      <button
        className="rounded px-3 py-1 text-sm hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-50"
        disabled={currentPage === 1}
        onClick={() => onPageChange(currentPage - 1)}
        type="button"
      >
        上一页
      </button>

      <div className="flex items-center space-x-2">
        <span className="px-2 py-1 text-gray-600 text-sm">
          {currentPage} / {totalPages}
        </span>

        <div className="flex items-center space-x-1">
          <input
            className="w-16 rounded border border-gray-300 px-2 py-1 text-center text-sm focus:border-blue-500 focus:outline-none"
            max={totalPages}
            min={1}
            onChange={(e) => setPageInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="页码"
            type="number"
            value={pageInput}
          />
          <button
            className="rounded bg-blue-500 px-2 py-1 text-sm text-white hover:bg-blue-600 disabled:cursor-not-allowed disabled:opacity-50"
            onClick={handlePageJump}
            type="button"
          >
            跳转
          </button>
        </div>
      </div>

      <button
        className="rounded px-3 py-1 text-sm hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-50"
        disabled={currentPage === totalPages}
        onClick={() => onPageChange(currentPage + 1)}
        type="button"
      >
        下一页
      </button>
    </div>
  );
};
