import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useState } from 'react';
import { apiClient } from '@/api/client';
import { useNotification } from '@/components/notification';
import { uploadAndProcessImage } from '@/lib/image-processor';
import { notifyImageUploaded } from '@/lib/optimization-engine';
import { useEditorStore } from '@/store/editor';
import type { MediaItem } from './types';

/**
 * 处理单个文件上传（极简版 - 只上传原图）
 */
async function uploadSingleFile(file: File) {
  const startTime = performance.now();
  console.log(
    `[ZeroY Upload] ==================== 开始上传: ${file.name} ====================`
  );

  // 上传原图到 WordPress（0.5-1 秒完成）
  const result = await uploadAndProcessImage(file, {
    onProgress: (message, current, total) => {
      console.log(`[ZeroY Upload] ${message} (${current}/${total})`);
    },
  });

  const elapsed = performance.now() - startTime;
  console.log(
    `[ZeroY Upload] ==================== 上传总耗时: ${elapsed.toFixed(0)}ms ====================`
  );
  console.log('[ZeroY Upload] 上传结果:', {
    attachment_id: result.attachment_id,
    sourceFormat: result.sourceFormat,
    sizes: result.sizes.length,
  });

  // 通知优化引擎有新图片（立即触发扫描）
  notifyImageUploaded();

  return {
    success: true,
    attachment_id: result.attachment_id,
  };
}

export const useMediaLibrary = () => {
  const { notify } = useNotification();
  const { content, setContent } = useEditorStore();
  const queryClient = useQueryClient();
  const [selectedItems, setSelectedItems] = useState<MediaItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(1);
  const [isUploading, setIsUploading] = useState(false);
  const [editingItem, setEditingItem] = useState<MediaItem | null>(null);

  // 获取媒体列表
  const { data, isLoading, refetch } = useQuery<{
    data: MediaItem[];
    total: number;
    pages: number;
  }>({
    queryKey: ['media', page, searchTerm],
    queryFn: () => {
      // 使用带自动 nonce 刷新的 API 客户端
      return apiClient.get('/media', {
        page,
        per_page: 35,
        ...(searchTerm ? { search: searchTerm } : {}),
      });
    },
  });

  const toggleSelection = useCallback((item: MediaItem) => {
    setSelectedItems((prev) => {
      const isSelected = prev.some((i) => i.id === item.id);
      if (isSelected) {
        return prev.filter((i) => i.id !== item.id);
      }
      return [...prev, item];
    });
  }, []);

  const handleInsert = useCallback(() => {
    if (selectedItems.length === 0) {
      notify('warning', '请先选择图片');
      return;
    }

    const html = selectedItems
      .map((item) => {
        if (item.mime_type?.startsWith('image/')) {
          return `<img src="${item.url}" alt="${item.alt || item.title}" />`;
        }
        if (item.mime_type?.startsWith('video/')) {
          return `<video src="${item.url}" controls></video>`;
        }
        return `<a href="${item.url}">${item.title}</a>`;
      })
      .join('\n');

    // 使用全局方法插入到光标位置
    if (typeof window !== 'undefined' && (window as any).insertTextAtCursor) {
      (window as any).insertTextAtCursor(html);
    } else {
      // 备用方案：添加到末尾
      setContent(`${content}\n${html}`);
    }

    notify('success', `已插入 ${selectedItems.length} 个媒体项`);
    setSelectedItems([]);
  }, [selectedItems, content, setContent, notify]);

  const handleCopyLinks = useCallback(() => {
    if (selectedItems.length === 0) {
      notify('warning', '请先选择图片');
      return;
    }

    const links = selectedItems.map((item) => item.url).join(', ');

    // 备用复制方法
    const copyFallback = (text: string) => {
      const textArea = document.createElement('textarea');
      textArea.value = text;
      textArea.style.position = 'fixed';
      textArea.style.left = '-9999px';
      document.body.appendChild(textArea);
      textArea.focus();
      textArea.select();

      try {
        document.execCommand('copy');
        notify('success', `已复制 ${selectedItems.length} 个链接到剪贴板`);
      } catch (_err) {
        notify('error', '复制失败，请手动复制');
      }

      document.body.removeChild(textArea);
    };

    // 尝试使用现代 API
    if (navigator.clipboard?.writeText) {
      navigator.clipboard
        .writeText(links)
        .then(() => {
          notify('success', `已复制 ${selectedItems.length} 个链接到剪贴板`);
        })
        .catch(() => {
          // 如果失败，尝试备用方法
          copyFallback(links);
        });
    } else {
      // 使用备用方法
      copyFallback(links);
    }
  }, [selectedItems, notify]);

  // 处理文件上传（极简版 - 只上传原图）
  const handleUpload = useCallback(
    async (files: FileList) => {
      setIsUploading(true);

      try {
        const fileArray = Array.from(files);
        let successCount = 0;
        let failedCount = 0;

        // 串行上传每个文件（避免并发过多）
        for (const file of fileArray) {
          try {
            await uploadSingleFile(file);
            successCount++;
          } catch (error) {
            failedCount++;
            console.error('[ZeroY Upload] 上传失败:', file.name, error);
          }
        }

        // 显示结果
        if (successCount > 0) {
          notify('success', `成功上传 ${successCount} 个文件`);
          await queryClient.invalidateQueries({ queryKey: ['media'] });
        }

        if (failedCount > 0) {
          notify('error', `${failedCount} 个文件上传失败`);
        }
      } catch (error) {
        notify(
          'error',
          `上传失败: ${error instanceof Error ? error.message : '未知错误'}`
        );
        console.error('[ZeroY Upload] 上传错误:', error);
      } finally {
        setIsUploading(false);
      }
    },
    [notify, queryClient]
  );

  const handleEdit = useCallback((item: MediaItem) => {
    setEditingItem(item);
  }, []);

  const closeEditor = useCallback(() => {
    setEditingItem(null);
  }, []);

  const resetState = useCallback(() => {
    setSelectedItems([]);
    setSearchTerm('');
    setPage(1);
    setEditingItem(null);
  }, []);

  return {
    // State
    data,
    isLoading,
    selectedItems,
    searchTerm,
    page,
    isUploading,
    editingItem,

    // Actions
    setSearchTerm,
    setPage,
    toggleSelection,
    handleInsert,
    handleCopyLinks,
    handleUpload,
    handleEdit,
    closeEditor,
    resetState,

    // Query controls
    refetch,
  };
};
