import type React from 'react';
import type { MediaItem as MediaItemType } from './types';

// 顶层定义正则表达式常量
const IMAGE_FILE_REGEX = /\.(jpg|jpeg|png|gif|webp|svg)$/i;

interface MediaItemProps {
  item: MediaItemType;
  isSelected: boolean;
  onToggle: () => void;
  onEdit?: (item: MediaItemType) => void;
}

export const MediaItem: React.FC<MediaItemProps> = ({
  item,
  isSelected,
  onToggle,
  onEdit,
}) => {
  const isImage =
    item.mime_type?.startsWith('image/') ||
    item.filename?.match(IMAGE_FILE_REGEX);

  return (
    <button
      className={`group relative aspect-square overflow-hidden rounded-lg border-2 transition-all ${
        isSelected
          ? 'border-blue-500 ring-2 ring-blue-500 ring-offset-2'
          : 'border-gray-200 hover:border-gray-300'
      }`}
      onClick={onToggle}
      type="button"
    >
      {isImage ? (
        // biome-ignore lint/performance/noImgElement: Not using Next.js
        // biome-ignore lint/nursery/noNoninteractiveElementInteractions: Parent button handles interaction
        <img
          alt={item.alt || item.title}
          className="h-full w-full object-cover"
          onError={(e) => {
            e.currentTarget.src =
              'data:image/svg+xml;base64,';
          }}
          src={
            item.sizes?.medium?.url || item.sizes?.thumbnail?.url || item.url
          }
        />
      ) : (
        <div className="flex h-full items-center justify-center bg-gray-100">
          <svg
            className="h-12 w-12 text-gray-400"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <title>文件</title>
            <path
              d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
            />
          </svg>
        </div>
      )}
      {isSelected && (
        <div className="absolute top-2 right-2 flex h-6 w-6 items-center justify-center rounded-full bg-blue-500 text-white">
          <svg className="h-4 w-4" fill="currentColor" viewBox="0 0 20 20">
            <title>已选中</title>
            <path
              clipRule="evenodd"
              d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z"
              fillRule="evenodd"
            />
          </svg>
        </div>
      )}
      {/* Edit button - only for images */}
      {isImage && onEdit && (
        <button
          className="absolute right-2 bottom-2 flex h-8 w-8 items-center justify-center rounded-full bg-white/90 opacity-0 shadow-lg transition hover:bg-white group-hover:opacity-100"
          onClick={(e) => {
            e.stopPropagation();
            onEdit(item);
          }}
          title="编辑图片"
          type="button"
        >
          <svg
            className="h-4 w-4 text-gray-700"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <title>编辑</title>
            <path
              d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
            />
          </svg>
        </button>
      )}
    </button>
  );
};
