import type React from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useAIModelAvailability } from '@/hooks/use-ai-model-availability';
import type { ModelListResult, UnifiedModel } from '@/lib/ai-config-provider';
import { extractAiCredentials } from '@/lib/ai-credentials';
import {
  chooseInitialModel,
  createModelStorageKey,
  ensureSelectionExists,
  persistModelSelection,
} from '@/lib/model-selection';
import { ModelSelect } from '@/settings/components/ai-settings/model-select';
import { CodeModePanel } from './code-mode/code-mode-panel';
import type { UnifiedAIDialogProps } from './types/ai-dialog.types';

export const UnifiedAIDialog: React.FC<UnifiedAIDialogProps> = ({
  isOpen,
  onClose,
  initialPrompt,
}) => {
  const [selectedModel, setSelectedModel] = useState<string>('');
  const [models, setModels] = useState<UnifiedModel[]>([]);
  const [modelError, setModelError] = useState('');
  const [currentBaseUrl, setCurrentBaseUrl] = useState(
    window.zeroyEditor?.aiSettings?.base_url || ''
  );
  const hasInitializedModel = useRef(false);

  const handleModelsUpdate = useCallback(
    (nextModels: UnifiedModel[], resolvedBaseUrl?: string) => {
      setModels(nextModels);

      const fallbackBaseUrl = window.zeroyEditor?.aiSettings?.base_url || '';
      let storageBase = resolvedBaseUrl || currentBaseUrl || fallbackBaseUrl;

      if (resolvedBaseUrl && resolvedBaseUrl !== currentBaseUrl) {
        hasInitializedModel.current = false;
        setCurrentBaseUrl(resolvedBaseUrl);
        storageBase = resolvedBaseUrl;
      }

      const storageKey = storageBase
        ? createModelStorageKey(storageBase)
        : null;

      const applySelection = (modelId: string | null) => {
        setSelectedModel(modelId ?? '');
        persistModelSelection(storageKey, modelId);
      };

      if (!hasInitializedModel.current) {
        const savedModel = storageKey ? localStorage.getItem(storageKey) : null;
        const initialSelection = chooseInitialModel(nextModels, {
          saved: savedModel,
          defaultModel: window.zeroyEditor?.aiSettings?.model,
          currentSelection: selectedModel,
        });
        applySelection(initialSelection);
        hasInitializedModel.current = true;
        return;
      }

      const ensured = ensureSelectionExists(nextModels, selectedModel);
      if (ensured !== (selectedModel || null)) {
        applySelection(ensured);
      }
    },
    [currentBaseUrl, selectedModel]
  );

  // Helpers for result mapping and messaging (declared before useEffect to satisfy lint)
  const pickResolvedBase = useCallback(
    (resultBase?: string, localBase?: string, aiBase?: string): string =>
      resultBase || localBase || aiBase || '',
    []
  );

  const buildModelsFromResult = useCallback(
    (result: ModelListResult): UnifiedModel[] => {
      if (result.models && result.models.length > 0) {
        return result.models as UnifiedModel[];
      }
      const sugg = (result.suggestions || []) as string[];
      return sugg.map((s) => ({ id: s, name: s }));
    },
    []
  );

  const buildModelMessage = useCallback((result: ModelListResult): string => {
    if (result.source === 'none') {
      return (
        result.serverErrorMessage ||
        result.localErrorMessage ||
        '无法获取模型列表，请检查配置'
      );
    }
    if (result.source === 'local' && result.serverStatus === 'error') {
      return result.serverErrorMessage
        ? `${result.serverErrorMessage}（已回退到本地配置）`
        : '服务端配置不可用，已回退到本地配置';
    }
    if (result.listingSupported === false) {
      return '上游不支持列出模型，请手动选择或输入模型 ID';
    }
    return '';
  }, []);

  // Small wrapper to apply result consistently
  const handleModelsFromResult = useCallback(
    (result: ModelListResult, baseUrlA?: string, baseUrlB?: string) => {
      const resolved = pickResolvedBase(result.baseUrl, baseUrlA, baseUrlB);
      const list = buildModelsFromResult(result);
      handleModelsUpdate(list, resolved || undefined);
      setModelError(buildModelMessage(result));
    },
    [
      pickResolvedBase,
      buildModelsFromResult,
      handleModelsUpdate,
      buildModelMessage,
    ]
  );

  const aiSettings = window.zeroyEditor?.aiSettings;
  const hasAiSettings = Boolean(aiSettings);
  const rawBaseUrl = aiSettings?.base_url || '';
  const aiCredentials = extractAiCredentials(aiSettings);

  const {
    result: modelResult,
    loading: isLoadingModels,
    error: availabilityError,
    available: hasModels,
  } = useAIModelAvailability({
    enabled: isOpen && aiCredentials.hasCredentials,
    credentials: aiSettings || null,
  });

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    if (!hasAiSettings) {
      setModels([]);
      setModelError('未检测到 AI 设置，请刷新页面。');
      return;
    }

    if (!aiCredentials.hasCredentials) {
      setModels([]);
      setModelError('请先在设置中配置 API URL 与 Key，或上传到服务端。');
      return;
    }

    if (availabilityError) {
      setModels([]);
      setModelError(availabilityError);
      return;
    }

    if (modelResult) {
      handleModelsFromResult(modelResult, aiCredentials.baseUrl, rawBaseUrl);
      return;
    }

    if (!(isLoadingModels || hasModels)) {
      setModels([]);
      setModelError('无法获取模型列表，请检查配置');
    }
  }, [
    isOpen,
    hasAiSettings,
    aiCredentials.hasCredentials,
    aiCredentials.baseUrl,
    rawBaseUrl,
    availabilityError,
    modelResult,
    handleModelsFromResult,
    isLoadingModels,
    hasModels,
  ]);

  const handleModelChange = (model: string) => {
    setSelectedModel(model);
    const storageBaseUrl =
      currentBaseUrl || window.zeroyEditor?.aiSettings?.base_url;
    if (!storageBaseUrl) {
      return;
    }
    const storageKey = createModelStorageKey(storageBaseUrl);
    localStorage.setItem(storageKey, model);
  };

  const renderModelSelector = () => {
    if (models.length > 0) {
      return (
        <ModelSelect
          className="min-w-60"
          isLoading={isLoadingModels}
          models={models}
          onChange={handleModelChange}
          placeholder="选择模型"
          value={selectedModel}
        />
      );
    }

    if (isLoadingModels) {
      return <div className="text-gray-500 text-sm">模型列表加载中...</div>;
    }

    return (
      <div className="max-w-xs text-red-600 text-sm">
        {modelError || '无可用模型，请检查 API 配置'}
      </div>
    );
  };

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 z-50 bg-black/50" />

      {/* Dialog */}
      <div className="pointer-events-none fixed inset-0 z-50 flex items-center justify-center p-4">
        <div className="pointer-events-auto flex h-[80vh] w-full max-w-4xl flex-col rounded-lg bg-white shadow-xl">
          {/* Header */}
          <div className="flex items-center justify-between border-b p-4">
            <h2 className="font-semibold text-gray-900 text-xl">AI 智能助手</h2>
            <div className="flex items-center gap-3">
              {/* 模型选择器 */}
              {renderModelSelector()}
              <button
                className="text-gray-400 transition hover:text-gray-600"
                onClick={onClose}
                type="button"
              >
                <svg
                  className="h-6 w-6"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <title>关闭</title>
                  <path
                    d="M6 18L18 6M6 6l12 12"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                  />
                </svg>
              </button>
            </div>
          </div>

          {/* Content Area */}
          <div className="flex-1 overflow-hidden">
            <CodeModePanel
              initialPrompt={initialPrompt}
              onClose={onClose}
              selectedModel={selectedModel}
            />
          </div>
        </div>
      </div>
    </>
  );
};
