import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

interface SelectedElement {
  id: string;
  tagName: string;
  start: number;
  end: number;
}

interface EditorState {
  // 内容
  content: string;
  originalContent: string;
  isDirty: boolean;

  // 选中状态
  selectedText: string;
  selectionStart: number;
  selectionEnd: number;
  selectedElement: SelectedElement | null;

  // 撤销/重做
  history: string[];
  historyIndex: number;

  // UI 状态
  isLoading: boolean;
  isSaving: boolean;
  isPreviewLoading: boolean;
  isSelecting: boolean;
  previewDevice: 'desktop' | 'mobile';

  // 布局状态
  codeHeight: number; // 代码区高度百分比 (0-100)

  // Actions
  setContent: (content: string, addToHistory?: boolean) => void;
  setOriginalContent: (content: string) => void;
  setLoading: (isLoading: boolean) => void;
  setSaving: (isSaving: boolean) => void;
  setPreviewLoading: (isPreviewLoading: boolean) => void;
  resetDirty: () => void;
  setSelecting: (isSelecting: boolean) => void;
  setSelection: (selectedText: string, start: number, end: number) => void;
  clearSelection: () => void;
  setSelectedElement: (element: SelectedElement | null) => void;
  setPreviewDevice: (device: 'desktop' | 'mobile') => void;
  setCodeHeight: (height: number) => void;
  undo: () => void;
  redo: () => void;
}

// 代码区默认高度：0%（默认隐藏，全屏预览）
// 每次进入编辑器都重置为 0%，不记忆用户上次的设置
const DEFAULT_CODE_HEIGHT = 0;

export const useEditorStore = create<EditorState>()(
  devtools(
    (set, _get) => ({
      // 初始状态
      content: '',
      originalContent: '',
      isDirty: false,
      selectedText: '',
      selectionStart: 0,
      selectionEnd: 0,
      selectedElement: null,
      history: [''],
      historyIndex: 0,
      isLoading: false,
      isSaving: false,
      isPreviewLoading: false,
      isSelecting: false,
      previewDevice: 'desktop',
      codeHeight: DEFAULT_CODE_HEIGHT,

      // Actions
      setContent: (content, addToHistory = true) =>
        set((state) => {
          const newState: Partial<EditorState> = {
            content,
            isDirty: content !== state.originalContent,
          };

          if (addToHistory) {
            // 如果在历史中间进行了修改，删除后面的历史
            const newHistory = state.history.slice(0, state.historyIndex + 1);
            newHistory.push(content);

            // 限制历史记录数量，防止内存占用过多
            if (newHistory.length > 50) {
              newHistory.shift();
            }

            newState.history = newHistory;
            newState.historyIndex = newHistory.length - 1;
          }

          return newState;
        }),

      setOriginalContent: (originalContent) =>
        set({
          originalContent,
          content: originalContent,
          isDirty: false,
          history: [originalContent],
          historyIndex: 0,
        }),

      setLoading: (isLoading) => set({ isLoading }),
      setSaving: (isSaving) => set({ isSaving }),
      setPreviewLoading: (isPreviewLoading) => set({ isPreviewLoading }),

      resetDirty: () =>
        set((state) => ({
          originalContent: state.content,
          isDirty: false,
        })),

      setSelecting: (isSelecting) => set({ isSelecting }),

      setSelection: (selectedText, start, end) =>
        set({
          selectedText,
          selectionStart: start,
          selectionEnd: end,
        }),

      clearSelection: () =>
        set({
          selectedText: '',
          selectionStart: 0,
          selectionEnd: 0,
        }),

      setSelectedElement: (element) => set({ selectedElement: element }),
      setPreviewDevice: (device) => set({ previewDevice: device }),

      setCodeHeight: (height) => {
        // 只允许固定的几个高度值：0, 30, 80
        const validHeights = [0, 30, 80];
        const clampedHeight = validHeights.includes(height) ? height : 0;
        set({ codeHeight: clampedHeight });
        // 不再保存到 localStorage，每次进入编辑器都重置为 0%
      },

      undo: () =>
        set((state) => {
          if (state.historyIndex > 0) {
            const newIndex = state.historyIndex - 1;
            return {
              content: state.history[newIndex],
              historyIndex: newIndex,
              isDirty: state.history[newIndex] !== state.originalContent,
            };
          }
          return state;
        }),

      redo: () =>
        set((state) => {
          if (state.historyIndex < state.history.length - 1) {
            const newIndex = state.historyIndex + 1;
            return {
              content: state.history[newIndex],
              historyIndex: newIndex,
              isDirty: state.history[newIndex] !== state.originalContent,
            };
          }
          return state;
        }),
    }),
    {
      name: 'zeroy-editor-store',
    }
  )
);
