import { ChevronDown, ChevronUp } from 'lucide-react';

interface ResizableDividerProps {
  currentCodeHeight: number;
  onHeightChange: (newCodeHeight: number) => void;
}

// 固定的代码区高度选项（百分比）
export const HEIGHT_OPTIONS = [0, 30, 80];

// 检测是否是 Mac 系统
const isMac =
  typeof navigator !== 'undefined' &&
  navigator.platform.toUpperCase().includes('MAC');
const modifierKey = isMac ? '⌘' : 'Ctrl+';

export function ResizableDivider({
  currentCodeHeight,
  onHeightChange,
}: ResizableDividerProps) {
  // 找到当前高度在选项中的索引
  const getCurrentIndex = () => {
    // 找到最接近的选项
    let closestIndex = 0;
    let minDiff = Math.abs(HEIGHT_OPTIONS[0] - currentCodeHeight);

    for (let i = 1; i < HEIGHT_OPTIONS.length; i++) {
      const diff = Math.abs(HEIGHT_OPTIONS[i] - currentCodeHeight);
      if (diff < minDiff) {
        minDiff = diff;
        closestIndex = i;
      }
    }

    return closestIndex;
  };

  // 向上箭头：增加代码区高度（减少预览区）
  const handleIncreaseCodeHeight = () => {
    const currentIndex = getCurrentIndex();
    if (currentIndex < HEIGHT_OPTIONS.length - 1) {
      onHeightChange(HEIGHT_OPTIONS[currentIndex + 1]);
    }
  };

  // 向下箭头：减少代码区高度（增加预览区）
  const handleDecreaseCodeHeight = () => {
    const currentIndex = getCurrentIndex();
    if (currentIndex > 0) {
      onHeightChange(HEIGHT_OPTIONS[currentIndex - 1]);
    }
  };

  const currentIndex = getCurrentIndex();
  const canIncrease = currentIndex < HEIGHT_OPTIONS.length - 1;
  const canDecrease = currentIndex > 0;
  const isCollapsed = currentCodeHeight === 0;

  return (
    <div className="group relative z-10" style={{ height: '1px' }}>
      {/* 分隔线背景 */}
      <div className="absolute inset-x-0 top-0 h-px bg-gray-200" />

      {/* 箭头按钮容器 - 根据代码区状态决定位置 */}
      <div
        className={`-translate-x-1/2 absolute left-1/2 flex items-center gap-0.5 ${
          isCollapsed
            ? '-translate-y-full top-0' // 代码区隐藏时，显示在上方
            : 'top-0 translate-y-0' // 代码区显示时，显示在下方
        }`}
      >
        {/* 向上箭头：增加代码区 */}
        <button
          aria-label="增加代码区高度"
          className="flex h-5 w-9 items-center justify-center rounded-l-full border border-gray-200 bg-white shadow-sm transition-colors hover:border-blue-300 hover:bg-blue-50 hover:text-blue-600 disabled:cursor-not-allowed disabled:opacity-30"
          disabled={!canIncrease}
          onClick={handleIncreaseCodeHeight}
          title={`展开代码区 ${canIncrease ? `→ ${HEIGHT_OPTIONS[currentIndex + 1]}%` : '(已最大)'} (${modifierKey}K)`}
          type="button"
        >
          <ChevronUp className="h-3.5 w-3.5 text-gray-600" />
        </button>

        {/* 向下箭头：减少代码区 */}
        <button
          aria-label="减少代码区高度"
          className="flex h-5 w-9 items-center justify-center rounded-r-full border border-gray-200 border-l-0 bg-white shadow-sm transition-colors hover:border-blue-300 hover:bg-blue-50 hover:text-blue-600 disabled:cursor-not-allowed disabled:opacity-30"
          disabled={!canDecrease}
          onClick={handleDecreaseCodeHeight}
          title={`收起代码区 ${canDecrease ? `→ ${HEIGHT_OPTIONS[currentIndex - 1]}%` : '(已最小)'} (${modifierKey}K)`}
          type="button"
        >
          <ChevronDown className="h-3.5 w-3.5 text-gray-600" />
        </button>
      </div>
    </div>
  );
}
