/**
 * 浏览器能力检测
 * 检测是否支持图片优化所需的关键特性
 */

export interface BrowserCapabilities {
  webAssembly: boolean;
  webWorker: boolean;
  offscreenCanvas: boolean;
  broadcastChannel: boolean;
}

/**
 * 检测浏览器能力
 */
export function detectBrowserCapabilities(): BrowserCapabilities {
  return {
    // WebAssembly 支持（图片编码核心依赖）
    webAssembly: typeof WebAssembly !== 'undefined',

    // Web Worker 支持（并行处理依赖）
    webWorker: typeof Worker !== 'undefined',

    // OffscreenCanvas 支持（可选，提升性能）
    offscreenCanvas: typeof OffscreenCanvas !== 'undefined',

    // BroadcastChannel 支持（多 Tab 协调）
    broadcastChannel: typeof BroadcastChannel !== 'undefined',
  };
}

/**
 * 检查是否支持客户端图片优化
 * 返回 true 表示可以使用 Worker Pool
 */
export function supportsClientSideOptimization(): boolean {
  const caps = detectBrowserCapabilities();

  // 最低要求：WebAssembly + Web Worker
  return caps.webAssembly && caps.webWorker;
}

/**
 * 获取不支持的特性列表（用于错误提示）
 */
export function getUnsupportedFeatures(): string[] {
  const caps = detectBrowserCapabilities();
  const unsupported: string[] = [];

  if (!caps.webAssembly) {
    unsupported.push('WebAssembly');
  }
  if (!caps.webWorker) {
    unsupported.push('Web Worker');
  }

  return unsupported;
}
