/**
 * Parse executed PHP output and extract dynamic block inner HTML
 * between <!--zeroy:block:start:ID--> and <!--zeroy:block:end:ID-->
 */
export function extractDynamicBlocks(output: string): Map<string, string> {
  const marker =
    /<!--\s*zeroy:block:(start|end):([^:\s>]+)(?:[:\s][^>]*)?\s*-->/g;

  type Marker = {
    kind: 'start' | 'end';
    id: string;
    index: number;
    length: number;
  };

  const markers: Marker[] = [];
  let m: RegExpExecArray | null = marker.exec(output);
  while (m !== null) {
    markers.push({
      kind: m[1] as any,
      id: m[2],
      index: m.index,
      length: m[0].length,
    });
    m = marker.exec(output);
  }

  // Pair markers using a stack to support nesting
  const result = new Map<string, string>();
  const stack: Array<{ id: string; i: number }> = [];

  for (let i = 0; i < markers.length; i++) {
    const mk = markers[i];
    if (mk.kind === 'start') {
      stack.push({ id: mk.id, i });
    } else {
      // find last matching start
      for (let j = stack.length - 1; j >= 0; j--) {
        if (stack[j].id === mk.id) {
          const st = stack[j];
          stack.splice(j, 1);
          const s = markers[st.i];
          const inner = output.slice(s.index + s.length, mk.index);
          result.set(mk.id, inner);
          break;
        }
      }
    }
  }

  return result;
}
