import type React from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useMediaLibrary } from './hooks';
import { ImageEditorDialog } from './image-editor-dialog';
import { MediaActions } from './media-actions';
import { MediaGrid } from './media-grid';
import { MediaUpload } from './media-upload';
import type { MediaLibraryProps } from './types';

export const CustomMediaLibrary: React.FC<MediaLibraryProps> = ({
  isOpen,
  onClose,
}) => {
  const {
    data,
    isLoading,
    selectedItems,
    searchTerm,
    page,
    isUploading,
    editingItem,
    setSearchTerm,
    setPage,
    toggleSelection,
    handleInsert,
    handleCopyLinks,
    handleUpload,
    handleEdit,
    closeEditor,
    resetState,
    refetch,
  } = useMediaLibrary();

  // 拖拽状态（dragCounter 用于处理子元素的 dragenter/dragleave 事件）
  const [isDragging, setIsDragging] = useState(false);
  const dragCounterRef = useRef(0);

  // 当弹窗打开时自动刷新媒体库数据
  useEffect(() => {
    if (isOpen) {
      refetch();
    }
  }, [isOpen, refetch]);

  // 拖拽事件处理
  const handleDragEnter = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current += 1;
    if (e.dataTransfer.types.includes('Files')) {
      setIsDragging(true);
    }
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounterRef.current -= 1;
    if (dragCounterRef.current === 0) {
      setIsDragging(false);
    }
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setIsDragging(false);
      dragCounterRef.current = 0;

      const files = e.dataTransfer.files;
      if (files && files.length > 0) {
        // 过滤出图片、视频和 PDF 文件
        const mediaFiles = Array.from(files).filter(
          (file) =>
            file.type.startsWith('image/') ||
            file.type.startsWith('video/') ||
            file.type === 'application/pdf'
        );
        if (mediaFiles.length > 0) {
          const dt = new DataTransfer();
          for (const file of mediaFiles) {
            dt.items.add(file);
          }
          handleUpload(dt.files);
        }
      }
    },
    [handleUpload]
  );

  const handleClose = useCallback(() => {
    resetState();
    onClose();
  }, [onClose, resetState]);

  const handleInsertAndClose = useCallback(() => {
    handleInsert();
    handleClose();
  }, [handleInsert, handleClose]);

  const handleSearchChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setSearchTerm(e.target.value);
      setPage(1); // Reset to first page when searching
    },
    [setSearchTerm, setPage]
  );

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* Backdrop */}
      <div
        aria-label="关闭媒体库"
        className="fixed inset-0 z-40 bg-black/50"
        onClick={handleClose}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            handleClose();
          }
        }}
        role="button"
        tabIndex={0}
      />

      {/* Dialog */}
      <div className="pointer-events-none fixed inset-0 z-50 flex items-center justify-center p-4">
        {/* biome-ignore lint/a11y/useSemanticElements: 拖拽上传区域需要事件处理 */}
        {/* biome-ignore lint/nursery/noNoninteractiveElementInteractions: 拖拽上传是合理的交互 */}
        <div
          aria-label="媒体库，支持拖拽上传"
          className="pointer-events-auto relative h-[80vh] w-full max-w-6xl overflow-hidden rounded-lg bg-white shadow-xl"
          onDragEnter={handleDragEnter}
          onDragLeave={handleDragLeave}
          onDragOver={handleDragOver}
          onDrop={handleDrop}
          role="region"
        >
          {/* 拖拽上传覆盖层 */}
          {isDragging && (
            <div className="absolute inset-0 z-50 flex items-center justify-center bg-blue-500/90">
              <div className="text-center text-white">
                <svg
                  className="mx-auto mb-4 h-16 w-16"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <title>上传</title>
                  <path
                    d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                  />
                </svg>
                <p className="font-medium text-xl">松开鼠标上传文件</p>
                <p className="mt-1 text-sm opacity-80">支持图片、视频和 PDF</p>
              </div>
            </div>
          )}

          {/* Header */}
          <div className="flex items-center justify-between border-gray-200 border-b p-4">
            <div className="flex items-center gap-4">
              <h2 className="font-semibold text-gray-900 text-xl">媒体库</h2>
              <MediaUpload isUploading={isUploading} onUpload={handleUpload} />
            </div>
            <div className="flex items-center gap-4">
              <input
                className="rounded-md border border-gray-300 px-3 py-1.5 text-sm focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                onChange={handleSearchChange}
                placeholder="搜索媒体..."
                type="text"
                value={searchTerm}
              />
              <button
                className="text-gray-400 transition hover:text-gray-600"
                onClick={handleClose}
                type="button"
              >
                <svg
                  className="h-6 w-6"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <title>关闭</title>
                  <path
                    d="M6 18L18 6M6 6l12 12"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                  />
                </svg>
              </button>
            </div>
          </div>

          {/* Content */}
          <div className="flex h-[calc(100%-73px)]">
            {/* Media Grid */}
            <div className="flex-1 overflow-y-auto p-4">
              <MediaGrid
                data={data}
                isLoading={isLoading}
                onEdit={handleEdit}
                onPageChange={setPage}
                onToggleSelection={toggleSelection}
                page={page}
                selectedItems={selectedItems}
              />
            </div>

            {/* Actions Panel */}
            <MediaActions
              onCopyLinks={handleCopyLinks}
              onInsert={handleInsertAndClose}
              selectedItems={selectedItems}
            />
          </div>
        </div>
      </div>

      {/* Image Editor Dialog */}
      <ImageEditorDialog
        isOpen={!!editingItem}
        item={editingItem}
        onClose={closeEditor}
        onSuccess={refetch}
      />
    </>
  );
};
