import { useEffect, useRef } from 'react';
import {
  type CompletionReminderController,
  createCompletionReminderController,
} from './completion-reminder-controller';

interface WebKitAudioWindow extends Window {
  webkitAudioContext?: typeof AudioContext;
}

function createAudioReminder() {
  let audioContext: AudioContext | null = null;

  const getAudioContext = () => {
    if (audioContext) {
      return audioContext;
    }

    const AudioContextConstructor =
      window.AudioContext || (window as WebKitAudioWindow).webkitAudioContext;
    if (!AudioContextConstructor) {
      return null;
    }

    audioContext = new AudioContextConstructor();
    return audioContext;
  };

  const unlockSound = async () => {
    const context = getAudioContext();
    if (context?.state === 'suspended') {
      await context.resume();
    }
  };

  const playSound = async () => {
    const context = getAudioContext();
    if (!context) {
      return;
    }

    if (context.state === 'suspended') {
      await context.resume();
    }

    const oscillator = context.createOscillator();
    const gain = context.createGain();
    const now = context.currentTime;

    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(880, now);
    gain.gain.setValueAtTime(0.001, now);
    gain.gain.exponentialRampToValueAtTime(0.16, now + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.32);

    oscillator.connect(gain);
    gain.connect(context.destination);
    oscillator.onended = () => {
      oscillator.disconnect();
      gain.disconnect();
    };
    oscillator.start(now);
    oscillator.stop(now + 0.34);
  };

  return {
    unlockSound,
    playSound,
  };
}

function getNotificationPermission(): NotificationPermission {
  if (!('Notification' in window)) {
    return 'denied';
  }
  return Notification.permission;
}

function requestNotificationPermission(): Promise<NotificationPermission> {
  if (!('Notification' in window)) {
    return Promise.resolve('denied');
  }
  return Notification.requestPermission();
}

function showCompletionNotification(
  title: string,
  options: NotificationOptions,
  onClick: () => void
) {
  if (!('Notification' in window)) {
    return;
  }

  const notification = new Notification(title, options);
  notification.onclick = onClick;
}

function createBrowserCompletionReminder(): CompletionReminderController {
  const audioReminder = createAudioReminder();

  return createCompletionReminderController({
    getTitle: () => document.title,
    setTitle: (title) => {
      document.title = title;
    },
    isBackground: () =>
      document.visibilityState === 'hidden' || !document.hasFocus(),
    getNotificationPermission,
    requestNotificationPermission,
    showNotification: showCompletionNotification,
    focusWindow: () => window.focus(),
    unlockSound: audioReminder.unlockSound,
    playSound: audioReminder.playSound,
    setInterval: (callback, delay) => window.setInterval(callback, delay),
    clearInterval: (id) => window.clearInterval(id),
    setTimeout: (callback, delay) => window.setTimeout(callback, delay),
    clearTimeout: (id) => window.clearTimeout(id),
  });
}

export function useCompletionReminder(): CompletionReminderController {
  const controllerRef = useRef<CompletionReminderController | null>(null);

  if (!controllerRef.current) {
    controllerRef.current = createBrowserCompletionReminder();
  }

  useEffect(() => {
    const controller = controllerRef.current;
    if (!controller) {
      return;
    }

    const clearWhenEditorReturns = () => {
      if (document.visibilityState !== 'hidden' && document.hasFocus()) {
        controller.clear();
      }
    };

    document.addEventListener('visibilitychange', clearWhenEditorReturns);
    window.addEventListener('focus', clearWhenEditorReturns);

    return () => {
      document.removeEventListener('visibilitychange', clearWhenEditorReturns);
      window.removeEventListener('focus', clearWhenEditorReturns);
      controller.clear();
    };
  }, []);

  return controllerRef.current;
}
