type TimerId = number;

export interface CompletionReminderArmOptions {
  requestPermission: boolean;
}

export interface CompletionReminderRuntime {
  getTitle: () => string;
  setTitle: (title: string) => void;
  isBackground: () => boolean;
  getNotificationPermission: () => NotificationPermission;
  requestNotificationPermission?: () => Promise<NotificationPermission>;
  showNotification?: (
    title: string,
    options: NotificationOptions,
    onClick: () => void
  ) => void;
  focusWindow?: () => void;
  unlockSound?: () => Promise<void>;
  playSound?: () => Promise<void>;
  setInterval: (callback: () => void, delay: number) => TimerId;
  clearInterval: (id: TimerId) => void;
  setTimeout: (callback: () => void, delay: number) => TimerId;
  clearTimeout: (id: TimerId) => void;
}

export interface CompletionReminderController {
  arm: (options: CompletionReminderArmOptions) => void;
  complete: () => void;
  clear: () => void;
}

const COMPLETION_TITLE = 'AI 代码已完成 - zeroY';
const NOTIFICATION_TITLE = 'AI 代码生成完成';
const NOTIFICATION_BODY = '返回 zeroY 编辑器查看并插入生成代码。';
const TITLE_BLINK_INTERVAL_MS = 1000;
const TITLE_BLINK_SETTLE_MS = 20_000;

function ignoreAsyncError(promise: Promise<void> | undefined): void {
  promise?.catch(() => {
    // Reminder channels are best-effort; title state remains the durable cue.
  });
}

export function createCompletionReminderController(
  runtime: CompletionReminderRuntime
): CompletionReminderController {
  let baseTitle = runtime.getTitle();
  let intervalId: TimerId | null = null;
  let timeoutId: TimerId | null = null;
  let titleReminderActive = false;

  const clearTimers = () => {
    if (intervalId !== null) {
      runtime.clearInterval(intervalId);
      intervalId = null;
    }
    if (timeoutId !== null) {
      runtime.clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  const clear = () => {
    clearTimers();
    if (titleReminderActive) {
      runtime.setTitle(baseTitle);
      titleReminderActive = false;
    }
  };

  const arm = ({ requestPermission }: CompletionReminderArmOptions) => {
    clear();
    baseTitle = runtime.getTitle();

    ignoreAsyncError(runtime.unlockSound?.());

    if (
      requestPermission &&
      runtime.getNotificationPermission() === 'default' &&
      runtime.requestNotificationPermission
    ) {
      runtime.requestNotificationPermission().catch(() => 'default');
    }
  };

  const startTitleReminder = () => {
    clearTimers();
    titleReminderActive = true;
    runtime.setTitle(COMPLETION_TITLE);

    let showCompletionTitle = true;
    intervalId = runtime.setInterval(() => {
      showCompletionTitle = !showCompletionTitle;
      runtime.setTitle(showCompletionTitle ? COMPLETION_TITLE : baseTitle);
    }, TITLE_BLINK_INTERVAL_MS);

    timeoutId = runtime.setTimeout(() => {
      clearTimers();
      runtime.setTitle(COMPLETION_TITLE);
    }, TITLE_BLINK_SETTLE_MS);
  };

  const complete = () => {
    if (!runtime.isBackground()) {
      return;
    }

    startTitleReminder();

    if (
      runtime.getNotificationPermission() === 'granted' &&
      runtime.showNotification
    ) {
      runtime.showNotification(
        NOTIFICATION_TITLE,
        {
          body: NOTIFICATION_BODY,
          tag: 'zeroy-ai-generation-complete',
        },
        () => {
          runtime.focusWindow?.();
          clear();
        }
      );
    }

    ignoreAsyncError(runtime.playSound?.());
  };

  return {
    arm,
    complete,
    clear,
  };
}
