import type React from 'react';
import type { MediaItem } from './types';

interface ImageEditorDialogProps {
  item: MediaItem | null;
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

export const ImageEditorDialog: React.FC<ImageEditorDialogProps> = ({
  item,
  isOpen,
  onClose,
}) => {
  if (!(isOpen && item)) {
    return null;
  }

  return (
    <>
      {/* Backdrop */}
      <div
        aria-label="关闭图片编辑"
        className="fixed inset-0 z-[60] bg-black/70"
        onClick={onClose}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            onClose();
          }
        }}
        role="button"
        tabIndex={0}
      />

      {/* Dialog */}
      <div className="pointer-events-none fixed inset-0 z-[70] flex items-center justify-center p-4">
        <div className="pointer-events-auto w-full max-w-2xl overflow-hidden rounded-lg bg-white shadow-2xl">
          {/* Header */}
          <div className="flex items-center justify-between border-gray-200 border-b p-4">
            <h2 className="font-semibold text-gray-900 text-xl">图片详情</h2>
            <button
              className="text-gray-400 transition hover:text-gray-600"
              onClick={onClose}
              type="button"
            >
              <svg
                className="h-6 w-6"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <title>关闭</title>
                <path
                  d="M6 18L18 6M6 6l12 12"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                />
              </svg>
            </button>
          </div>

          {/* Content */}
          <div className="p-6">
            {/* Image Preview */}
            <div className="mb-6 flex justify-center rounded-lg bg-gray-100 p-4">
              {/* biome-ignore lint/performance/noImgElement: WordPress 环境，不使用 Next.js Image 组件 */}
              <img
                alt={item.alt || item.title}
                className="max-h-64 rounded object-contain"
                src={item.sizes?.medium?.url || item.url}
              />
            </div>

            {/* Image Info */}
            <div className="rounded-lg bg-gray-50 p-4">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <span className="font-medium text-gray-700">文件名：</span>
                  <span className="text-gray-600">{item.filename}</span>
                </div>
                <div>
                  <span className="font-medium text-gray-700">格式：</span>
                  <span className="text-gray-600">
                    {item.mime_type?.split('/')[1]?.toUpperCase() || 'Unknown'}
                  </span>
                </div>
                <div>
                  <span className="font-medium text-gray-700">尺寸：</span>
                  <span className="text-gray-600">
                    {item.width} × {item.height} px
                  </span>
                </div>
                <div>
                  <span className="font-medium text-gray-700">ID：</span>
                  <span className="text-gray-600">{item.id}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Footer */}
          <div className="flex justify-end border-gray-200 border-t bg-gray-50 p-4">
            <button
              className="rounded-md border border-gray-300 px-4 py-2 text-gray-700 text-sm transition hover:bg-gray-100"
              onClick={onClose}
              type="button"
            >
              关闭
            </button>
          </div>
        </div>
      </div>
    </>
  );
};
