import { useCallback, useEffect, useRef, useState } from 'react';
import type { PhpBlock } from './php-block-preprocessor';

interface PhpBlockOverlayProps {
  blocks: Map<string, PhpBlock>;
  containerRef: React.RefObject<HTMLElement | null>;
  selectedBlockId?: string | null;
  onBlockClick?: (blockId: string) => void;
}

interface OverlayPosition {
  top: number;
  left: number;
  width: number;
  height: number;
}

/**
 * Component that renders overlay markers for PHP blocks
 * These overlays are positioned absolutely and don't affect layout
 */
export function PhpBlockOverlay({
  blocks: _blocks, // Not used directly but passed for future enhancements
  containerRef,
  selectedBlockId,
  onBlockClick,
}: PhpBlockOverlayProps) {
  const [overlayPositions, setOverlayPositions] = useState<
    Map<string, OverlayPosition>
  >(new Map<string, OverlayPosition>());
  const rafRef = useRef<number | undefined>(undefined);

  // Helper to calculate position based on a reference element
  const calculatePosition = useCallback(
    (
      rect: DOMRect,
      containerRect: DOMRect,
      placement: 'bottom-right' | 'top-left' | 'top-left-offset'
    ): OverlayPosition => {
      const base = {
        width: 50,
        height: 18,
      };

      switch (placement) {
        case 'bottom-right':
          return {
            ...base,
            top: rect.bottom - containerRect.top - 20,
            left: rect.right - containerRect.left - 60,
          };
        case 'top-left':
          return {
            ...base,
            top: rect.top - containerRect.top,
            left: rect.left - containerRect.left,
          };
        case 'top-left-offset':
          return {
            ...base,
            top: rect.top - containerRect.top + 4,
            left: rect.left - containerRect.left + 4,
          };
        default:
          return base as OverlayPosition;
      }
    },
    []
  );

  // Helper to find and calculate position for a placeholder
  const findPlaceholderPosition = useCallback(
    (
      placeholder: Element,
      containerRect: DOMRect,
      container: HTMLElement
    ): OverlayPosition | null => {
      const prevSibling = placeholder.previousElementSibling as HTMLElement;
      const nextSibling = placeholder.nextElementSibling as HTMLElement;

      // Try previous sibling
      if (prevSibling && prevSibling.offsetHeight > 0) {
        return calculatePosition(
          prevSibling.getBoundingClientRect(),
          containerRect,
          'bottom-right'
        );
      }

      // Try next sibling
      if (nextSibling && nextSibling.offsetHeight > 0) {
        return calculatePosition(
          nextSibling.getBoundingClientRect(),
          containerRect,
          'top-left'
        );
      }

      // Fallback to parent
      const parent = placeholder.parentElement;
      if (parent && parent !== container) {
        return calculatePosition(
          parent.getBoundingClientRect(),
          containerRect,
          'top-left-offset'
        );
      }

      return null;
    },
    [calculatePosition]
  );

  // Calculate positions for all PHP block placeholders
  const updatePositions = useCallback(() => {
    if (!containerRef.current) {
      return;
    }

    const container = containerRef.current;
    const containerRect = container.getBoundingClientRect();
    const newPositions = new Map<string, OverlayPosition>();

    // Find all placeholders and dynamic wrappers
    const nodes = container.querySelectorAll(
      'script[type="application/x-zeroy-php"], [data-php-block-id]'
    );

    for (const node of nodes) {
      const el = node as HTMLElement;
      const blockId = el.dataset.blockId || el.dataset.phpBlockId;
      if (!blockId) {
        continue;
      }

      let position: OverlayPosition | null = null;
      if (el.matches('[data-php-block-id]')) {
        // Dynamic wrapper: use its own rect (top-left)
        position = calculatePosition(
          el.getBoundingClientRect(),
          containerRect,
          'top-left'
        );
      } else {
        // Placeholder script: infer from neighbors/parent
        position = findPlaceholderPosition(el, containerRect, container);
      }
      if (position) {
        newPositions.set(blockId, position);
      }
    }

    setOverlayPositions(newPositions);
  }, [containerRef, findPlaceholderPosition, calculatePosition]);

  // Update positions on mount and when blocks change
  useEffect(() => {
    updatePositions();

    // Debounced resize handler
    const handleResize = () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
      rafRef.current = requestAnimationFrame(updatePositions);
    };

    window.addEventListener('resize', handleResize);

    // Also observe container for mutations
    const observer = new MutationObserver(() => {
      handleResize();
    });

    if (containerRef.current) {
      observer.observe(containerRef.current, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['style', 'class'],
      });
    }

    return () => {
      window.removeEventListener('resize', handleResize);
      observer.disconnect();
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [updatePositions, containerRef]);

  return (
    <div
      style={{
        position: 'absolute',
        inset: 0,
        pointerEvents: 'none',
        zIndex: 999,
      }}
    >
      {Array.from(overlayPositions.entries()).map(([blockId, position]) => (
        <div
          key={blockId}
          style={{
            position: 'absolute',
            top: `${position.top}px`,
            left: `${position.left}px`,
            pointerEvents: 'none', // Container doesn't block
          }}
        >
          <button
            className={`zeroy-php-overlay ${selectedBlockId === blockId ? 'zeroy-php-overlay-selected' : ''}`}
            onClick={() => onBlockClick?.(blockId)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                onBlockClick?.(blockId);
              }
            }}
            style={{
              position: 'relative',
              width: '40px',
              height: '18px',
              pointerEvents: 'auto', // Only button is clickable
              border: 'none',
              padding: '2px 6px',
            }}
            title={`PHP Block: ${blockId}`}
            type="button"
          >
            <span className="zeroy-php-overlay-label">PHP</span>
          </button>
        </div>
      ))}
    </div>
  );
}

/**
 * Hook to manage PHP block overlays
 */
export function usePhpBlockOverlay(
  containerRef: React.RefObject<HTMLElement | null>
) {
  const [blocks, setBlocks] = useState<Map<string, PhpBlock>>(new Map());
  const [selectedBlockId, setSelectedBlockId] = useState<string | null>(null);

  const updateBlocks = useCallback((newBlocks: Map<string, PhpBlock>) => {
    setBlocks(newBlocks);
  }, []);

  const selectBlock = useCallback((blockId: string | null) => {
    setSelectedBlockId(blockId);
  }, []);

  return {
    blocks,
    selectedBlockId,
    updateBlocks,
    selectBlock,
    OverlayComponent: (
      <PhpBlockOverlay
        blocks={blocks}
        containerRef={containerRef}
        onBlockClick={selectBlock}
        selectedBlockId={selectedBlockId}
      />
    ),
  };
}
