import { useQuery } from '@tanstack/react-query';
import type React from 'react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { contentApi } from '@/api/content';
import { settingsApi } from '@/api/settings';
import { useNotification } from '@/components/notification';
import { RemoteNotificationsContainer } from '@/components/remote-notifications';
import {
  pauseOptimizationEngine,
  startOptimizationEngine,
} from '@/lib/optimization-engine';
import { detectTangibleTags } from '@/lib/tangible-detector';
import { useEditorStore } from '@/store/editor';
import { UnifiedAIDialog } from './components/ai-assistant';
import type { CodeEditorRef } from './components/code-editor';
import CodeEditor from './components/code-editor';
import { EditorLayout } from './components/editor-layout';
import { EditorToolbar } from './components/editor-toolbar';
import { PreviewPanel } from './components/preview-panel';
import { ProductionModeEducation } from './components/production-mode-education';
import {
  HEIGHT_OPTIONS,
  ResizableDivider,
} from './components/resizable-divider';
import { TangibleNotice } from './components/tangible-notice';
import { TokenRequired } from './components/token-required';

export const EditorApp: React.FC = () => {
  const { notify } = useNotification();
  const {
    setOriginalContent,
    setLoading,
    setContent,
    selectedElement,
    codeHeight,
    setCodeHeight,
  } = useEditorStore();
  const historyTimeoutRef = useRef<number | null>(null);
  const codeEditorRef = useRef<CodeEditorRef>(null);

  // Tangible migration and AI dialog state
  const [showTangibleNotice, setShowTangibleNotice] = useState(false);
  const [aiDialogOpen, setAIDialogOpen] = useState(false);
  const [aiInitialPrompt, setAIInitialPrompt] = useState<string>('');

  const postId = window.zeroyEditor?.postId;
  const hasApiToken = window.zeroyEditor?.aiSettings?.api_token?.trim();

  // 获取初始内容 - 必须在条件之前调用
  const { data, isLoading, error, isSuccess } = useQuery({
    queryKey: ['content', postId],
    queryFn: () => contentApi.get(postId ?? 0),
    enabled: !!postId && !!hasApiToken,
  });

  const content = useEditorStore((state) => state.content);

  // Detect Tangible tags in content
  const tangibleDetectionResult = useMemo(() => {
    return detectTangibleTags(content);
  }, [content]);

  // 获取设置数据以检查生产模式
  const { data: settingsData } = useQuery({
    queryKey: ['settings'],
    queryFn: () => settingsApi.get(),
    staleTime: 5 * 60 * 1000,
  });

  // Memoize the onChange handler with debounced history
  const handleContentChange = useCallback(
    (value: string) => {
      // Update content immediately without adding to history
      setContent(value, false);

      // Clear existing history timeout
      if (historyTimeoutRef.current !== null) {
        clearTimeout(historyTimeoutRef.current);
      }

      // Add to history after 2 second of no typing
      historyTimeoutRef.current = window.setTimeout(() => {
        setContent(value, true);
      }, 2000);
    },
    [setContent]
  );

  // Handle Tangible conversion by opening AI dialog
  const handleTangibleConversion = useCallback(() => {
    // 首先全选编辑器中的所有代码
    if (codeEditorRef.current) {
      codeEditorRef.current.selectAll();
    }

    // 创建简洁的提示词，不包含完整代码
    const detectedTagsList = Object.entries(tangibleDetectionResult.tagCounts)
      .map(([tag, count]) => `${tag} (${count})`)
      .join(', ');

    const migrationPrompt = `将选中的 Tangible 模板代码转换为现代 PHP 代码。

检测到的标签: ${detectedTagsList}

转换要求:
- 使用 WordPress 函数替代 Tangible 标签
- Loop 转为 foreach/WP_Query
- Field 转为 get_field/get_post_meta
- If 转为 PHP if 语句
- 保持 HTML 结构和样式不变
- 添加必要的错误处理`;

    // Set initial prompt and open AI dialog
    setAIInitialPrompt(migrationPrompt);
    setAIDialogOpen(true);
    setShowTangibleNotice(false);
  }, [tangibleDetectionResult]);

  // Handle AI dialog close
  const handleAIDialogClose = useCallback(() => {
    setAIDialogOpen(false);
    setAIInitialPrompt('');
  }, []);

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (historyTimeoutRef.current !== null) {
        clearTimeout(historyTimeoutRef.current);
      }
    };
  }, []);

  // 启动后台图片优化引擎（只做原格式压缩，不做 WebP/AVIF 转换）
  useEffect(() => {
    console.log('[EditorApp] 编辑器已加载，启动后台优化引擎（仅压缩）');
    startOptimizationEngine();

    return () => {
      console.log('[EditorApp] 编辑器卸载，暂停后台优化引擎');
      pauseOptimizationEngine();
    };
  }, []);

  // Cmd/Ctrl + K 快捷键：循环切换代码区高度 (0% -> 30% -> 80% -> 0%)
  useEffect(() => {
    // 切换高度的公共函数
    const cycleCodeHeight = () => {
      const currentIndex = HEIGHT_OPTIONS.indexOf(codeHeight);
      const nextIndex =
        currentIndex === -1 ? 0 : (currentIndex + 1) % HEIGHT_OPTIONS.length;
      setCodeHeight(HEIGHT_OPTIONS[nextIndex]);
    };

    // 处理键盘事件
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        cycleCodeHeight();
      }
    };

    // 处理来自 iframe 的消息（当焦点在预览区时）
    const handleMessage = (e: MessageEvent) => {
      if (e.data?.type === 'SHORTCUT_CMD_K') {
        cycleCodeHeight();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('message', handleMessage);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('message', handleMessage);
    };
  }, [codeHeight, setCodeHeight]);

  // Show Tangible notice when tags are detected
  useEffect(() => {
    setShowTangibleNotice(tangibleDetectionResult.hasTangibleTags);
  }, [tangibleDetectionResult.hasTangibleTags]);

  // Highlight selected element in code editor
  useEffect(() => {
    if (selectedElement && codeEditorRef.current) {
      codeEditorRef.current.highlightPosition({
        elementId: selectedElement.id,
        start: {
          line: 0,
          column: 0,
          offset: selectedElement.start,
        },
        end: {
          line: 0,
          column: 0,
          offset: selectedElement.end,
        },
      });
    } else if (codeEditorRef.current) {
      codeEditorRef.current.clearHighlight();
    }
  }, [selectedElement]);

  // 合并所有副作用到一个 useEffect 中
  useEffect(() => {
    // 同步加载状态
    setLoading(isLoading);

    // 设置初始内容
    if (isSuccess && data?.content) {
      setOriginalContent(data.content);
    }

    // 处理错误
    if (error) {
      notify('error', `加载内容失败：${(error as Error).message}`);
    }
  }, [
    isLoading,
    isSuccess,
    data,
    error,
    setLoading,
    setOriginalContent,
    notify,
  ]);

  // 处理高度切换
  const handleHeightChange = useCallback(
    (newCodeHeight: number) => {
      setCodeHeight(newCodeHeight);
    },
    [setCodeHeight]
  );

  // 计算预览区高度
  const previewHeight = 100 - codeHeight;

  // 如果没有 API Token，显示设置提示
  if (!hasApiToken) {
    return <TokenRequired postId={postId || 0} />;
  }

  return (
    <EditorLayout>
      <EditorToolbar />
      <div className="editor-main-container flex flex-1 flex-col overflow-hidden">
        {/* 远程通知 - 仅显示高优先级 */}
        <RemoteNotificationsContainer
          className="mx-4 mt-2"
          maxDisplay={2}
          priorityFilter={['high']}
        />
        <ProductionModeEducation
          isProductionMode={!!settingsData?.settings?.production_mode}
        />
        {showTangibleNotice && (
          <TangibleNotice
            detectionResult={tangibleDetectionResult}
            onConvert={handleTangibleConversion}
          />
        )}
        <div
          className="overflow-hidden"
          style={{ height: `${previewHeight}%` }}
        >
          <PreviewPanel
            content={content}
            designSystemHtml={window.zeroyEditor?.designSystemHtml}
            extractedTailwindConfig={
              window.zeroyEditor?.extractedTailwindConfig
            }
            fontCss={window.zeroyEditor?.fontCss}
          />
        </div>
        <ResizableDivider
          currentCodeHeight={codeHeight}
          onHeightChange={handleHeightChange}
        />
        <div className="overflow-hidden" style={{ height: `${codeHeight}%` }}>
          <CodeEditor
            onChange={handleContentChange}
            ref={codeEditorRef}
            value={content}
          />
        </div>
      </div>

      <UnifiedAIDialog
        initialPrompt={aiInitialPrompt}
        isOpen={aiDialogOpen}
        onClose={handleAIDialogClose}
      />
    </EditorLayout>
  );
};
