import { useMemo } from 'react';
import { PreviewContentGenerator } from './preview-content-generator';
import {
  messageHandlerScript,
  ScriptManager,
  selectionHandlerScript,
  // phpBlockScript is no longer needed - PHP blocks are preprocessed
} from './script-manager';
import {
  createStyleModule,
  StyleManager,
  selectionModeStyles,
} from './style-manager';
import type { PreviewConfig, PreviewResource } from './types';

/**
 * Swiper.js CDN resources for preview
 */
const SWIPER_VERSION = '11.1.15';
const swiperCSSResource: PreviewResource = {
  id: 'swiper-css',
  type: 'link',
  content: '',
  attributes: {
    rel: 'stylesheet',
    href: `https://cdn.jsdelivr.net/npm/swiper@${SWIPER_VERSION}/swiper-bundle.min.css`,
  },
};
const swiperJSResource: PreviewResource = {
  id: 'swiper-js',
  type: 'script',
  content: '',
  attributes: {
    src: `https://cdn.jsdelivr.net/npm/swiper@${SWIPER_VERSION}/swiper-bundle.min.js`,
  },
};

/**
 * Hook to manage preview modules
 */
export function usePreviewModules() {
  const styleManager = useMemo(() => {
    const manager = new StyleManager();

    // Register default style modules
    manager.register(selectionModeStyles);

    return manager;
  }, []);

  const scriptManager = useMemo(() => {
    const manager = new ScriptManager();

    // Register default script modules
    // phpBlockScript removed - PHP blocks are now preprocessed as inert placeholders
    manager.register(messageHandlerScript);
    manager.register(selectionHandlerScript);

    return manager;
  }, []);

  const contentGenerator = useMemo(() => {
    const generator = new PreviewContentGenerator(styleManager, scriptManager);

    // Add Swiper.js resources for preview (always loaded in editor)
    generator.addExternalResource(swiperCSSResource);
    generator.addExternalResource(swiperJSResource);

    return generator;
  }, [styleManager, scriptManager]);

  const generatePreviewContent = (config: PreviewConfig) => {
    return contentGenerator.generate(config);
  };

  const addCustomStyle = (
    id: string,
    name: string,
    styles: string,
    priority = 50
  ) => {
    const module = createStyleModule(id, name, styles, priority);
    styleManager.register(module);
  };

  const removeCustomStyle = (id: string) => {
    styleManager.unregister(id);
  };

  return {
    styleManager,
    scriptManager,
    contentGenerator,
    generatePreviewContent,
    addCustomStyle,
    removeCustomStyle,
  };
}
