import type { Message, MessageType } from '../types/messages';

export type MessageHandler = (message: Message) => void | Promise<void>;

export class MessageBus {
  private static instance: MessageBus | null = null;

  private handlers: Map<MessageType, Set<MessageHandler>> = new Map();
  private pendingMessages: Message[] = [];
  private isReady = false;
  private messageId = 0;
  private responseHandlers: Map<string, (response: Message) => void> =
    new Map();
  private timeout = 5000; // 5 seconds default timeout

  private target: Window | null = null;

  private constructor(target: Window | null = null) {
    this.target = target;
    if (typeof window !== 'undefined') {
      window.addEventListener('message', this.handleMessage);
    }
  }

  static getInstance(): MessageBus {
    if (!MessageBus.instance) {
      MessageBus.instance = new MessageBus();
    }
    return MessageBus.instance;
  }

  private handleMessage = (event: MessageEvent) => {
    if (!event.data || typeof event.data !== 'object' || !event.data.type) {
      return;
    }

    const message = event.data as Message;

    // Handle response messages
    if (message.id && this.responseHandlers.has(message.id)) {
      const handler = this.responseHandlers.get(message.id);
      this.responseHandlers.delete(message.id);
      handler?.(message);
      return;
    }

    // Handle regular messages
    const handlers = this.handlers.get(message.type);
    if (handlers) {
      for (const handler of handlers) {
        try {
          handler(message);
        } catch (error) {
          console.error(`Error handling message ${message.type}:`, error);
        }
      }
    }
  };

  on(type: MessageType, handler: MessageHandler): () => void {
    if (!this.handlers.has(type)) {
      this.handlers.set(type, new Set());
    }

    const handlersSet = this.handlers.get(type);
    if (handlersSet) {
      handlersSet.add(handler);
    }

    // Return unsubscribe function
    return () => {
      const handlers = this.handlers.get(type);
      if (handlers) {
        handlers.delete(handler);
        if (handlers.size === 0) {
          this.handlers.delete(type);
        }
      }
    };
  }

  off(type: MessageType, handler: MessageHandler): void {
    const handlers = this.handlers.get(type);
    if (handlers) {
      handlers.delete(handler);
      if (handlers.size === 0) {
        this.handlers.delete(type);
      }
    }
  }

  send<T extends Message>(message: Omit<T, 'id' | 'timestamp'>): void {
    const fullMessage = {
      ...message,
      id: this.generateId(),
      timestamp: Date.now(),
    } as T;

    if (this.isReady && this.target) {
      this.target.postMessage(fullMessage, '*');
    } else {
      this.pendingMessages.push(fullMessage);
    }
  }

  sendAndWait<T extends Message, R = Message>(
    message: Omit<T, 'id' | 'timestamp'>
  ): Promise<R> {
    return new Promise((resolve, reject) => {
      const id = this.generateId();
      const fullMessage = {
        ...message,
        id,
        timestamp: Date.now(),
      } as T;

      const timeoutId = setTimeout(() => {
        this.responseHandlers.delete(id);
        reject(
          new Error(`Message ${message.type} timed out after ${this.timeout}ms`)
        );
      }, this.timeout);

      this.responseHandlers.set(id, (response) => {
        clearTimeout(timeoutId);
        resolve(response as R);
      });

      if (this.isReady && this.target) {
        this.target.postMessage(fullMessage, '*');
      } else {
        this.pendingMessages.push(fullMessage);
      }
    });
  }

  setTarget(target: Window): void {
    this.target = target;
    this.setReady(true);
  }

  setReady(ready: boolean): void {
    this.isReady = ready;

    if (ready && this.target) {
      // Send all pending messages
      while (this.pendingMessages.length > 0) {
        const message = this.pendingMessages.shift();
        if (message) {
          this.target.postMessage(message, '*');
        }
      }
    }
  }

  setTimeout(timeout: number): void {
    this.timeout = timeout;
  }

  private generateId(): string {
    return `msg_${Date.now()}_${++this.messageId}`;
  }

  destroy(): void {
    if (typeof window !== 'undefined') {
      window.removeEventListener('message', this.handleMessage);
    }
    this.handlers.clear();
    this.pendingMessages = [];
    this.responseHandlers.clear();
  }
}
