import type { ScriptModule } from './types';

/**
 * Script Manager for preview panel
 * Manages JavaScript code injection into the preview iframe
 */
export class ScriptManager {
  private modules: Map<string, ScriptModule> = new Map();

  /**
   * Register a script module
   */
  register(module: ScriptModule): void {
    this.modules.set(module.id, module);
  }

  /**
   * Unregister a script module
   */
  unregister(moduleId: string): void {
    this.modules.delete(moduleId);
  }

  /**
   * Get all scripts sorted by priority
   */
  getAllScripts(): string[] {
    const sortedModules = Array.from(this.modules.values()).sort(
      (a, b) => a.priority - b.priority
    );

    return sortedModules.map((module) => module.getScript());
  }

  /**
   * Generate a combined script
   */
  generateCombinedScript(): string {
    return this.getAllScripts().join('\n\n');
  }
}

// Pre-defined script modules
export const messageHandlerScript: ScriptModule = {
  id: 'message-handler',
  name: 'Message Handler',
  priority: 10,
  getScript: () => `
    // Send ready message
    window.parent.postMessage({ type: 'IFRAME_READY' }, '*');

    // Forward keyboard shortcuts to parent window
    // This ensures shortcuts work even when iframe has focus
    window.addEventListener('keydown', (e) => {
      // Cmd/Ctrl + K: Toggle code panel height
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        window.parent.postMessage({ type: 'SHORTCUT_CMD_K' }, '*');
      }
    });

    // Keep last known dynamic blocks (executed PHP output) so we can re-apply after content updates
    window.__zeroyDynamicBlocks = {};

    function disablePreviewHtmx(root) {
      try {
        const elements = [];
        if (root && root.nodeType === Node.ELEMENT_NODE) {
          elements.push(root);
        }
        if (root && typeof root.querySelectorAll === 'function') {
          root.querySelectorAll('*').forEach((el) => elements.push(el));
        }

        elements.forEach((el) => {
          const attrs = Array.from(el.attributes || []);
          attrs.forEach((attr) => {
            if (/^hx-/i.test(attr.name)) {
              el.setAttribute('data-preview-' + attr.name, attr.value);
              el.removeAttribute(attr.name);
            }
          });
        });
      } catch (e) {
        // no-op
      }
    }

    function applyDynamicBlocks() {
      try {
        const blocks = window.__zeroyDynamicBlocks || {};
        const root = document.getElementById('preview-content');
        if (!root || !blocks) return;

        for (const id in blocks) {
          const html = blocks[id];
          // placeholder script for this block
          const ph = root.querySelector('script[type="application/x-zeroy-php"][data-block-id="' + id + '"]');
          if (!ph) continue;

          // Create a wrapper for executed HTML so layout is preserved
          const wrapper = document.createElement('div');
          wrapper.setAttribute('data-php-block-id', id);
          // Unify selection path: give it a data-element-id too
          wrapper.setAttribute('data-element-id', id);
          wrapper.classList.add('zeroy-php-block');
          try {
            wrapper.innerHTML = html;
            disablePreviewHtmx(wrapper);
          } catch {}

          // Replace placeholder with dynamic wrapper
          ph.parentNode && ph.parentNode.replaceChild(wrapper, ph);
        }
      } catch (e) {
        // no-op
      }
    }

    // Execute scripts that were inserted via innerHTML (they don't run automatically)
    function executeInlineScripts(container) {
      const scripts = container.querySelectorAll('script:not([type]), script[type="text/javascript"]');
      scripts.forEach(function(oldScript) {
        const newScript = document.createElement('script');
        // Copy attributes
        Array.from(oldScript.attributes).forEach(function(attr) {
          newScript.setAttribute(attr.name, attr.value);
        });
        // Copy content
        newScript.textContent = oldScript.textContent;
        // Replace old script with new one to trigger execution
        oldScript.parentNode.replaceChild(newScript, oldScript);
      });

      // Re-dispatch DOMContentLoaded for scripts that depend on it
      // (since the real event fired before content was inserted)
      if (scripts.length > 0) {
        document.dispatchEvent(new Event('DOMContentLoaded'));
      }
    }

    // Handle messages from parent
    window.addEventListener('message', (event) => {
      if (event.data.type === 'UPDATE_CONTENT') {
        const container = document.getElementById('preview-content');
        container.innerHTML = event.data.payload.content;
        disablePreviewHtmx(container);
        // Execute user scripts (e.g., Swiper initialization)
        executeInlineScripts(container);
        // Note: PHP blocks are now handled as inert script placeholders
        // No need to wrap them as they don't affect layout
        // If we already have executed PHP blocks, re-apply them on top of updated content
        applyDynamicBlocks();
        
        // Re-apply selection state if needed
        if (window.selectedElement && window.selectedElement.dataset.elementId) {
          const id = window.selectedElement.dataset.elementId;
          // Prefer dynamic wrapper if exists
          let selector = '[data-php-block-id="' + id + '"]';
          let newSelected = document.querySelector(selector);
          if (!newSelected) {
            selector = '[data-element-id="' + id + '"]';
            newSelected = document.querySelector(selector);
          }
          if (newSelected) {
            window.selectedElement = newSelected;
            if (newSelected.getAttribute('data-php-block-id')) {
              newSelected.classList.add('zeroy-dyn-selected');
            } else {
              newSelected.classList.add('element-selected');
            }
          }
        }
      } else if (event.data.type === 'UPDATE_DYNAMIC_BLOCKS') {
        // Payload: { blocks: [{id, html}] }
        const payload = event.data.payload || {};
        const list = payload.blocks || [];
        const map = {};
        for (const b of list) {
          if (b && b.id) map[b.id] = b.html || '';
        }
        window.__zeroyDynamicBlocks = map;
        applyDynamicBlocks();
      } else if (event.data.type === 'SET_SELECTION_MODE') {
        window.isSelectionMode = event.data.payload.enabled;
        document.body.classList.toggle('selection-mode', window.isSelectionMode);
        
        if (!window.isSelectionMode) {
          if (window.hoveredElement) {
            window.hoveredElement.classList.remove('element-hover');
            window.hoveredElement.classList.remove('zeroy-dyn-hover');
            window.hoveredElement = null;
          }
          if (window.selectedElement) {
            window.selectedElement.classList.remove('element-selected');
            window.selectedElement.classList.remove('zeroy-dyn-selected');
            window.selectedElement = null;
          }
        }
      }
    });
`,
};

