export const selectionHandlerScript: ScriptModule = {
  id: 'selection-handler',
  name: 'Selection Handler',
  priority: 20,
  getScript: () => `
    // Initialize selection state
    window.isSelectionMode = false;
    window.hoveredElement = null;
    window.selectedElement = null;

    // === 全局点击事件拦截 - 屏蔽预览区所有默认交互 ===
    // 使用捕获阶段确保在所有其他事件处理器之前执行
    document.addEventListener('click', (e) => {
      // 处于选取模式时放行，让下方 selection handler 处理并阻止默认行为
      if (window.isSelectionMode) {
        return;
      }

      const target = e.target;

      // 检查是否点击了交互元素（链接、按钮、表单等）
      if (target && typeof target.closest === 'function') {
        const interactiveElement = target.closest('a, button, [onclick], input[type="submit"], input[type="button"], form');
        if (interactiveElement) {
          e.preventDefault();
          e.stopPropagation();
          e.stopImmediatePropagation();
          return false;
        }
      }
    }, { capture: true });

    // Handle hover in selection mode
    document.addEventListener('mouseover', (e) => {
      if (!window.isSelectionMode) return;

      const raw = e.target;
      let target = null;
      // Plain JS runtime inside iframe
      if (raw && typeof (raw).closest === 'function') {
        // Try dynamic php wrapper, then normal elements
        target = (raw).closest('[data-php-block-id], [data-element-id]');
      } else {
        let el = raw;
        while (el && el !== document && !(el.dataset && (el.dataset.phpBlockId || el.dataset.elementId))) {
          el = el.parentElement;
        }
        if (el && el.dataset && (el.dataset.phpBlockId || el.dataset.elementId)) target = el;
      }

      if (target && target !== window.hoveredElement) {
        if (window.hoveredElement) {
          window.hoveredElement.classList.remove('element-hover');
          window.hoveredElement.classList.remove('zeroy-dyn-hover');
        }
        if (target.dataset && target.dataset.phpBlockId) {
          target.classList.add('zeroy-dyn-hover');
        } else {
          target.classList.add('element-hover');
        }
        window.hoveredElement = target;
      } else if (!target && window.hoveredElement) {
        window.hoveredElement.classList.remove('element-hover');
        window.hoveredElement.classList.remove('zeroy-dyn-hover');
        window.hoveredElement = null;
      }
    });

    document.addEventListener('mouseout', (e) => {
      if (!window.isSelectionMode) return;
      const to = (e && e.relatedTarget) || null;
      const hovered = window.hoveredElement;
      if (hovered && (!to || !(hovered.contains && hovered.contains(to)))) {
        hovered.classList.remove('element-hover');
        hovered.classList.remove('zeroy-dyn-hover');
        window.hoveredElement = null;
      }
    });

    // Extra safety: clear hover when leaving the iframe or losing focus
    window.addEventListener('blur', () => {
      const hovered = window.hoveredElement;
      if (hovered) {
        hovered.classList.remove('element-hover');
        hovered.classList.remove('zeroy-dyn-hover');
        window.hoveredElement = null;
      }
    });
    document.addEventListener('mouseleave', () => {
      const hovered = window.hoveredElement;
      if (hovered) {
        hovered.classList.remove('element-hover');
        hovered.classList.remove('zeroy-dyn-hover');
        window.hoveredElement = null;
      }
    });

    // Handle click in selection mode
    document.addEventListener('click', (e) => {
      if (!window.isSelectionMode) return;
      
      e.preventDefault();
      e.stopPropagation();
      
      const raw = e.target;
      let target = null;
      if (raw && typeof (raw).closest === 'function') {
        target = (raw).closest('[data-php-block-id], [data-element-id]');
      } else {
        let el = raw;
        while (el && el !== document && !(el.dataset && (el.dataset.phpBlockId || el.dataset.elementId))) {
          el = el.parentElement;
        }
        if (el && el.dataset && (el.dataset.phpBlockId || el.dataset.elementId)) target = el;
      }

      if (target && target.dataset && target.dataset.elementId) {
        if (window.selectedElement) {
          window.selectedElement.classList.remove('element-selected');
          window.selectedElement.classList.remove('zeroy-dyn-selected');
        }
        if (target.dataset.phpBlockId) {
          target.classList.add('zeroy-dyn-selected');
        } else {
          target.classList.add('element-selected');
        }
        window.selectedElement = target;
        const phpIds = [];
        if (target.classList.contains('zeroy-php-block') || target.dataset.phpBlockId) {
          phpIds.push(target.dataset.elementId);
        } else {
          target.querySelectorAll('.zeroy-php-block').forEach((el) => {
            if (el.dataset && el.dataset.elementId) {
              phpIds.push(el.dataset.elementId);
            }
          });
        }
        window.parent.postMessage({
          type: 'ELEMENT_CLICKED',
          payload: {
            elementId: target.dataset.elementId,
            phpBlockIds: phpIds
          }
        }, '*');
        if (target.classList.contains('zeroy-php-block')) {
          const rect = target.getBoundingClientRect();
          const hint = document.createElement('div');
          hint.textContent = '这是个动态元素';
          hint.style.position = 'fixed';
          hint.style.top = rect.top + 'px';
          hint.style.left = rect.left + 'px';
          hint.style.padding = '4px 8px';
          hint.style.background = 'rgba(0,0,0,0.75)';
          hint.style.color = '#fff';
          hint.style.fontSize = '12px';
          hint.style.borderRadius = '4px';
          hint.style.pointerEvents = 'none';
          hint.style.zIndex = '2147483647';
          hint.style.opacity = '1';
          hint.style.transition = 'opacity 300ms ease';
          document.body.appendChild(hint);
          setTimeout(() => {
            hint.style.opacity = '0';
            setTimeout(() => hint.remove(), 320);
          }, 1000);
        }
      } else {
        // Lightweight hint when no selectable element is found
        const now = Date.now();
        const last = window.lastNoSelectHintAt || 0;
        if (!last || now - last > 800) {
          window.lastNoSelectHintAt = now;
          const hint = document.createElement('div');
          hint.textContent = '未选中元素，请尝试点击更外层区域';
          hint.style.position = 'fixed';
          hint.style.top = Math.min(window.innerHeight - 40, e.clientY + 12) + 'px';
          hint.style.left = Math.min(window.innerWidth - 240, e.clientX + 12) + 'px';
          hint.style.padding = '6px 10px';
          hint.style.background = 'rgba(0, 0, 0, 0.75)';
          hint.style.color = '#fff';
          hint.style.fontSize = '12px';
          hint.style.lineHeight = '1';
          hint.style.borderRadius = '4px';
          hint.style.pointerEvents = 'none';
          hint.style.zIndex = '2147483647';
          hint.style.opacity = '1';
          hint.style.transition = 'opacity 300ms ease';
          document.body.appendChild(hint);
          setTimeout(() => {
            hint.style.opacity = '0';
            setTimeout(() => hint.remove(), 320);
          }, 1000);
        }
      }
    });
  `,
};

/**
 * Create a custom script module
 */
export function createScriptModule(
  id: string,
  name: string,
  script: string,
  priority = 50
): ScriptModule {
  return {
    id,
    name,
    priority,
    getScript: () => script,
  };
}
