import { useMutation } from '@tanstack/react-query';
import { debounce } from 'lodash-es';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { phpApi } from '@/api/php';
import { parseDesignSystem } from '@/lib/tailwind-config-parser';
import { useEditorStore } from '@/store/editor';
import type { ElementMapping } from '../core/parser/html-position-mapper';
import { HtmlPositionMapper } from '../core/parser/html-position-mapper';
import { usePreviewModules } from '../preview';
import { usePhpBlockOverlay } from '../preview/php-block-overlay';
import {
  buildSafeToRawMapper,
  preprocessPhpBlocks,
} from '../preview/php-block-preprocessor';
import { extractDynamicBlocks } from '../preview/php-output-parser';
import { MessageBus } from '../services/message-bus';
import LoadingSpinner from './common/loading-spinner';

// Preview helper legacy code removed; using PHP preprocessor + mapping only.

interface PreviewPanelProps {
  content: string;
  extractedTailwindConfig?: string;
  designSystemHtml?: string;
  fontCss?: string;
}

export function PreviewPanel({
  content,
  extractedTailwindConfig,
  designSystemHtml,
  fontCss,
}: PreviewPanelProps) {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const [isIframeReady, setIsIframeReady] = useState(false);
  const [phpOutput, setPhpOutput] = useState<string | null>(null);
  const [phpError, setPhpError] = useState<string | null>(null);
  const isSelecting = useEditorStore((state) => state.isSelecting);
  const setSelectedElement = useEditorStore(
    (state) => state.setSelectedElement
  );
  const previewDevice = useEditorStore((state) => state.previewDevice);

  // Keep a stable reference to the position mapper
  const positionMapperRef = useRef<HtmlPositionMapper>(
    new HtmlPositionMapper()
  );
  // Mapping for PHP mode (elementId -> mapping with adjusted offsets)
  const phpElementMapRef = useRef<Map<string, ElementMapping>>(new Map());
  const messageBus = useMemo(() => MessageBus.getInstance(), []);

  // PHP execution mutation
  const phpExecuteMutation = useMutation({
    mutationFn: (code: string) =>
      phpApi.execute({
        code,
        post_id: window.zeroyEditor?.postId,
      }),
    onSuccess: (data) => {
      if (data.success) {
        setPhpOutput(data.output);
        setPhpError(null);
      } else {
        setPhpError(data.error || 'PHP execution failed');
        setPhpOutput(data.output || '');
      }
    },
    onError: (error) => {
      setPhpError(error instanceof Error ? error.message : 'Unknown error');
      setPhpOutput(null);
    },
  });

  // Check if content contains PHP code
  const hasPhpCode = useMemo(() => {
    return content.includes('<?php') || content.includes('<?=');
  }, [content]);

  // Container ref for overlay positioning
  const previewContainerRef = useRef<HTMLDivElement>(null);

  // PHP block overlay management
  const { updateBlocks, OverlayComponent } =
    usePhpBlockOverlay(previewContainerRef);

  // Store the mapper for safe→raw selection mapping
  const safeToRawMapperRef = useRef<ReturnType<
    typeof buildSafeToRawMapper
  > | null>(null);

  // Process PHP content with the new preprocessor
  const processPhpContent = useCallback(
    (src: string) => {
      // Preprocess PHP blocks into safe placeholders
      const {
        html: processedHtml,
        blocks,
        replacements,
      } = preprocessPhpBlocks(src);

      // Update overlay blocks
      updateBlocks(blocks);

      // Store the mapper for selection mapping
      safeToRawMapperRef.current = buildSafeToRawMapper(replacements);

      // Parse and instrument the processed HTML
      const mapper = new HtmlPositionMapper('php-');
      const { document, mappings } = mapper.parseHtml(processedHtml);
      const htmlWithIds = mapper.serializeWithIds(document);

      // Build element mapping with safe positions (will be mapped to raw later)
      const mapping = new Map<string, ElementMapping>();
      for (const [, m] of mappings) {
        mapping.set(m.elementId, {
          elementId: m.elementId,
          tagName: m.tagName,
          attributes: m.attributes,
          position: m.position, // These are safe positions
        });
      }

      // Add PHP block mappings
      for (const [blockId] of blocks) {
        // Find the replacement for this block to get safe positions
        const replacement = replacements.find((r) => r.id === blockId);
        if (replacement) {
          mapping.set(blockId, {
            elementId: blockId,
            tagName: 'php',
            attributes: {},
            position: {
              elementId: blockId,
              // Store safe positions (will be mapped to raw in handleElementClick)
              start: { line: 0, column: 0, offset: replacement.safeStart },
              end: { line: 0, column: 0, offset: replacement.safeEnd },
            },
          });
        }
      }

      return { code: htmlWithIds, mapping };
    },
    [updateBlocks]
  );

  // Debounced PHP execution function
  const debouncedPhpExecute = useMemo(
    () =>
      debounce((code: string) => {
        if (hasPhpCode && isIframeReady) {
          // Process PHP content to get mapping and safe HTML for preview
          const { mapping, code: safePreviewHtml } = processPhpContent(code);
          phpElementMapRef.current = mapping;

          // Render the preprocessed safe HTML into the iframe so data-element-id
          // stays in sync with our mapping (stable selection→code mapping)
          messageBus.send({
            type: 'UPDATE_CONTENT',
            payload: {
              content: safePreviewHtml,
            },
          } as any);

          // Optionally still execute the ORIGINAL code (for future features),
          // but do not use its HTML to replace the iframe content, as that
          // would break the ID mapping between preview and source.
          phpExecuteMutation.mutate(code);
        }
      }, 1500), // 1.5 second debounce
    [
      hasPhpCode,
      isIframeReady,
      phpExecuteMutation.mutate,
      processPhpContent,
      messageBus,
    ]
  );

  // Parse HTML and update iframe content
  const updateContent = useCallback(() => {
    if (!isIframeReady) {
      return;
    }

    // If content has PHP, don't process here - let the debounced function handle it
    if (hasPhpCode) {
      return;
    }

    // Process HTML content directly
    const { document } = positionMapperRef.current.parseHtml(content);
    const htmlWithIds = positionMapperRef.current.serializeWithIds(document);

    messageBus.send({
      type: 'UPDATE_CONTENT',
      payload: {
        content: htmlWithIds,
      },
    } as any);
  }, [isIframeReady, messageBus, hasPhpCode, content]);

  // Handle element click
  const handleElementClick = useCallback(
    (elementId: string, phpBlockIds: string[] = []) => {
      const mapping = hasPhpCode
        ? phpElementMapRef.current.get(elementId)
        : positionMapperRef.current.getElementMapping(elementId);
      if (!mapping) {
        return;
      }

      let start = mapping.position.start.offset;
      let end = mapping.position.end.offset;

      if (hasPhpCode && safeToRawMapperRef.current) {
        // Map safe positions to raw positions
        const { rawStart, rawEnd } = safeToRawMapperRef.current.mapRange(
          start,
          end
        );
        start = rawStart;
        end = rawEnd;

        // Include any additional PHP blocks
        for (const id of phpBlockIds) {
          const m = phpElementMapRef.current.get(id);
          if (m && safeToRawMapperRef.current) {
            const mapped = safeToRawMapperRef.current.mapRange(
              m.position.start.offset,
              m.position.end.offset
            );
            start = Math.min(start, mapped.rawStart);
            end = Math.max(end, mapped.rawEnd);
          }
        }
      }

      setSelectedElement({
        id: elementId,
        tagName: mapping.tagName,
        start,
        end,
      });
    },
    [setSelectedElement, hasPhpCode]
  );

  // Initialize message handling
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.source !== iframeRef.current?.contentWindow) {
        return;
      }

      if (event.data.type === 'IFRAME_READY') {
        setIsIframeReady(true);
        if (iframeRef.current?.contentWindow) {
          messageBus.setTarget(iframeRef.current.contentWindow);
        }
      } else if (event.data.type === 'ELEMENT_CLICKED' && isSelecting) {
        handleElementClick(
          event.data.payload.elementId,
          event.data.payload.phpBlockIds || []
        );
      }
    };

    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [isSelecting, handleElementClick, messageBus]);

  // Update content when ready or content changes
  useEffect(() => {
    if (hasPhpCode) {
      // For PHP content, use debounced execution
      debouncedPhpExecute(content);
    } else {
      // For non-PHP content, update immediately
      updateContent();
    }
  }, [content, hasPhpCode, debouncedPhpExecute, updateContent]);

  // When executed output is available, extract dynamic segments and inject
  // them into the preview placeholders so backend can "see" rendered PHP DOM
  useEffect(() => {
    if (phpOutput !== null && isIframeReady) {
      const blocksMap = extractDynamicBlocks(phpOutput);
      if (blocksMap.size > 0) {
        const blocks = Array.from(blocksMap.entries()).map(([id, html]) => ({
          id,
          html,
        }));
        messageBus.send({
          type: 'UPDATE_DYNAMIC_BLOCKS',
          payload: { blocks },
        } as any);
      }
    }
  }, [phpOutput, isIframeReady, messageBus]);

  // Cleanup debounced function on unmount
  useEffect(() => {
    return () => {
      debouncedPhpExecute.cancel();
    };
  }, [debouncedPhpExecute]);

  // Update selection mode
  useEffect(() => {
    if (!isIframeReady) {
      return;
    }

    messageBus.send({
      type: 'SET_SELECTION_MODE',
      payload: {
        enabled: isSelecting,
      },
    } as any);
  }, [isSelecting, isIframeReady, messageBus]);

  // Initialize preview modules
  const { generatePreviewContent } = usePreviewModules();

  // Generate iframe content - only once
  const iframeContent = useMemo(() => {
    // 使用提取好的配置，如果没有则使用空值
    const tailwindConfig = extractedTailwindConfig || '';
    const parsedDesignSystem = parseDesignSystem(designSystemHtml || '');
    const customStyles = [fontCss, parsedDesignSystem.customCSS].filter(
      (style): style is string => Boolean(style?.trim())
    );

    const previewHtml = generatePreviewContent({
      tailwindConfig,
      customStyles,
    });

    // Return empty string if null
    return previewHtml || '';
  }, [
    designSystemHtml,
    extractedTailwindConfig,
    fontCss,
    generatePreviewContent,
  ]);

  const deviceWidthClass = useMemo(
    () => (previewDevice === 'desktop' ? 'w-full' : 'w-[375px] max-w-full'),
    [previewDevice]
  );

  return (
    <div className="relative flex h-full w-full flex-col">
      {/* PHP Error Display */}
      {phpError && (
        <div className="border-red-200 border-b bg-red-50 p-3 text-red-700">
          <div className="mb-1 font-semibold text-sm">PHP Error:</div>
          <pre className="whitespace-pre-wrap text-xs">{phpError}</pre>
        </div>
      )}

      {/* PHP Mode Indicator */}
      {hasPhpCode && (
        <div className="flex items-center justify-between border-blue-200 border-b bg-blue-50 px-3 py-1 text-blue-700 text-xs">
          <span>PHP Mode Active</span>
          {phpExecuteMutation.isPending && <span>Executing...</span>}
        </div>
      )}

      {/* Preview iframe */}
      <div
        className={`relative flex-1 ${
          previewDevice === 'mobile'
            ? 'flex items-center justify-center bg-gray-100 px-4'
            : ''
        }`}
      >
        <div
          className={`relative h-full ${
            previewDevice === 'mobile'
              ? `transition-all duration-300 ease-in-out ${deviceWidthClass}`
              : 'w-full'
          }`}
          ref={previewContainerRef}
        >
          {!isIframeReady && <LoadingSpinner />}
          <iframe
            className={`h-full w-full border-0 ${
              isIframeReady ? 'opacity-100' : 'opacity-0'
            } transition-opacity duration-300 ${
              previewDevice === 'mobile' ? 'rounded-lg shadow-2xl' : ''
            }`}
            ref={iframeRef}
            sandbox="allow-scripts allow-forms allow-same-origin"
            srcDoc={iframeContent}
            title="Preview"
          />
          {/* PHP Block Overlays */}
          {hasPhpCode && isIframeReady && OverlayComponent}
        </div>
      </div>
    </div>
  );
}
