import type React from 'react';

interface WelcomeGuideProps {
  hasSelectedText?: boolean;
  templateType?: string;
  onExampleClick?: (example: string) => void;
}

export const WelcomeGuide: React.FC<WelcomeGuideProps> = ({
  hasSelectedText = false,
  templateType = '',
  onExampleClick,
}) => {
  // 根据模板类型选择不同的示例
  const getExamplesByTemplateType = () => {
    switch (templateType) {
      case 'single':
        return [
          '生成一个响应式的文章布局，包含标题、封面和内容',
          '添加文章的分类和标签列表',
          '添加一个作者的信息卡片，显示名称',
        ];
      case 'archive':
        return [
          '创建一个文章列表，展示最近 3 篇文章',
          '生成一个网格布局的博客归档页面',
          '添加分页组件，每页显示10篇文章',
        ];
      default:
        return [
          '创建一个符合设计规范的 about 页面',
          '生成一个带搜索功能的页眉',
          '让我点这个按钮可以展示一个弹窗',
        ];
    }
  };

  const examples = getExamplesByTemplateType();

  return (
    <div className="flex h-full items-center justify-center p-8">
      <div className="max-w-2xl space-y-6 text-center">
        {/* 欢迎标题 */}
        <div className="space-y-2">
          <h3 className="font-semibold text-2xl text-gray-900">
            🤖 AI 代码生成助手
          </h3>
          <p className="text-gray-600">我可以帮你生成、修改和优化 HTML 代码</p>
        </div>

        {/* 选中文本提示 */}
        {hasSelectedText && (
          <div className="rounded-lg bg-blue-50 p-4">
            <p className="text-blue-800 text-sm">
              💡 你已选中了代码片段，AI 将基于选中内容进行修改或替换
            </p>
          </div>
        )}

        {/* 示例提示 */}
        <div className="space-y-3">
          <h4 className="font-medium text-gray-700">试试这些示例：</h4>
          <div className="space-y-2">
            {examples.map((example) => (
              <button
                className="group relative w-full rounded-lg border border-gray-200 bg-gray-50 p-3 text-left transition-colors hover:border-blue-300 hover:bg-blue-50"
                key={example}
                onClick={() => onExampleClick?.(example)}
                type="button"
              >
                <p className="pr-8 text-gray-700 text-sm">{example}</p>
                <span className="absolute top-3 right-3 text-gray-400 text-xs opacity-0 transition-opacity group-hover:opacity-100">
                  点击使用
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* 快捷提示 */}
        <div className="rounded-lg bg-gray-100 p-4">
          <p className="text-gray-600 text-sm">
            <span className="font-medium">提示：</span>
            描述得越详细，生成的代码越符合你的需求
          </p>
        </div>
      </div>
    </div>
  );
};
