import { create } from 'zustand';

export interface AIHistoryEntry {
  id: string;
  prompt: string;
  code?: string;
  createdAt: number;
}

interface AIHistoryState {
  entries: AIHistoryEntry[];
  currentPostId: number | null;
  addEntry: (data: { prompt: string; code?: string }) => void;
  removeEntry: (id: string) => void;
  clearEntries: () => void;
  loadFromStorage: (postId: number) => void;
}

const MAX_ENTRIES = 20;

// 简单 hash 函数，用于站点隔离
function simpleHash(str: string): string {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash * 31 + str.charCodeAt(i)) % 1_000_000_007;
  }
  return Math.abs(hash).toString(36).slice(0, 6);
}

// 获取存储 key
function getStorageKey(postId: number): string {
  const siteUrl = window.zeroyEditor?.homeUrl || window.location.origin;
  const siteHash = simpleHash(siteUrl);
  return `zeroy_prompts_${siteHash}_${postId}`;
}

// 从 localStorage 读取
function readFromStorage(postId: number): AIHistoryEntry[] {
  try {
    const key = getStorageKey(postId);
    const data = localStorage.getItem(key);
    if (!data) {
      return [];
    }
    const parsed = JSON.parse(data);
    return Array.isArray(parsed.entries) ? parsed.entries : [];
  } catch {
    return [];
  }
}

// 写入 localStorage
function writeToStorage(postId: number, entries: AIHistoryEntry[]): void {
  try {
    const key = getStorageKey(postId);
    localStorage.setItem(key, JSON.stringify({ entries, version: 1 }));
  } catch {
    // localStorage 可能满了或被禁用，忽略错误
  }
}

export const useAIHistoryStore = create<AIHistoryState>()((set, get) => ({
  entries: [],
  currentPostId: null,

  loadFromStorage: (postId: number) => {
    const entries = readFromStorage(postId);
    set({ entries, currentPostId: postId });
  },

  addEntry: ({ prompt, code }) => {
    const { currentPostId } = get();
    if (!currentPostId) {
      return;
    }

    const newEntry: AIHistoryEntry = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      prompt,
      code,
      createdAt: Date.now(),
    };

    // 去重：过滤掉相同 prompt 的旧记录
    const current = get().entries;
    const filtered = current.filter((e) => e.prompt !== prompt);
    const next = [newEntry, ...filtered].slice(0, MAX_ENTRIES);

    set({ entries: next });
    writeToStorage(currentPostId, next);
  },

  removeEntry: (id: string) => {
    const { currentPostId, entries } = get();
    const next = entries.filter((e) => e.id !== id);
    set({ entries: next });
    if (currentPostId) {
      writeToStorage(currentPostId, next);
    }
  },

  clearEntries: () => {
    const { currentPostId } = get();
    set({ entries: [] });
    if (currentPostId) {
      writeToStorage(currentPostId, []);
    }
  },
}));
