/**
 * 后台图片优化引擎
 *
 * 核心理念：
 * - 用户上传时只上传原图（0.5-1秒，完全无感）
 * - 用户在 zeroy 编辑器时，后台自动扫描媒体库
 * - 自动处理所有缺失的格式：原格式压缩、WebP
 * - 利用浏览器空闲时间，不影响用户正常使用
 * - 支持历史图片优化（非 zeroy 上传的也能处理）
 *
 * 设计特点：
 * - 完全静默（只在 debug 模式显示日志）
 * - 智能优先级（最近上传的优先）
 * - 防重复（后端加锁机制）
 * - 自动恢复（处理失败自动重试）
 */

import { apiClient } from '@/api/client';
import { cleanupWorkerPool, getWorkerPool } from './image-processor';
import type { ImageWorkerPool } from './worker-pool';

/**
 * Debug 日志（只在开启 debug 模式时显示）
 */
function debugLog(...args: unknown[]) {
  // 检查是否开启 debug 模式
  const debugLevel = localStorage.getItem('zeroy_debug');

  if (debugLevel !== '1') {
    return;
  }

  console.log('[优化引擎]', ...args);
}

/**
 * [v1.1.29] 检测浏览器是否支持 WebAssembly
 *
 * 使用最小 WASM 模块测试（8 字节的空模块）
 *
 * @returns {boolean} 是否支持 WASM
 */
function isWebAssemblySupported(): boolean {
  try {
    if (
      typeof WebAssembly === 'object' &&
      typeof WebAssembly.instantiate === 'function'
    ) {
      // 最小 WASM 模块：magic number + version
      const module = new WebAssembly.Module(
        Uint8Array.of(0x0, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00)
      );

      if (module instanceof WebAssembly.Module) {
        return true;
      }
    }
  } catch (e) {
    console.error('[优化引擎] WASM check failed:', e);
  }

  return false;
}

/**
 * 正则表达式常量（顶层作用域，避免重复创建）
 */
const IMAGE_EXT_REGEX = /\.(jpe?g|png)$/i;

/**
 * Leader Election - 确保只有一个 Tab 运行优化引擎
 *
 * 机制：
 * 1. 使用 localStorage 存储 leader 心跳时间戳
 * 2. 第一个打开的 Tab 成为 leader
 * 3. Leader 每 5 秒发送心跳
 * 4. Follower 检测 10 秒无心跳后接管
 * 5. Leader 关闭时自动清理，follower 立即接管
 */
class LeaderElection {
  private static readonly HEARTBEAT_KEY = 'zeroy_optimization_leader_heartbeat';
  private static readonly HEARTBEAT_INTERVAL = 5000; // 5 秒
  private static readonly HEARTBEAT_TIMEOUT = 10_000; // 10 秒
  private static readonly CHANNEL_NAME = 'zeroy_optimization_leader';

  private isLeader = false;
  private heartbeatInterval: number | null = null;
  private checkInterval: number | null = null;
  private channel: BroadcastChannel | null = null;
  private sessionId: string;

  constructor() {
    // 生成唯一的 session ID
    this.sessionId = `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

    // 初始化 BroadcastChannel（用于跨 Tab 通信）
    if ('BroadcastChannel' in window) {
      this.channel = new BroadcastChannel(LeaderElection.CHANNEL_NAME);
      this.channel.onmessage = (e) => this.handleChannelMessage(e);
    }

    // 尝试成为 leader
    this.tryBecomeLeader();

    // 定期检查 leader 状态
    this.checkInterval = window.setInterval(() => {
      this.checkLeaderStatus();
    }, LeaderElection.HEARTBEAT_INTERVAL);

    // 页面关闭时清理
    window.addEventListener('beforeunload', () => this.cleanup());
  }

  /**
   * 尝试成为 leader
   */
  private tryBecomeLeader() {
    const lastHeartbeat = localStorage.getItem(LeaderElection.HEARTBEAT_KEY);
    const now = Date.now();

    // 如果没有 leader 或 leader 已超时（10 秒无心跳）
    if (
      !lastHeartbeat ||
      now - Number.parseInt(lastHeartbeat, 10) >
        LeaderElection.HEARTBEAT_TIMEOUT
    ) {
      this.becomeLeader();
    } else {
      debugLog('⏭️ 已有 Leader 存在，当前为 Follower 模式');
    }
  }

  /**
   * 成为 leader
   */
  private becomeLeader() {
    this.isLeader = true;
    this.updateHeartbeat();
    debugLog(`🎖️ 成为优化引擎 Leader (${this.sessionId})`);

    // 广播 leader 声明
    this.channel?.postMessage({
      type: 'leader_claim',
      sessionId: this.sessionId,
    });

    // 启动心跳
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
    }
    this.heartbeatInterval = window.setInterval(() => {
      this.updateHeartbeat();
    }, LeaderElection.HEARTBEAT_INTERVAL);
  }

  /**
   * 更新心跳时间戳
   */
  private updateHeartbeat() {
    if (this.isLeader) {
      localStorage.setItem(LeaderElection.HEARTBEAT_KEY, Date.now().toString());

      // 广播心跳
      this.channel?.postMessage({
        type: 'leader_alive',
        sessionId: this.sessionId,
      });
    }
  }

  /**
   * 处理跨 Tab 消息
   */
  private handleChannelMessage(e: MessageEvent) {
    const { type, sessionId } = e.data;

    // 如果其他 Tab 声明为 leader，且不是自己
    if (type === 'leader_claim' && sessionId !== this.sessionId) {
      debugLog('⚠️ 检测到其他 Tab 成为 Leader，降级为 Follower');
      this.stepDown();
    }

    // 如果收到心跳，且不是自己，且自己也是 leader（冲突），降级
    if (
      type === 'leader_alive' &&
      sessionId !== this.sessionId &&
      this.isLeader
    ) {
      debugLog('⚠️ 检测到 Leader 冲突，降级为 Follower');
      this.stepDown();
    }
  }

  /**
   * 降级为 follower
   */
  private stepDown() {
    this.isLeader = false;

    // 停止心跳
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  /**
   * 定期检查 leader 状态
   */
  private checkLeaderStatus() {
    const lastHeartbeat = localStorage.getItem(LeaderElection.HEARTBEAT_KEY);
    const now = Date.now();

    if (this.isLeader) {
      // Leader 继续发送心跳（已在 becomeLeader 中启动）
      return;
    }

    // Follower 检查是否需要接管
    if (
      !lastHeartbeat ||
      now - Number.parseInt(lastHeartbeat, 10) >
        LeaderElection.HEARTBEAT_TIMEOUT
    ) {
      debugLog('⚠️ 检测到 Leader 失联，尝试接管');
      this.tryBecomeLeader();
    }
  }

  /**
   * 清理资源
   */
  private cleanup() {
    if (this.isLeader) {
      debugLog('🛑 Leader 关闭，清理资源');
      localStorage.removeItem(LeaderElection.HEARTBEAT_KEY);
    }

    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
    }

    if (this.checkInterval) {
      clearInterval(this.checkInterval);
    }

    this.channel?.close();
  }

  /**
   * 获取是否为 leader
   */
  getIsLeader(): boolean {
    return this.isLeader;
  }

  /**
   * 销毁（外部调用）
   */
  destroy() {
    this.cleanup();
  }
}

/**
 * 待优化的图片信息
 */
interface PendingImage {
  id: number;
  url: string;
  title: string; // 图片标题
  sourceFormat: 'jpeg' | 'png' | 'webp';
  sizes: Array<{
    width: number;
    height: number;
    file?: string; // WordPress 已生成的文件名
  }>;
  needsCompression: boolean; // 需要原格式压缩
  needsWebP: boolean; // 需要 WebP
  uploadedAt: string; // 上传时间（用于优先级排序）
}

/**
 * 后台图片优化引擎（单例）
 */
export class ImageOptimizationEngine {
  private static instance: ImageOptimizationEngine | null = null;
  private isRunning = false;
  private isPaused = false;
  private processingImageId: number | null = null;
  private leaderElection: LeaderElection | null = null;
  private isGlobalLeader = false;
  private globalLeaderCheckInterval: number | null = null;
  private standbyRetryInterval: number | null = null; // 待命模式重试定时器
  private sessionId: string;

  // 智能检查频率
  private idleScanInterval = 5000; // 初始 5 秒
  private consecutiveEmptyScans = 0; // 连续空扫描次数
  private wakeUpSignal = false; // 唤醒信号（用于中断 sleep）

  private constructor() {
    // 生成唯一的 session ID
    this.sessionId = `session-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    debugLog(`🎬 引擎实例已创建 (${this.sessionId})`);
  }

  /**
   * 获取单例实例
   */
  static getInstance(): ImageOptimizationEngine {
    if (!ImageOptimizationEngine.instance) {
      ImageOptimizationEngine.instance = new ImageOptimizationEngine();
    }
    return ImageOptimizationEngine.instance;
  }

  /**
   * 启动后台引擎（用户进入编辑器时调用）
   */
  async start() {
    console.log('[优化引擎] 尝试启动...');

    // [v1.1.29] 检查 WebAssembly 支持
    if (!isWebAssemblySupported()) {
      console.warn(
        '[优化引擎] WebAssembly not supported, image optimization disabled'
      );
      return;
    }

    if (this.isRunning) {
      console.log('[优化引擎] 已在运行中，跳过');
      return;
    }

    // 1. 前端 Leader Election（同浏览器多 Tab 协调）
    if (!this.leaderElection) {
      this.leaderElection = new LeaderElection();
    }

    if (!this.leaderElection.getIsLeader()) {
      console.log('[优化引擎] 其他标签页正在运行，当前为 Follower 模式');
      return;
    }

    console.log('[优化引擎] 前端 Leader 选举成功，尝试获取全局锁...');

    // 2. 尝试成为全局 Leader（跨浏览器/用户/设备协调）
    const becameGlobalLeader = await this.tryBecomeGlobalLeader();
    if (!becameGlobalLeader) {
      console.log('[优化引擎] 全局锁被占用，进入待命模式，每 10 秒重试...');
      this.startStandbyMode();
      return;
    }

    this.isGlobalLeader = true;

    // 3. 定期刷新全局 Leader 心跳（每 10 秒）
    this.globalLeaderCheckInterval = window.setInterval(() => {
      this.refreshGlobalLeadership();
    }, 10_000);

    this.isRunning = true;
    this.isPaused = false;
    console.log('[优化引擎] 🚀 成功启动，开始扫描媒体库...');
    debugLog('🚀 全局 Leader 启动后台优化引擎');

    // 4. 开始扫描和处理循环（异步运行，不阻塞）
    this.runOptimizationLoop();
  }

  /**
   * 暂停引擎（用户离开编辑器时调用）
   */
  pause() {
    if (!(this.isRunning || this.standbyRetryInterval)) {
      return;
    }

    debugLog('⏸️ 暂停后台优化引擎');
    this.isPaused = true;
    this.isRunning = false;
    this.isGlobalLeader = false;

    // 清理全局 Leader 心跳定时器
    if (this.globalLeaderCheckInterval) {
      clearInterval(this.globalLeaderCheckInterval);
      this.globalLeaderCheckInterval = null;
    }

    // 清理待命模式重试定时器
    if (this.standbyRetryInterval) {
      clearInterval(this.standbyRetryInterval);
      this.standbyRetryInterval = null;
      console.log('[优化引擎] 退出待命模式');
    }

    // 清理 Worker 池
    cleanupWorkerPool();

    // 清理 Leader Election
    if (this.leaderElection) {
      this.leaderElection.destroy();
      this.leaderElection = null;
    }
  }

  /**
   * 启动待命模式（全局锁被占用时定期重试）
   */
  private startStandbyMode() {
    // 避免重复启动待命模式
    if (this.standbyRetryInterval) {
      return;
    }

    this.standbyRetryInterval = window.setInterval(async () => {
      console.log('[优化引擎] 待命模式：重试获取全局锁...');

      const becameGlobalLeader = await this.tryBecomeGlobalLeader();
      if (becameGlobalLeader) {
        // 成功接管！
        console.log('[优化引擎] 🎉 成功接管全局锁，启动引擎...');

        // 清理待命定时器
        if (this.standbyRetryInterval) {
          clearInterval(this.standbyRetryInterval);
          this.standbyRetryInterval = null;
        }

        // 启动引擎
        this.isGlobalLeader = true;

        // 定期刷新全局 Leader 心跳（每 10 秒）
        this.globalLeaderCheckInterval = window.setInterval(() => {
          this.refreshGlobalLeadership();
        }, 10_000);

        this.isRunning = true;
        this.isPaused = false;
        console.log('[优化引擎] 🚀 成功启动，开始扫描媒体库...');
        debugLog('🚀 全局 Leader 启动后台优化引擎');

        // 开始扫描和处理循环
        this.runOptimizationLoop();
      }
    }, 10_000); // 每 10 秒重试一次
  }

  /**
   * 主优化循环
   */
  private async runOptimizationLoop() {
    while (this.isRunning && !this.isPaused) {
      try {
        if (!this.checkLeadershipAndContinue()) {
          break;
        }

        const pendingImages = await this.fetchPendingImages();

        if (pendingImages.length === 0) {
          await this.handleNoPendingImages();
          continue;
        }

        debugLog(`📋 发现 ${pendingImages.length} 张图片待优化`);
        await this.processImageBatch(pendingImages);
      } catch (error) {
        debugLog('❌ 优化循环出错:', error);
        await this.sleep(10_000);
      }
    }

    debugLog('🏁 优化循环已退出');
  }

  /**
   * 检查 leadership 并决定是否继续
   */
  private checkLeadershipAndContinue(): boolean {
    if (!this.leaderElection?.getIsLeader()) {
      debugLog('⚠️ 失去 Leader 身份，停止优化引擎');
      this.pause();
      return false;
    }
    return true;
  }

  /**
   * 处理没有待优化图片的情况
   * 智能间隔：连续空扫描时逐渐增加间隔，节省资源
   */
  private async handleNoPendingImages() {
    this.consecutiveEmptyScans++;

    // 智能间隔调整：5秒 → 10秒 → 30秒
    if (this.consecutiveEmptyScans === 1) {
      this.idleScanInterval = 5000;
    } else if (this.consecutiveEmptyScans === 2) {
      this.idleScanInterval = 10_000;
    } else {
      this.idleScanInterval = 30_000;
    }

    debugLog(
      `✅ 媒体库已全部优化，等待 ${this.idleScanInterval / 1000} 秒后重新检查`
    );
    await this.interruptibleSleep(this.idleScanInterval);
  }

  /**
   * 可中断的 sleep（通过 wakeUpSignal 提前唤醒）
   */
  private async interruptibleSleep(ms: number) {
    const startTime = Date.now();
    const checkInterval = 100; // 每 100ms 检查一次唤醒信号

    while (Date.now() - startTime < ms) {
      // 检查唤醒信号
      if (this.wakeUpSignal) {
        this.wakeUpSignal = false;
        debugLog('⏰ 收到唤醒信号，提前结束等待');
        return;
      }

      // 等待 100ms 或剩余时间（取较小值）
      const remaining = ms - (Date.now() - startTime);
      const sleepTime = Math.min(checkInterval, remaining);
      await this.sleep(sleepTime);
    }
  }

  /**
   * 处理一批图片
   */
  private async processImageBatch(images: PendingImage[]) {
    // 发现待处理图片，重置空扫描计数器（恢复勤快模式）
    this.consecutiveEmptyScans = 0;
    this.idleScanInterval = 5000;

    for (const image of images) {
      if (!this.shouldContinueProcessing()) {
        break;
      }

      await this.optimizeImage(image);
      await this.sleep(1000); // 避免连续处理
    }
  }

  /**
   * 检查是否应该继续处理
   */
  private shouldContinueProcessing(): boolean {
    if (!this.isRunning || this.isPaused) {
      debugLog('🛑 引擎已停止');
      return false;
    }

    if (!this.leaderElection?.getIsLeader()) {
      debugLog('⚠️ 处理过程中失去 Leader 身份，停止');
      this.pause();
      return false;
    }

    return true;
  }

  /**
   * 从后端获取待优化的图片列表
   */
  private async fetchPendingImages(): Promise<PendingImage[]> {
    try {
      const response = (await apiClient.get('/media/pending-optimization', {
        limit: 10, // 每次最多处理 10 张
      })) as PendingImage[];

      return Array.isArray(response) ? response : [];
    } catch (error) {
      debugLog('❌ 获取待优化列表失败:', error);
      return [];
    }
  }

  /**
   * 优化单张图片
   */
  private async optimizeImage(image: PendingImage) {
    const { id, url, title, needsCompression, needsWebP } = image;

    debugLog(
      `🎨 开始优化图片 #${id} "${title}": 压缩=${needsCompression}, WebP=${needsWebP}`
    );

    this.processingImageId = id;

    // 1. 尝试加锁（防止多开页面重复处理）
    const locked = await this.acquireLock(id);
    if (!locked) {
      debugLog(`⏭️ 图片 #${id} 正在其他地方处理，跳过`);
      this.processingImageId = null;
      return;
    }

    try {
      // 2. 下载原图
      const imageFile = await this.downloadImage(url, image.sourceFormat);

      // 3. 按顺序处理（WebP -> 原格式压缩）
      // 先转 WebP（从原图转换），最后再压缩原格式
      if (needsWebP) {
        await this.processWebP(id, imageFile, image.sizes);
      }

      if (needsCompression) {
        await this.processCompression(id, imageFile, image.sizes);
      }

      debugLog(`✅ 图片 #${id} 优化完成`);
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : '未知错误';
      debugLog(`❌ 图片 #${id} 处理失败:`, errorMsg);
      await this.markAsFailed(id, errorMsg);
    } finally {
      await this.releaseLock(id);
      this.processingImageId = null;
    }
  }

  /**
   * 处理原格式压缩（使用 jsquash）
   */
  private async processCompression(
    attachmentId: number,
    file: File,
    sizes: PendingImage['sizes']
  ) {
    debugLog(`🗜️ 开始原格式压缩: ${sizes.length} 个尺寸`);
    const startTime = performance.now();

    // 浏览器能力检测（带降级）
    let pool: ImageWorkerPool;
    try {
      pool = getWorkerPool();
    } catch (_error) {
      debugLog('⚠️ 浏览器不支持客户端优化，跳过原格式压缩');
      return;
    }

    const sourceFormat = this.getSourceFormat(file.type);

    if (sourceFormat !== 'jpeg' && sourceFormat !== 'png') {
      debugLog('⏭️ 跳过不支持的格式:', file.type);
      return;
    }

    const results: Array<{
      width: number;
      height: number;
      data: Uint8Array;
      filename: string;
    }> = [];

    for (const size of sizes) {
      // 等待浏览器空闲
      await this.waitForIdle();

      if (!this.isRunning) {
        break;
      }

      // 调整图片尺寸
      const imageData = await this.resizeImage(file, size.width, size.height);

      // 提交到 Worker 池压缩
      const result = await pool.runTask({
        type: 'compress',
        imageData,
        sourceFormat,
        quality: 85,
        filename: size.file || `image-${size.width}x${size.height}.jpg`,
        sizeLabel: `${size.width}x${size.height}`,
        priority: 3, // 低优先级
      });

      if (result.success && result.data && result.filename) {
        results.push({
          width: size.width,
          height: size.height,
          data: result.data,
          filename: result.filename,
        });
      }
    }

    // 上传到后端
    if (results.length > 0) {
      await this.uploadCompressedFiles(attachmentId, sourceFormat, results);
    }

    const elapsed = performance.now() - startTime;
    debugLog(`✅ 原格式压缩完成，耗时: ${elapsed.toFixed(0)}ms`);
  }

  /**
   * 处理 WebP 转换
   */
  private async processWebP(
    attachmentId: number,
    file: File,
    sizes: PendingImage['sizes']
  ) {
    debugLog(`🎨 开始 WebP 转换: ${sizes.length} 个尺寸`);
    const startTime = performance.now();

    // 浏览器能力检测（带降级）
    let pool: ImageWorkerPool;
    try {
      pool = getWorkerPool();
    } catch (_error) {
      debugLog('⚠️ 浏览器不支持客户端优化，跳过 WebP 转换');
      return;
    }

    const results: Array<{
      width: number;
      height: number;
      data: Uint8Array;
      filename: string;
    }> = [];

    for (const size of sizes) {
      // 等待浏览器空闲
      await this.waitForIdle();

      if (!this.isRunning) {
        break;
      }

      const imageData = await this.resizeImage(file, size.width, size.height);

      const result = await pool.runTask({
        type: 'convert-webp',
        imageData,
        quality: 85,
        filename:
          size.file?.replace(IMAGE_EXT_REGEX, '.webp') ||
          `image-${size.width}x${size.height}.webp`,
        sizeLabel: `${size.width}x${size.height}`,
        priority: 2, // 中优先级
      });

      if (result.success && result.data && result.filename) {
        results.push({
          width: size.width,
          height: size.height,
          data: result.data,
          filename: result.filename,
        });
      }
    }

    // 上传到后端
    if (results.length > 0) {
      await this.uploadWebPFiles(attachmentId, results);
    }

    const elapsed = performance.now() - startTime;
    debugLog(`✅ WebP 转换完成，耗时: ${elapsed.toFixed(0)}ms`);
  }

  /**
   * 下载原图
   */
  private async downloadImage(url: string, format: string): Promise<File> {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`下载图片失败: ${response.statusText}`);
    }

    const blob = await response.blob();
    const mimeType = this.getMimeType(format);
    return new File([blob], `image.${format}`, { type: mimeType });
  }

  /**
   * 调整图片尺寸
   */
  private resizeImage(
    file: File,
    targetWidth: number,
    targetHeight: number
  ): Promise<ImageData> {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const objectUrl = URL.createObjectURL(file);

      img.onload = () => {
        URL.revokeObjectURL(objectUrl);

        const canvas = document.createElement('canvas');
        canvas.width = targetWidth;
        canvas.height = targetHeight;

        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error('无法获取 canvas context'));
          return;
        }

        ctx.drawImage(img, 0, 0, targetWidth, targetHeight);
        const imageData = ctx.getImageData(0, 0, targetWidth, targetHeight);
        resolve(imageData);
      };

      img.onerror = () => {
        URL.revokeObjectURL(objectUrl);
        reject(new Error('图片加载失败'));
      };

      img.src = objectUrl;
    });
  }

  /**
   * 上传压缩后的原格式文件
   */
  private async uploadCompressedFiles(
    attachmentId: number,
    sourceFormat: string,
    results: Array<{
      width: number;
      height: number;
      data: Uint8Array;
      filename: string;
    }>
  ) {
    const formData = new FormData();
    formData.append('attachment_id', attachmentId.toString());

    for (const result of results) {
      const buffer = result.data.buffer as ArrayBuffer;
      const blob = new Blob([buffer], {
        type: this.getMimeType(sourceFormat),
      });
      const file = new File([blob], result.filename, {
        type: this.getMimeType(sourceFormat),
      });
      formData.append('compressed_files[]', file);
    }

    const ajaxUrl = '/wp-admin/admin-ajax.php';
    const uploadUrl = `${ajaxUrl}?action=zeroy_save_optimized&source_format=${sourceFormat}`;

    const response = await fetch(uploadUrl, {
      method: 'POST',
      credentials: 'same-origin',
      body: formData,
    });

    if (!response.ok) {
      throw new Error('上传压缩文件失败');
    }

    const result = await response.json();
    if (!result.success) {
      throw new Error(result.message || '保存压缩文件失败');
    }
  }

  /**
   * 上传 WebP 文件
   */
  private async uploadWebPFiles(
    attachmentId: number,
    results: Array<{
      width: number;
      height: number;
      data: Uint8Array;
      filename: string;
    }>
  ) {
    const formData = new FormData();
    formData.append('attachment_id', attachmentId.toString());

    for (const result of results) {
      const buffer = result.data.buffer as ArrayBuffer;
      const blob = new Blob([buffer], { type: 'image/webp' });
      const file = new File([blob], result.filename, { type: 'image/webp' });
      formData.append('webp_files[]', file);
    }

    const ajaxUrl = '/wp-admin/admin-ajax.php';
    const uploadUrl = `${ajaxUrl}?action=zeroy_save_optimized&source_format=webp`;

    const response = await fetch(uploadUrl, {
      method: 'POST',
      credentials: 'same-origin',
      body: formData,
    });

    if (!response.ok) {
      throw new Error('上传 WebP 文件失败');
    }

    const result = await response.json();
    if (!result.success) {
      throw new Error(result.message || '保存 WebP 文件失败');
    }
  }

  /**
   * 获取锁（防止重复处理）
   */
  private async acquireLock(attachmentId: number): Promise<boolean> {
    try {
      const response = (await apiClient.post(
        `/media/${attachmentId}/acquire-lock`,
        {
          session_id: this.sessionId,
        }
      )) as { success: boolean };
      return response.success === true;
    } catch {
      return false;
    }
  }

  /**
   * 释放锁
   */
  private async releaseLock(attachmentId: number) {
    try {
      await apiClient.post(`/media/${attachmentId}/release-lock`, {});
    } catch (error) {
      debugLog('⚠️ 释放锁失败:', error);
    }
  }

  /**
   * 标记为失败
   */
  private async markAsFailed(attachmentId: number, error: string) {
    try {
      await apiClient.post(`/media/${attachmentId}/mark-failed`, { error });
    } catch (err) {
      debugLog('⚠️ 标记失败状态失败:', err);
    }
  }

  /**
   * 尝试成为全局 Leader（跨浏览器/用户/设备）
   */
  private async tryBecomeGlobalLeader(): Promise<boolean> {
    try {
      const response = (await apiClient.post(
        '/optimization/try-become-leader',
        {
          session_id: this.sessionId,
        }
      )) as { is_leader: boolean; message?: string };

      if (response.is_leader) {
        debugLog(`🎖️ 成为全局 Leader (${this.sessionId})`);
      }

      return response.is_leader === true;
    } catch (error) {
      debugLog('❌ 全局 Leader 请求失败:', error);
      return false;
    }
  }

  /**
   * 刷新全局 Leader 心跳
   */
  private async refreshGlobalLeadership() {
    const stillLeader = await this.tryBecomeGlobalLeader();

    if (!stillLeader && this.isGlobalLeader) {
      debugLog('⚠️ 失去全局 Leader 身份，停止优化');
      this.isGlobalLeader = false;
      this.pause();
    }
  }

  /**
   * 等待浏览器空闲
   */
  private waitForIdle(timeout = 1000): Promise<void> {
    return new Promise((resolve) => {
      if ('requestIdleCallback' in window) {
        requestIdleCallback(() => resolve(), { timeout });
      } else {
        setTimeout(resolve, 100);
      }
    });
  }

  /**
   * 睡眠
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * 获取源格式
   */
  private getSourceFormat(mimeType: string): 'jpeg' | 'png' | 'webp' {
    if (mimeType.includes('jpeg') || mimeType.includes('jpg')) {
      return 'jpeg';
    }
    if (mimeType.includes('png')) {
      return 'png';
    }
    if (mimeType.includes('webp')) {
      return 'webp';
    }
    return 'jpeg';
  }

  /**
   * 获取 MIME 类型
   */
  private getMimeType(format: string): string {
    const mimeTypes: Record<string, string> = {
      jpeg: 'image/jpeg',
      jpg: 'image/jpeg',
      png: 'image/png',
      webp: 'image/webp',
    };
    return mimeTypes[format.toLowerCase()] || 'image/jpeg';
  }

  /**
   * 通知引擎有新图片上传（立即触发扫描）
   */
  notifyNewImage() {
    if (this.isRunning && this.isGlobalLeader) {
      debugLog('📢 收到新图片通知，唤醒引擎');
      // 重置空扫描计数器，立即进入勤快模式
      this.consecutiveEmptyScans = 0;
      this.idleScanInterval = 5000;
      // 设置唤醒信号，中断当前 sleep
      this.wakeUpSignal = true;
    }
  }

  /**
   * 获取当前状态（用于调试）
   */
  getStatus() {
    return {
      isRunning: this.isRunning,
      isPaused: this.isPaused,
      processingImageId: this.processingImageId,
    };
  }
}

/**
 * 导出便捷函数
 */
export function startOptimizationEngine() {
  const engine = ImageOptimizationEngine.getInstance();
  engine.start();
}

export function pauseOptimizationEngine() {
  const engine = ImageOptimizationEngine.getInstance();
  engine.pause();
}

export function notifyImageUploaded() {
  const engine = ImageOptimizationEngine.getInstance();
  engine.notifyNewImage();
}

export function getOptimizationEngineStatus() {
  const engine = ImageOptimizationEngine.getInstance();
  return engine.getStatus();
}
