// 超时常量
const FRONTEND_COMPILE_TIMEOUT = 5000; // 5 秒
const FRONTEND_COMPILE_MAX_RETRIES = 1; // 最多重试 1 次（最坏 10 秒）
const IMAGE_OPTIMIZATION_WAIT_TIMEOUT = 3000; // 最多额外等 3 秒
const IMAGE_OPTIMIZATION_WAIT_INTERVAL = 300;

// 调试模式（通过 localStorage 启用）
const DEBUG_ENABLED =
  typeof window !== 'undefined' && localStorage.getItem('zeroy_debug') === '1';

// 调试日志
function debugLog(category: string, message: string, data?: unknown) {
  if (!DEBUG_ENABLED) {
    return;
  }
  const prefix = `[ZeroY Save ${new Date().toISOString()}] [${category}]`;
  // eslint-disable-next-line no-console
  console.log(`${prefix} ${message}`, data ?? '');
}

// 超时辅助函数
const timeout = <T,>(ms: number, message: string): Promise<T> => {
  return new Promise((_, reject) => {
    setTimeout(() => reject(new Error(message)), ms);
  });
};

const sleep = (ms: number): Promise<void> => {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
};

// CSS 编译结果类型
interface CSSCompileResult {
  compiledCss: string | null;
  compileSource: 'frontend' | 'backend' | 'cdn' | null;
  compileError: Error | null;
}

// 编译结果类型
interface CompileResultData {
  success?: boolean;
  completed?: number;
  failed?: number;
  total?: number;
}

// 保存结果类型
interface SaveResult {
  success: boolean;
  global_template_changed: boolean;
  compile_result?: CompileResultData;
  speed_optimization_enabled?: boolean;
  compiledCss?: string | null;
  compileSource?: 'frontend' | 'backend' | 'cdn' | null;
  compileError?: Error | null;
}

// 处理后端编译结果（提取函数降低复杂度）
function handleBackendCompileResult(rawResult: {
  global_template_changed?: boolean;
  compile_result?: CompileResultData;
  speed_optimization_enabled?: boolean;
}): SaveResult | null {
  const {
    global_template_changed,
    compile_result,
    speed_optimization_enabled,
  } = rawResult;

  // 全局模板（header/footer）
  if (global_template_changed && compile_result) {
    debugLog(
      'save',
      'Global template changed, backend compiled',
      compile_result
    );
    return {
      success: true,
      global_template_changed: true,
      compile_result,
      speed_optimization_enabled,
    };
  }

  // 非全局模板（single/archive 等）
  if (compile_result && (compile_result.completed ?? 0) > 0) {
    debugLog('save', 'Template CSS compiled by backend', compile_result);
    return {
      success: true,
      global_template_changed: false,
      compile_result,
      speed_optimization_enabled,
    };
  }

  // 速度优化未开启
  if (!speed_optimization_enabled) {
    debugLog('save', 'Speed optimization disabled, skipping compile');
    return {
      success: true,
      speed_optimization_enabled: false,
      global_template_changed: false,
    };
  }

  return null; // 需要前端编译
}

// 保存编译后的 CSS（提取函数降低复杂度）
async function saveCompiledResult(
  postId: number,
  compiledCss: string | null,
  compileSource: 'frontend' | 'backend' | 'cdn' | null,
  header_footer_hash: string,
  design_system_hash: string
): Promise<void> {
  if (compiledCss && compileSource && compileSource !== 'cdn') {
    debugLog('save', 'Saving compiled CSS', {
      source: compileSource,
      header_footer_hash,
      design_system_hash,
    });
    await contentApi.saveCompiledCSS(postId, {
      css: compiledCss,
      source: compileSource,
      header_footer_hash,
      design_system_hash,
    });
  } else {
    debugLog('save', 'Marking to use CDN (compile failed or empty)');
    await contentApi.markUseCDN(postId);
  }
}

// 前端编译尝试
async function tryFrontendCompile(content: string): Promise<CSSCompileResult> {
  if (!isCompilerReady()) {
    throw new Error('编译器未就绪');
  }

  const headerFooterData = await contentApi.getHeaderFooter();
  const result = await Promise.race([
    compileSinglePage(content, headerFooterData),
    timeout<SinglePageCompileResult | null>(
      FRONTEND_COMPILE_TIMEOUT,
      'Frontend compile timeout'
    ),
  ]);

  if (result?.css) {
    return {
      compiledCss: result.css,
      compileSource: 'frontend',
      compileError: null,
    };
  }
  throw new Error('前端编译返回空结果');
}

// CSS 编译流程（带重试和 CDN 降级）
async function compileCSS(
  content: string,
  _postId: number
): Promise<CSSCompileResult> {
  let lastError: Error | null = null;

  // 重试前端编译
  for (let attempt = 0; attempt <= FRONTEND_COMPILE_MAX_RETRIES; attempt++) {
    try {
      if (attempt > 0) {
        debugLog(
          'compile',
          `前端编译重试 (${attempt}/${FRONTEND_COMPILE_MAX_RETRIES})`
        );
      }
      return await tryFrontendCompile(content);
    } catch (error) {
      lastError = error as Error;
      debugLog('compile', `前端编译失败 (attempt ${attempt + 1})`, error);
    }
  }

  // 所有重试都失败，降级到 CDN
  // eslint-disable-next-line no-console
  console.warn('前端编译失败，将使用 CDN:', lastError);
  return {
    compiledCss: null,
    compileSource: 'cdn',
    compileError: lastError,
  };
}

async function waitForImageOptimizationAndRefresh(
  postId: number,
  imageOptimizationEnabled: boolean,
  setSaveProgress: (message: string) => void
): Promise<void> {
  if (!(imageOptimizationEnabled && postId)) {
    return;
  }

  try {
    let status: PageImageOptimizationStatus =
      await contentApi.getImageOptimizationStatus(postId);

    if (!status.enabled || status.total_images === 0) {
      return;
    }

    const startTime = Date.now();

    while (!status.all_ready) {
      const elapsed = Date.now() - startTime;
      if (elapsed >= IMAGE_OPTIMIZATION_WAIT_TIMEOUT) {
        debugLog('save', 'Image optimization wait timed out', status);
        break;
      }

      setSaveProgress(
        `等待图片优化... (${status.ready_images}/${status.total_images})`
      );
      await sleep(IMAGE_OPTIMIZATION_WAIT_INTERVAL);
      status = await contentApi.getImageOptimizationStatus(postId);
    }

    await contentApi.refreshOptimizedHTML(postId);
    debugLog('save', 'Image optimization refresh completed', status);
  } catch (error) {
    debugLog('save', 'Image optimization wait/refresh failed', error);
  }
}

// 处理全局模板变更（header/footer）后的整站编译
async function handleGlobalTemplateChange(
  localCompiler: ReturnType<typeof useLocalCompiler>,
  notify: ReturnType<typeof useNotification>['notify']
): Promise<void> {
  // 清除前端 header/footer 缓存，确保后续编译使用最新内容
  contentApi.clearHeaderFooterCache();
  debugLog('save', 'Global template changed, triggering site-wide compilation');

  notify('info', '保存成功，正在进行整站速度优化...', 3000);

  try {
    // 触发整站编译（复用极致压缩逻辑）
    const compileResult = await localCompiler.compile();

    if (compileResult) {
      const { stats, errors } = compileResult;
      const totalCompiled = stats.compiledPages + stats.compiledTemplates;
      const hasErrors = errors.length > 0;

      if (hasErrors) {
        notify('warning', `整站优化完成，但 ${errors.length} 个项目失败`, 5000);
      } else {
        notify('success', `整站优化完成（${totalCompiled} 个项目）`);
      }
    }
  } catch (error) {
    debugLog('save', 'Site-wide compilation failed', error);
    notify('warning', '整站优化失败，将使用 CDN 模式', 5000);
  }
}

// 处理保存成功的通知
function handleSaveSuccessNotification(
  result: SaveResult,
  notify: ReturnType<typeof useNotification>['notify']
): void {
  // 速度优化未开启
  if (!result.speed_optimization_enabled) {
    notify('success', '保存成功');
    return;
  }

  // 非全局模板（single/archive 等）：后端编译了模板 CSS
  if (result.compile_result && (result.compile_result.completed ?? 0) > 0) {
    notify('success', '保存成功，速度优化完成');
    return;
  }

  // 普通页面：前端编译
  if (result.compiledCss && result.compileSource !== 'cdn') {
    notify('success', '保存成功，速度优化完成');
    return;
  }

  // 其他情况
  notify('success', '保存成功');
}

export const EditorToolbar: React.FC = () => {
  const { notify } = useNotification();
  const {
    content,
    isDirty,
    isSaving,
    setSaving,
    resetDirty,
    isSelecting,
    setSelecting,
    previewDevice,
    setPreviewDevice,
  } = useEditorStore();
  const postId = window.zeroyEditor?.postId;
  const [isMediaLibraryOpen, setIsMediaLibraryOpen] = useState(false);
  const [aiDialogMode, setAIDialogMode] = useState<
    'code' | 'dynamic-data' | null
  >(null);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [saveProgress, setSaveProgress] = useState('');
  const { available: hasAIModels, loading: isModelCheckLoading } =
    useAIModelAvailability();

  // 整站编译 hook（用于 header/footer 保存后自动触发）
  const localCompiler = useLocalCompiler();

  // 编辑器加载完成后，立即预热编译器
  useEffect(() => {
    warmupCompiler()
      .then(() => {
        // eslint-disable-next-line no-console
        console.log('Tailwind 编译器已就绪');
      })
      .catch((err) => {
        // eslint-disable-next-line no-console
        console.error('编译器预热失败:', err);
      });
  }, []);

  // 获取文章信息
  const { data: postData } = useQuery({
    queryKey: ['content', postId],
    queryFn: () => contentApi.get(postId ?? 0),
    enabled: !!postId,
  });

  // 直接从查询数据中派生标题，而不是使用 useState 和 useEffect
  const postTitle =
    postData && 'title' in postData && postData.title ? postData.title : '';

  const saveMutation = useMutation({
    mutationFn: async (): Promise<SaveResult> => {
      debugLog('save', 'Starting save flow', {
        postId,
        contentLength: content.length,
      });
      setSaveProgress('保存中...');

      // 第 1 步：保存 raw 内容（核心数据，必须成功）
      const rawResult = await contentApi.saveRaw(postId ?? 0, { content });
      debugLog('save', 'saveRaw result', rawResult);

      const imageOptimizationPromise = waitForImageOptimizationAndRefresh(
        postId ?? 0,
        !!rawResult.image_optimization_enabled,
        setSaveProgress
      );

      // 检查后端是否已完成编译
      const backendResult = handleBackendCompileResult(rawResult);
      if (backendResult) {
        await imageOptimizationPromise;
        return backendResult;
      }

      // 检查是否关闭了自动优化
      // 如果关闭，跳过编译，直接返回
      if (!rawResult.speed_optimization_enabled) {
        debugLog(
          'save',
          'Speed optimization disabled, skipping CSS compilation'
        );
        const result: SaveResult = {
          success: true,
          compiledCss: null,
          compileSource: null,
          compileError: null,
          global_template_changed: false,
          speed_optimization_enabled: false,
        };
        await imageOptimizationPromise;
        return result;
      }

      // 第 2 步：普通页面 - 前端编译 CSS（带超时和降级）
      debugLog('save', 'Starting frontend CSS compile');
      setSaveProgress('速度优化中...');
      const { compiledCss, compileSource, compileError } = await compileCSS(
        content,
        postId ?? 0
      );
      debugLog('save', 'CSS compile result', {
        hasCSS: !!compiledCss,
        cssLength: compiledCss?.length,
        source: compileSource,
        error: compileError?.message,
      });

      // 第 3 步：保存编译结果
      await saveCompiledResult(
        postId ?? 0,
        compiledCss,
        compileSource,
        rawResult.header_footer_hash,
        rawResult.design_system_hash
      );

      await imageOptimizationPromise;

      return {
        success: true,
        compiledCss,
        compileSource,
        compileError,
        global_template_changed: false,
      };
    },
    onMutate: () => setSaving(true),
    onSuccess: async (result) => {
      debugLog('save', 'Save completed', result);
      resetDirty();

      // 全局模板（header/footer）：仅在自动优化开启时触发整站编译
      if (result.global_template_changed && result.speed_optimization_enabled) {
        await handleGlobalTemplateChange(localCompiler, notify);
        return;
      }

      // 其他情况：显示保存成功通知
      handleSaveSuccessNotification(result, notify);
    },
    onError: (error) => {
      notify('error', `保存失败：${(error as Error).message}`);
    },
    onSettled: () => {
      setSaving(false);
      setSaveProgress('');
    },
  });

  const handleSave = React.useCallback(() => {
    if (!isDirty || isSaving) {
      return;
    }
    saveMutation.mutate();
  }, [isDirty, isSaving, saveMutation]);

  const handleConfirmSave = React.useCallback(() => {
    setShowSaveConfirm(false);
    saveMutation.mutate();
  }, [saveMutation]);

  const handleMediaLibrary = React.useCallback(() => {
    setIsMediaLibraryOpen(true);
  }, []);

  const handleAIAssistant = React.useCallback(() => {
    setAIDialogMode('code');
  }, []);

  const handleBackToWordPress = React.useCallback(() => {
    if (isDirty && !window.confirm('您有未保存的更改，确定要离开吗？')) {
      return;
    }
    window.history.back();
  }, [isDirty]);

  // 处理选择模式切换
  const handleToggleSelectionMode = React.useCallback(() => {
    setSelecting(!isSelecting);
  }, [isSelecting, setSelecting]);

  // 快捷键支持
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
        e.preventDefault();
        handleSave();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSave]);

  return (
    <>
      <div className="flex h-14 items-stretch border-gray-200 border-b bg-white shadow-sm">
        {/* 左侧：返回按钮和页面标题 */}
        <div className="flex items-stretch">
          <button
            className="flex items-center border-gray-200 border-r px-4 text-gray-700 transition-colors hover:bg-gray-50"
            onClick={handleBackToWordPress}
            title="返回 WordPress"
            type="button"
          >
            <svg
              className="mr-2 h-4 w-4"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <title>返回</title>
              <path
                d="M11 17l-5-5m0 0l5-5m-5 5h12"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
            <span className="font-medium">返回</span>
          </button>

          <div className="flex items-center px-4">
            <h1 className="!text-sm text-gray-700" title={postTitle}>
              {(() => {
                if (!postTitle) {
                  return '未命名页面';
                }
                if (postTitle.length > 30) {
                  return `${postTitle.substring(0, 30)}...`;
                }
                return postTitle;
              })()}
            </h1>
            {isDirty && (
              <span className="ml-2 text-amber-600 text-sm">• 未保存</span>
            )}
          </div>
        </div>

        {/* 中间：功能按钮组 */}
        <div className="flex flex-1 items-center justify-center space-x-2">
          <button
            className="rounded-md px-3 py-2 text-gray-700 transition-colors hover:bg-gray-100"
            onClick={handleMediaLibrary}
            title="媒体库"
            type="button"
          >
            <svg
              className="h-5 w-5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <title>媒体库</title>
              <path
                d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
          </button>

          <button
            className={`rounded-md px-3 py-2 transition-colors ${
              isSelecting
                ? 'bg-blue-600 text-white'
                : 'text-gray-700 hover:bg-gray-100'
            }`}
            onClick={handleToggleSelectionMode}
            title={isSelecting ? '取消选择' : '选择元素'}
            type="button"
          >
            <svg
              className="h-5 w-5"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <title>{isSelecting ? '取消选择' : '选择元素'}</title>
              <path
                d="M15 15l-2 5L9 9l11 4-5 2zm0 0l5 5M7.188 2.239l.777 2.897M5.136 7.965l-2.898-.777M13.95 4.05l-2.122 2.122m-5.657 5.656l-2.12 2.122"
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
              />
            </svg>
          </button>

          {hasAIModels && (
            <button
              aria-busy={isModelCheckLoading}
              className="rounded-md px-3 py-2 text-gray-700 transition-colors hover:bg-gray-100"
              disabled={isModelCheckLoading && !hasAIModels}
              onClick={handleAIAssistant}
              title="AI 助手"
              type="button"
            >
              <RobotIcon />
            </button>
          )}
        </div>

        {/* 右侧：设备切换 + 预览/保存 */}
        <div className="flex items-stretch">
          <div className="flex items-center border-gray-200 border-l px-3">
            <div className="flex items-center gap-px rounded-md border border-gray-200 bg-gray-50 p-0.5">
              <button
                aria-label="桌面视图"
                aria-pressed={previewDevice === 'desktop'}
                className={`rounded px-2 py-1 text-gray-600 transition-colors hover:text-gray-800 ${
                  previewDevice === 'desktop'
                    ? 'bg-white text-blue-600 shadow-sm'
                    : ''
                }`}
                onClick={() => setPreviewDevice('desktop')}
                type="button"
              >
                <Monitor aria-hidden className="h-4 w-4" />
              </button>
              <button
                aria-label="手机视图"
                aria-pressed={previewDevice === 'mobile'}
                className={`rounded px-2 py-1 text-gray-600 transition-colors hover:text-gray-800 ${
                  previewDevice === 'mobile'
                    ? 'bg-white text-blue-600 shadow-sm'
                    : ''
                }`}
                onClick={() => setPreviewDevice('mobile')}
                type="button"
              >
                <Smartphone aria-hidden className="h-4 w-4" />
              </button>
            </div>
          </div>
          <button
            className="flex items-center border-gray-200 border-l px-4 text-gray-700 transition-colors hover:bg-gray-100"
            onClick={() => {
              // 打开预览窗口
              const previewUrl = window.zeroyEditor?.previewUrl;
              if (previewUrl) {
                // 使用模板的预览 URL
                window.open(previewUrl, '_blank');
              } else if (postId) {
                // 普通页面预览，使用站点本地化地址作为基准
                const homeUrl =
                  window.zeroyEditor?.homeUrl ?? window.location.origin;
                const url = new URL(homeUrl);
                url.searchParams.set('page_id', String(postId));
                url.searchParams.set('preview', 'true');
                window.open(url.toString(), '_blank');
              }
            }}
            title="预览"
            type="button"
          >
            <EyeIcon />
          </button>
          <button
            className={(() => {
              const baseClasses =
                'flex items-center border-gray-200 border-l px-6 font-medium transition-colors';
              if (!isDirty || isSaving) {
                return `${baseClasses} cursor-not-allowed bg-gray-100 text-gray-400`;
              }
              return `${baseClasses} bg-blue-600 text-white hover:bg-blue-700`;
            })()}
            disabled={!isDirty || isSaving}
            onClick={handleSave}
            type="button"
          >
            {isSaving ? saveProgress || '保存中...' : '保存'}
          </button>
        </div>
      </div>

      <CustomMediaLibrary
        isOpen={isMediaLibraryOpen}
        onClose={() => setIsMediaLibraryOpen(false)}
      />

      <UnifiedAIDialog
        isOpen={aiDialogMode !== null}
        onClose={() => setAIDialogMode(null)}
      />

      <SaveConfirmDialog
        isOpen={showSaveConfirm}
        onCancel={() => setShowSaveConfirm(false)}
        onConfirm={handleConfirmSave}
      />
    </>
  );
};
