import type { EditorView } from '@codemirror/view';
import { useCallback } from 'react';
import type { ElementPosition } from '../types';

export const useCodeHighlight = () => {
  // We don't need any extensions for native selection
  const highlightExtension: never[] = [];

  // Select text like native selection
  const highlightPosition = useCallback(
    (view: EditorView, position: ElementPosition) => {
      const { start, end } = position;
      const docLength = view.state.doc.length;

      // Validate offsets are within document bounds
      const safeStart = Math.max(0, Math.min(start.offset, docLength));
      const safeEnd = Math.max(0, Math.min(end.offset, docLength));

      // Only dispatch selection if offsets are valid
      if (safeStart <= safeEnd && safeEnd <= docLength) {
        // Use native selection
        view.dispatch({
          selection: { anchor: safeStart, head: safeEnd },
          scrollIntoView: true,
        });

        // Focus the editor to enable keyboard input
        view.focus();
      } else {
        console.warn('Selection offsets out of bounds:', {
          start: start.offset,
          end: end.offset,
          docLength,
          safeStart,
          safeEnd,
        });
      }
    },
    []
  );

  // Clear selection
  const clearHighlight = useCallback((view: EditorView) => {
    // Move cursor to the end of current selection
    const pos = view.state.selection.main.head;
    view.dispatch({
      selection: { anchor: pos },
    });
  }, []);

  return {
    highlightExtension,
    highlightPosition,
    clearHighlight,
  };
};
