import type React from 'react';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useNotification } from '@/components/notification';
import { useEditorStore } from '@/store/editor';
import { useAIPolling } from '../hooks/use-ai-polling';
import { useCompletionReminder } from '../hooks/use-completion-reminder';
import { FakeStreamDisplay } from '../shared/fake-stream-display';
import { MessageBubble } from '../shared/message-bubble';
import { WelcomeGuide } from '../shared/welcome-guide';
import { useAIHistoryStore } from '../store/ai-history';
import type { AIRequestBody, Message } from '../types/ai-dialog.types';

interface CodeModePanelProps {
  onClose?: () => void;
  selectedModel?: string;
  initialPrompt?: string;
}

export const CodeModePanel: React.FC<CodeModePanelProps> = ({
  onClose,
  selectedModel,
  initialPrompt,
}) => {
  const { notify } = useNotification();
  const { content, setContent, selectedText, selectionStart, selectionEnd } =
    useEditorStore();
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const initialPromptProcessedRef = useRef(false);
  const { entries, addEntry, removeEntry, clearEntries, loadFromStorage } =
    useAIHistoryStore();
  const completionReminder = useCompletionReminder();

  // 加载持久化的历史记录
  useEffect(() => {
    const postId = window.zeroyEditor?.postId;
    if (postId) {
      loadFromStorage(postId);
    }
  }, [loadFromStorage]);

  // Polling hook for non-streaming
  const { isPolling, startPolling, cancelPolling } = useAIPolling();

  // 创建请求体
  const createRequestBody = useCallback(
    (prompt: string): AIRequestBody => {
      // Use new comprehensive WordPress context if available, fall back to legacy
      const wordpressContext = window.zeroyEditor?.wordpressContext || {
        // Fallback to legacy structure if new context not available
        site: {
          name: '',
          description: '',
          url: window.location.origin,
          home_url: window.location.origin,
          admin_url: `${window.location.origin}/wp-admin`,
          language: 'en-US',
          timezone: 'UTC',
          date_format: 'Y-m-d',
          time_format: 'H:i:s',
        },
        post_types: {},
        posts: {},
        fields: {},
        taxonomies: {},
        terms: {},
        menus: window.zeroyEditor?.menus || [],
        menu_locations: {},
        current_user: {
          id: 0,
          username: '',
          email: '',
          display_name: '',
          roles: [],
        },
        user_roles: {},
        theme: { name: '', version: '', template: '', stylesheet: '' },
        plugins: [],
        editing_context: {
          post_id: window.zeroyEditor?.postId,
          post_type: window.zeroyEditor?.postType,
          template_type: window.zeroyEditor?.templateType,
          is_template: window.zeroyEditor?.isTemplate,
          user: { id: 0, username: '', email: '', display_name: '', roles: [] },
          can_edit: true,
          can_publish: true,
          can_delete: false,
        },
        generated_at: new Date().toISOString(),
        api_version: '1.0.0',
      };

      return {
        config: {
          api_key: window.zeroyEditor?.aiSettings?.api_key || '',
          base_url: window.zeroyEditor?.aiSettings?.base_url || '',
          model:
            selectedModel || window.zeroyEditor?.aiSettings?.model || 'gpt-4o',
        },
        request: {
          user_prompt: prompt,
          selected_code: selectedText || '',
          design_system_html: window.zeroyEditor?.designSystemHtml || '',
          additional_context:
            window.zeroyEditor?.aiSettings?.additional_context || '',
          wordpress_context: wordpressContext,
          conversation: messages.map((msg) => ({
            role: msg.role,
            content: msg.content,
          })),
          stream: false,
        },
      };
    },
    [selectedModel, selectedText, messages]
  );

  // 处理生成的代码
  const handleGeneratedCode = useCallback(
    (generatedCode: string, originalPrompt: string) => {
      if (!generatedCode || generatedCode.trim() === '') {
        notify('warning', '未生成代码，请检查您的输入或 API 配置');
        return false;
      }

      const aiMessage: Message = {
        id: `ai-${Date.now()}`,
        role: 'assistant',
        content: '代码生成完成！',
        template: generatedCode,
      };
      setMessages((prev) => [...prev, aiMessage]);
      // 记录历史（仅当前页面会话）
      addEntry({ prompt: originalPrompt, code: generatedCode });
      notify('success', 'AI 代码生成完成');
      completionReminder.complete();
      return true;
    },
    [notify, addEntry, completionReminder]
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isPolling) {
      return;
    }

    // 添加用户消息
    const promptToSend = inputValue.trim();

    const userMessage: Message = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: promptToSend,
    };
    setMessages((prev) => [...prev, userMessage]);

    const requestBody = createRequestBody(promptToSend);
    setInputValue('');
    completionReminder.arm({ requestPermission: true });

    try {
      const generatedCode = await startPolling(requestBody);
      handleGeneratedCode(generatedCode, promptToSend);
    } catch (error: any) {
      if (error.name !== 'AbortError') {
        notify('error', `AI 请求失败：${error.message}`);
      }
    }
  };

  // 自动发送初始提示
  useEffect(() => {
    if (initialPrompt && !initialPromptProcessedRef.current && !isPolling) {
      initialPromptProcessedRef.current = true;
      // 不再设置到输入框，直接发送

      // 延迟一点发送，确保组件已完全加载
      setTimeout(() => {
        if (initialPrompt.trim()) {
          // 添加用户消息
          const userMessage: Message = {
            id: `user-${Date.now()}`,
            role: 'user',
            content: initialPrompt,
          };
          setMessages((prev) => [...prev, userMessage]);

          const requestBody = createRequestBody(initialPrompt);
          completionReminder.arm({ requestPermission: false });

          // 自动发送请求
          startPolling(requestBody)
            .then((generatedCode) => {
              handleGeneratedCode(generatedCode, initialPrompt);
            })
            .catch((error: any) => {
              if (error.name !== 'AbortError') {
                notify('error', `AI 请求失败：${error.message}`);
              }
            });
        }
      }, 100);
    }
  }, [
    initialPrompt,
    isPolling,
    createRequestBody,
    startPolling,
    handleGeneratedCode,
    notify,
    completionReminder,
  ]);

  const handleCancelGeneration = () => {
    completionReminder.clear();
    cancelPolling();
  };

  const applyGeneratedCode = (code: string) => {
    // 始终使用 selectionStart 和 selectionEnd，即使它们相同（光标位置）
    const insertPosition = selectionStart ?? 0;
    const endPosition = selectionEnd ?? insertPosition;

    const beforeSelection = content.substring(0, insertPosition);
    const afterSelection = content.substring(endPosition);
    setContent(beforeSelection + code + afterSelection);

    // 插入后关闭对话框
    if (onClose) {
      onClose();
    }
  };

  return (
    <div className="flex h-full flex-col">
      {/* 最近历史（仅当前会话） */}
      {entries.length > 0 && (
        <div className="border-b bg-gray-50 p-3">
          <div className="flex items-center justify-between">
            <div className="font-medium text-gray-700 text-sm">最近历史</div>
            <button
              className="text-gray-500 text-xs hover:text-gray-700"
              onClick={clearEntries}
              type="button"
            >
              清空
            </button>
          </div>
          <div className="mt-2 max-h-32 space-y-1 overflow-y-auto">
            {entries.map((item) => (
              <div
                className="flex items-center justify-between text-xs"
                key={item.id}
                title={item.prompt}
              >
                <div className="mr-2 line-clamp-1 flex-1 truncate text-gray-700">
                  {item.prompt}
                </div>
                <div className="flex flex-shrink-0 items-center gap-2">
                  <button
                    className="text-blue-600 hover:underline"
                    onClick={() => setInputValue(item.prompt)}
                    type="button"
                  >
                    复用
                  </button>
                  {item.code && (
                    <button
                      className="text-green-600 hover:underline"
                      onClick={() => applyGeneratedCode(item.code || '')}
                      type="button"
                    >
                      插入
                    </button>
                  )}
                  <button
                    className="text-gray-400 hover:text-red-500"
                    onClick={() => removeEntry(item.id)}
                    title="删除"
                    type="button"
                  >
                    ✕
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
      {/* 选中代码提示 */}
      {selectedText && (
        <div className="border-b bg-gray-50 p-3">
          <p className="text-gray-600 text-sm">已选中代码片段（将被替换）</p>
        </div>
      )}

      {/* 对话区域 */}
      <div className="flex-1 overflow-y-auto p-4">
        {/* 当没有消息时显示欢迎界面 */}
        {messages.length === 0 && !isPolling ? (
          <WelcomeGuide
            hasSelectedText={!!selectedText}
            onExampleClick={(example) => setInputValue(example)}
            templateType={window.zeroyEditor?.templateType}
          />
        ) : (
          <>
            {messages.map((message) => (
              <MessageBubble
                key={message.id}
                message={message}
                onInsertCode={applyGeneratedCode}
              />
            ))}

            {/* 假流式显示 */}
            <FakeStreamDisplay isActive={isPolling} />
          </>
        )}
      </div>

      {/* 输入区域 */}
      <form className="border-t p-4" onSubmit={handleSubmit}>
        <div className="flex space-x-2">
          <input
            autoFocus
            className="flex-1 rounded-md border border-gray-300 px-4 py-2 focus:border-blue-500 focus:outline-none"
            disabled={isPolling}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder="描述您需要的代码..."
            type="text"
            value={inputValue}
          />
          <button
            className={`rounded-md px-6 py-2 font-medium text-white transition ${
              isPolling || !inputValue.trim()
                ? 'cursor-not-allowed bg-gray-400'
                : 'bg-blue-600 hover:bg-blue-700'
            }`}
            disabled={isPolling || !inputValue.trim()}
            type="submit"
          >
            {isPolling ? '生成中...' : '发送'}
          </button>
          {isPolling && (
            <button
              className="rounded-md border border-gray-300 px-4 py-2 text-gray-700 hover:bg-gray-50"
              onClick={handleCancelGeneration}
              type="button"
            >
              取消
            </button>
          )}
        </div>
      </form>
    </div>
  );
};
