/**
 * 浏览器端图片处理工具 - v6.0 懒编码架构
 *
 * 新架构（完全无感上传）：
 * 1. 上传时：只上传原图到 WordPress（0.5-1 秒）
 * 2. 后台处理：用户在编辑器时，后台引擎自动优化整个媒体库
 *    - 原格式压缩（jsquash）
 *    - WebP 转换
 * 3. 完全静默：不影响用户正常使用
 */

import {
  getUnsupportedFeatures,
  supportsClientSideOptimization,
} from './browser-capability';
import { ImageWorkerPool } from './worker-pool';

/**
 * 文件名规范化正则表达式（顶层常量，避免重复创建）
 *
 * 统一规则（前后端一致）：
 * 1. 特殊字符 → -
 * 2. 连续 - → 单个 -
 * 3. 去掉首尾 -
 */
const FILENAME_SPECIAL_CHARS_REGEX = /[\s()[\]<>{}|\\^`~!@#$%&*]+/g;
const FILENAME_MULTI_DASH_REGEX = /-+/g;
const FILENAME_EDGE_DASH_UNDERSCORE_REGEX = /^[-_]+|[-_]+$/g;

/**
 * 全局 Worker 池单例（懒加载）
 */
let workerPool: ImageWorkerPool | null = null;

/**
 * 浏览器能力检查缓存
 */
let browserSupported: boolean | null = null;

/**
 * 获取或创建 Worker 池（带浏览器能力检测）
 *
 * @throws {Error} 如果浏览器不支持必需特性
 */
export function getWorkerPool(): ImageWorkerPool {
  // 检查浏览器能力（只检查一次）
  if (browserSupported === null) {
    browserSupported = supportsClientSideOptimization();

    if (!browserSupported) {
      const unsupported = getUnsupportedFeatures();
      const errorMsg = `浏览器不支持客户端图片优化（缺少：${unsupported.join(', ')}）`;
      console.warn(`[ZeroY] ⚠️ ${errorMsg}`);
      console.info('[ZeroY] 💡 将使用服务器端优化（功能正常，但速度可能较慢）');
      throw new Error(errorMsg);
    }
  }

  // 如果之前检测不支持，直接抛出错误
  if (!browserSupported) {
    throw new Error('浏览器不支持客户端图片优化');
  }

  // 创建 Worker 池
  if (!workerPool) {
    try {
      workerPool = new ImageWorkerPool();
      console.log('[ZeroY] 🚀 Worker 池已创建');
    } catch (error) {
      console.error('[ZeroY] ❌ Worker 池创建失败:', error);
      browserSupported = false; // 标记为不支持
      throw error;
    }
  }
  return workerPool;
}

/**
 * 清理 Worker 池
 */
export function cleanupWorkerPool() {
  if (workerPool) {
    workerPool.destroy();
    workerPool = null;
    console.log('[ZeroY] 🗑️ Worker 池已清理');
  }
}

/**
 * WordPress 媒体详情接口
 */
export interface WordPressMediaDetails {
  width: number;
  height: number;
  file: string;
  sizes?: Record<
    string,
    {
      file: string;
      width: number;
      height: number;
      mime_type: string;
      source_url: string;
    }
  >;
}

/**
 * WordPress 媒体响应接口
 */
export interface WordPressMediaResponse {
  id: number;
  source_url: string;
  media_details: WordPressMediaDetails;
  mime_type: string;
}

/**
 * 上传结果（简化版）
 */
export interface UploadResult {
  attachment_id: number;
  sourceFormat: 'jpeg' | 'png' | 'webp';
  sizes: Array<{
    width: number;
    height: number;
    file: string;
    url: string;
  }>;
}

/**
 * 规范化文件名
 *
 * 目的：避免特殊字符导致的文件名/URL 不一致问题
 *
 * 统一规则（与后端 PHP normalize_filename 一致）：
 * 1. 特殊字符（空格、括号、方括号等）→ -
 * 2. 连续 - → 单个 -
 * 3. 去掉首尾 -
 * 4. 空名 → image
 */
function sanitizeFileName(filename: string): string {
  // 分离文件名和扩展名
  const lastDotIndex = filename.lastIndexOf('.');
  if (lastDotIndex === -1) {
    return filename;
  }

  let name = filename.substring(0, lastDotIndex);
  const ext = filename.substring(lastDotIndex).toLowerCase();

  // 1. 特殊字符 → -
  name = name.replace(FILENAME_SPECIAL_CHARS_REGEX, '-');

  // 2. 连续 - → 单个 -
  name = name.replace(FILENAME_MULTI_DASH_REGEX, '-');

  // 3. 去掉首尾 - 和 _
  name = name.replace(FILENAME_EDGE_DASH_UNDERSCORE_REGEX, '');

  // 4. 空名 → image
  if (!name) {
    name = 'image';
  }

  return name + ext;
}

/**
 * 检测源文件格式
 */
export function detectSourceFormat(
  file: File
): 'jpeg' | 'png' | 'webp' | 'unknown' {
  const type = file.type.toLowerCase();
  if (type === 'image/jpeg' || type === 'image/jpg') {
    return 'jpeg';
  }
  if (type === 'image/png') {
    return 'png';
  }
  if (type === 'image/webp') {
    return 'webp';
  }
  return 'unknown';
}

/**
 * 上传文件到 WordPress
 */
async function uploadToWordPress(file: File): Promise<WordPressMediaResponse> {
  const startTime = performance.now();

  // 规范化文件名（避免连续的 - 或末尾 - 导致的问题）
  const sanitizedName = sanitizeFileName(file.name);
  const uploadFile =
    sanitizedName !== file.name
      ? new File([file], sanitizedName, { type: file.type })
      : file;

  if (sanitizedName !== file.name) {
    console.log(
      `[ZeroY Upload] 📝 文件名规范化: "${file.name}" → "${sanitizedName}"`
    );
  }

  console.log('[ZeroY Upload] 📤 开始上传原图到 WordPress');

  const formData = new FormData();
  formData.append('file', uploadFile);

  const uploadResponse = await fetch('/wp-json/wp/v2/media', {
    method: 'POST',
    headers: {
      'X-WP-Nonce': window.zeroyEditor?.nonce || '',
    },
    body: formData,
  });

  if (!uploadResponse.ok) {
    const errorText = await uploadResponse.text();
    throw new Error(`WordPress 上传失败: ${errorText}`);
  }

  const result = await uploadResponse.json();
  const elapsed = performance.now() - startTime;
  console.log(
    `[ZeroY Upload] ✅ WordPress 上传完成，耗时: ${elapsed.toFixed(0)}ms`
  );

  return result;
}

/**
 * 从 WordPress 媒体响应中提取所有尺寸信息
 */
function extractSizes(
  wpMedia: WordPressMediaResponse
): Array<{ width: number; height: number; file: string; url: string }> {
  const mediaDetails = wpMedia.media_details;
  const sizes: Array<{
    width: number;
    height: number;
    file: string;
    url: string;
  }> = [];

  // 添加原图（full size）
  sizes.push({
    url: wpMedia.source_url,
    file: mediaDetails.file.split('/').pop() || 'image.jpg',
    width: mediaDetails.width,
    height: mediaDetails.height,
  });

  // 添加所有缩略图
  if (mediaDetails.sizes) {
    for (const sizeData of Object.values(mediaDetails.sizes)) {
      sizes.push({
        url: sizeData.source_url,
        file: sizeData.file,
        width: sizeData.width,
        height: sizeData.height,
      });
    }
  }

  return sizes;
}

/**
 * 上传图片到 WordPress（极简版 - 只上传原图）
 *
 * 核心理念：
 * - 上传时只上传原图（0.5-1 秒完成）
 * - WordPress 自动生成所有尺寸的原格式文件
 * - 压缩、WebP 全部交给后台优化引擎
 *
 * @param file 原始图片文件
 * @param callbacks 进度回调（可选）
 * @returns 上传结果（attachment_id + 源格式 + 尺寸信息）
 */
export async function uploadAndProcessImage(
  file: File,
  callbacks?: {
    onProgress?: (message: string, current: number, total: number) => void;
  }
): Promise<UploadResult> {
  const startTime = performance.now();
  console.log(
    `[ZeroY Upload] ==================== 开始上传: ${file.name} ====================`
  );

  // 检测源格式
  const sourceFormat = detectSourceFormat(file);
  if (sourceFormat === 'unknown') {
    throw new Error('不支持的图片格式');
  }

  // 上传到 WordPress（只上传原图，WordPress 会自动生成各种尺寸）
  callbacks?.onProgress?.('上传到 WordPress...', 0, 100);
  const wpMedia = await uploadToWordPress(file);

  // 提取尺寸信息
  const sizes = extractSizes(wpMedia);
  console.log(`[ZeroY Upload] WordPress 生成了 ${sizes.length} 个尺寸版本`);

  callbacks?.onProgress?.('上传完成', 100, 100);

  const elapsed = performance.now() - startTime;
  console.log(
    `[ZeroY Upload] ==================== 上传总耗时: ${elapsed.toFixed(0)}ms ====================`
  );

  // 返回结果（后续的压缩、WebP 交给后台引擎处理）
  return {
    attachment_id: wpMedia.id,
    sourceFormat,
    sizes,
  };
}

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes: number): string {
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  if (bytes < 1024 * 1024) {
    return `${(bytes / 1024).toFixed(1)} KB`;
  }
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}
