import type { ScriptManager } from './script-manager';
import type { StyleManager } from './style-manager';
import type { PreviewConfig, PreviewResource } from './types';

/**
 * Preview Content Generator
 * Generates the complete HTML content for the preview iframe
 */
export class PreviewContentGenerator {
  private styleManager: StyleManager;
  private scriptManager: ScriptManager;
  private externalResources: PreviewResource[] = [];

  constructor(styleManager: StyleManager, scriptManager: ScriptManager) {
    this.styleManager = styleManager;
    this.scriptManager = scriptManager;
  }

  /**
   * Add an external resource (script or stylesheet)
   */
  addExternalResource(resource: PreviewResource): void {
    this.externalResources.push(resource);
  }

  /**
   * Remove an external resource
   */
  removeExternalResource(resourceId: string): void {
    this.externalResources = this.externalResources.filter(
      (r) => r.id !== resourceId
    );
  }

  /**
   * Generate external resource tags
   */
  private generateExternalResources(): string {
    return this.externalResources
      .map((resource) => {
        const attrs = resource.attributes
          ? Object.entries(resource.attributes)
              .map(([key, value]) => `${key}="${value}"`)
              .join(' ')
          : '';

        switch (resource.type) {
          case 'script':
            return `<script ${attrs}>${resource.content}</script>`;
          case 'link':
            return `<link ${attrs} />`;
          case 'style':
            return `<style ${attrs}>${resource.content}</style>`;
          default:
            return '';
        }
      })
      .join('\n');
  }

  /**
   * Generate the complete HTML content
   */
  generate(config: PreviewConfig = {}): string {
    const {
      tailwindConfig = '',
      customStyles = [],
      customScripts = [],
    } = config;

    // Generate custom styles
    const customStyleTags = customStyles
      .map((style) => `<style>${style}</style>`)
      .join('\n');

    // Generate custom scripts
    const customScriptTags = customScripts
      .map((script) => `<script>${script}</script>`)
      .join('\n');

    // Get managed styles and scripts
    const managedStyles = this.styleManager.generateStyleTags();
    const managedScript = this.scriptManager.generateCombinedScript();

    return `<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <script src="https://cdn.tailwindcss.com"></script>
    ${tailwindConfig ? `<script>${tailwindConfig}</script>` : ''}
    ${this.generateExternalResources()}
    ${managedStyles}
    ${customStyleTags}
</head>
<body>
    <div id="preview-content"></div>
    <script>
        ${managedScript}
    </script>
    ${customScriptTags}
</body>
</html>`;
  }
}

/**
 * Default Tailwind CDN resource
 */
export const tailwindCDN: PreviewResource = {
  id: 'tailwind-cdn',
  type: 'script',
  content: '',
  attributes: {
    src: 'https://cdn.tailwindcss.com?plugins=forms,typography',
  },
};
